insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$0101$t$, $t$Absecon$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: City of Absecon Construction & Code Enforcement Office","Contact: Leigh Gadd, Code Enforcement Officer · 609-641-0663 ext. 113 · lgadd@abseconnj.org","Apply: Fees are payable before the inspection is scheduled; no minimum number of days is stated.","How to apply: Fill out the Application for a Certificate of Continued Occupancy (Code Enforcement page, Documents) and submit it with the fee to the Construction & Code Enforcement Office, 500 Mill Road, Absecon, NJ 08201. Fees are non-refundable and must be paid before the inspection is scheduled. Also file the Certification for Resale (smoke/CO/extinguisher) form.","Valid for: The application expires six months from the date received.","Inspection for compliance with the City property maintenance code (Chapter 266; the form cites the 1990 BOCA Property Maintenance Code)","Smoke alarms on every level (basement, first and second floors) and outside each separate sleeping area","Carbon monoxide alarms by every separate sleeping area","Portable fire extinguisher within 10 feet of the kitchen, in the exit path, visible, top no more than 5 feet above the floor, mounted on the maker's hanger or bracket","Extinguisher at least 2A:10B:C and no more than 10 lb, with owner's manual or instructions","Extinguisher serviced and tagged by a DCA-certified contractor within the past 12 months, or a recent purchase receipt"]$j$::jsonb, $j$[{"label":"CCO inspection, single-family residence (includes initial inspection and one re-inspection)","amount":"$75"},{"label":"Each additional re-inspection, starting with the third inspection (payable before scheduling)","amount":"$35"}]$j$::jsonb, $t$https://abseconnj.gov/wp-content/uploads/2026/06/Certificate-of-Continued-Occupancy-Application.pdf$t$, $t$https://abseconnj.gov/code-enforcement/$t$, $j$[{"url":"https://abseconnj.gov/code-enforcement/","label":"Official source (abseconnj.gov)"},{"url":"https://abseconnj.gov/wp-content/uploads/2026/06/Certificate-of-Continued-Occupancy-Application.pdf","label":"Official source (abseconnj.gov)"},{"url":"https://abseconnj.gov/construction/","label":"Official source (abseconnj.gov)"}]$j$::jsonb, $t$Chapter 160 of the Code of Absecon requires all properties having a change in owner, tenant or occupant receive a certificate of continuing occupancy stating the property is in compliance with the Chapter 266, property maintenance code. Residential properties must also comply with N.J.A.C.5:70-2.3 for smoke alarms, co alarms and fire extinguisher.$t$, $t$460bc177332606406ed70ede90b0c7a1b262b7318609b26be752c110a62de1b5$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":12,"q_ok":7,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0101.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0101.json$t$, true),
  ($t$0101$t$, $t$Absecon$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Absecon Construction & Code Enforcement Office (resale smoke/CO/extinguisher certification) (town fire bureau)","Contact: Leigh Gadd, Code Enforcement Officer · 609-641-0663 ext. 113 · lgadd@abseconnj.org","How to apply: Complete the Certification for Resale form (owner or authorized representative inspects and certifies), have it notarized, give the email address the certificate should go to, and submit it with the $75 fee to the City of Absecon Municipal Complex, 500 Mill Road (Code Enforcement, ext. 113).","Fire official in the NJ state directory, updated 2/6/2026: Tom Flynn · (609) 646-7382 · tflynn@abseconnj.org","Owner self-certification, signed before a notary, on the City's Certification for Resale form","Built 1978 and before: 10-year sealed battery smoke alarms on each level and outside each sleeping area","Built 1979 to 1987: AC-powered alarms near each sleeping area and in the basement, plus 10-year sealed battery alarms on each other level","Built 1987 to 1991: AC-powered, interconnected alarms on each level and outside each sleeping area","Built 1991 to present: AC-powered interconnected alarms with battery backup in all bedrooms, outside each sleeping area and on every level","Carbon monoxide alarm near the sleeping area(s), UL 2034 listed","Portable fire extinguisher, 2.5 to 10 lb ABC dry chemical, within 10 feet of the kitchen, mounted no higher than 5 feet and visible (2020 form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certification of Smoke Alarm, CO Alarm and Portable Fire Extinguisher Compliance (1-2 family)","amount":"$75"}]$j$::jsonb, $t$https://abseconnj.gov/wp-content/uploads/2026/06/Certification-for-Resale.pdf$t$, $t$https://abseconnj.gov/code-enforcement/$t$, $j$[{"url":"https://abseconnj.gov/wp-content/uploads/2026/06/Certification-for-Resale.pdf","label":"Official source (abseconnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://abseconnj.gov/fire-prevention/","label":"Official source (abseconnj.gov)"}]$j$::jsonb, $t$Application for One and Two Family Dwelling Certification of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance$t$, $t$86d584f0c99bad10c1ca91c8034df8b4c9628c3927ae4594115af25b49321600$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":12,"q_ok":7,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0101.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0101.json$t$, true),
  ($t$0102$t$, $t$Atlantic City$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Occupancy Permit (Certificate of Occupancy)$t$, $j$["Issued by: Atlantic City Department of Licensing & Inspections","Contact: Dale L. Finch, Director of Licensing & Inspections · 609-347-5290","How to apply: Apply online with the City's GovPilot Occupancy Permit Application (choose the Sale application type, give the closing date and buyer details, and attach the Certificate of Land Use, smoke certification and pest certification). Questions go to the Licensing & Inspection Department, City Hall, 1301 Bacharach Blvd., 5th Floor, Suite 502.","Certificate of Land Use (zoning) from Planning, (609) 347-5404, or the CRDA Tourism District, (609) 347-0500","Smoke certification from Fire Prevention (single-family or duplex)","Pest certification: report from a licensed exterminator that the unit is free of bed bugs, other insects and rodents","All utilities turned on for the inspection","No rubbish, debris or bulk garbage left on the property before the new occupancy","Buyer details (and all members or principals if the buyer is an LLC, corporation or partnership)","Also: Certificate of Land Use (zoning): Required attachment for the Occupancy Permit. Contact Planning, (609) 347-5404, or the CRDA Tourism District, (609) 347-0500.","Also: Pest certification: Certified examination report from a licensed exterminator that the unit is free of bed bugs, other insects and rodents; required attachment for the Occupancy Permit."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://main.govpilot.com/web/public/efeba3a1-0cd_Occupancy-Permit-Application-atlanticcity?uid=6910&ust=NJ&pu=1&id=0$t$, $t$https://www.acnj.gov/departments/licensing-and-inspection$t$, $j$[{"url":"https://www.ecode360.com/15210509","label":"Official source (ecode360.com)"},{"url":"https://main.govpilot.com/web/public/efeba3a1-0cd_Occupancy-Permit-Application-atlanticcity?uid=6910&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.acnj.gov/api/data/GetPageContactInfo?tag=Licensing%20%26%20Inspection","label":"Official source (acnj.gov)"}]$j$::jsonb, $t$The owner of any residential property shall obtain an occupancy permit prior to the sale of such property involving a new occupancy of any unit of dwelling space, provided that no occupancy permit shall be required for the sale of vacant properties, but shall be required prior to such time as a new occupancy occurs.$t$, $t$bd5bf8d8e690935ba1fd4c23cb69708bb74e8458aac179dda24c4c4c96364616$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":11,"q_bad":1,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0102.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0102.json$t$, true),
  ($t$0102$t$, $t$Atlantic City$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Atlantic City Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Kevin Munn, Fire Official (state fire directory) · 609-347-5595 · kmunn@acnj.gov","Apply: Fee depends on timing: 10 or more days, 4 to 10 days, or under 4 days before the change of occupant. The inspection is scheduled only after payment.","How to apply: Submit the City's online GovPilot Smoke Detector Application and attach the Smoke Certificate Affidavit, filled out and notarized. Pay by check to the City of Atlantic City, cash or money order. Fees are non-refundable and an inspection cannot be scheduled until payment is made. Office: City Hall, 1301 Bacharach Blvd, Room 130.","Fire official in the NJ state directory, updated 1/27/2026: Kevin Munn · (609) 347-5595 · kmunn@acnj.gov","Notarized owner affidavit (Smoke Certificate Affidavit) attached to the online application","10-year sealed battery smoke alarm on each level, including basements (not attic or crawl space)","Smoke alarm and CO alarm outside each separate sleeping area, within 10 feet of it","Existing AC-powered or interconnected alarms in homes built after January 1977 must be kept working","Portable fire extinguisher 2A-10B:C, no more than 10 lb, on a hanger within 10 feet of the kitchen (2020 affidavit still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 10 days before change of occupant (per unit)","amount":"$45"},{"label":"Smoke/CO certificate, 4 to 10 days before change of occupant (per unit)","amount":"$70"},{"label":"Smoke/CO certificate, less than 4 days before change of occupant (per unit)","amount":"$125"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/60ccced5-73b_Smoke-Detector-Application-atlanticcity?uid=6910&ust=NJ&pu=1&id=0$t$, $t$https://www.acnj.gov/departments/fire-prevention$t$, $j$[{"url":"https://main.govpilot.com/web/public/60ccced5-73b_Smoke-Detector-Application-atlanticcity?uid=6910&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.acnj.gov/_Content/pdf/forms/Smoke-Certificate-Affidavit.pdf","label":"Official source (acnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Compliance Certificate must be filled out, notarized and attached with this application.$t$, $t$0fd680593c0792d2209581f9235d13293edc7bdbd9372d78a8cac5a799f74517$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":11,"q_bad":1,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0102.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0102.json$t$, true),
  ($t$0106$t$, $t$Corbin City$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Corbin City. Confirm with the office if the buyer's lender or title company asks.","Contact: Alexander Bauer, Zoning Officer · 609-701-0203 · Zoning@corbincitynj.com","Also: Septic inspection: The Atlantic County Health Department may require a septic inspection; call (609) 645-5971 x4371 to verify.","Also: Private well test: The well must be tested under the state Private Well Testing Act through a third-party vendor."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://sites.google.com/view/corbincitynj/municipal-services/zoningconstruction$t$, $j$[{"url":"https://drive.google.com/uc?export=download&id=1YSBEuVwDPovVS3IY5l5guotF43xcQ8Ru","label":"Official source (drive.google.com)"},{"url":"https://sites.google.com/view/corbincitynj/municipal-services/city-clerk/forms","label":"Official source (sites.google.com)"},{"url":"https://sites.google.com/view/corbincitynj/municipal-services/zoningconstruction","label":"Official source (sites.google.com)"}]$j$::jsonb, $t$Selling Property: The city does not require any documentation or inspections to sell property.$t$, $t$1156c05cb9154c07291d87a8c97ee45637e596ec6e192b2a08ffb62c096aa449$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0106.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0106.json$t$, true),
  ($t$0106$t$, $t$Corbin City$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: Fee depends on how many business days before closing you apply (more than 10, 4 to 10, under 4).","How to apply: Apply online through the NJ DCA Fire Safety portal ('Start Your Smoke Certification Application'). Pay by e-check or credit card before submitting; a valid email address is required. The certificate is emailed once the application is submitted, the fee is paid and any required inspections are done. Homes heated by electricity with no CO alarm requirement should also email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 7/22/2026: Louis Kilmer · (609)633-6132","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"State smoke/CO certificate, applied more than 10 business days before closing","amount":"$45"},{"label":"State smoke/CO certificate, applied 4 to 10 business days before closing","amount":"$90"},{"label":"State smoke/CO certificate, closing less than 4 business days away","amount":"$161"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://drive.google.com/uc?export=download&id=1YSBEuVwDPovVS3IY5l5guotF43xcQ8Ru","label":"Official source (drive.google.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The smoke detector and/or carbon monoxide detector system must be inspected (CSDCMAC Certification) through the NJ Division of Fire Safety. You must schedule this inspection online at: https://firesolutions.dca.nj.gov/$t$, $t$4bc2b51026c0e92716b9ceadf62f73d2fa8d6d1de91101f1e9d4c945e8c25f9f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0106.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0106.json$t$, true),
  ($t$0107$t$, $t$Egg Harbor City$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Occupancy Transfer Certificate (Occupancy Transfer Inspection)$t$, $j$["Issued by: Egg Harbor City Building Department / Construction Office (Code Enforcement)","Contact: Donna Heffley, Land Use and Building Department Office Manager · 609-965-1616 · donnah@eggharborcity.org","How to apply: Download the Occupancy Transfer Inspection Form from Forms & Documents, mark it SALE, and submit it with the Smoke and Carbon Monoxide Alarm Certificate Application to the Egg Harbor City Construction Office, 500 London Ave., Egg Harbor City, NJ 08215. Pay with exact cash, money order or check made out to City of Egg Harbor City. Online payment is also possible through the City's WIPP portal (2.95% fee).","Occupancy Transfer Inspection of the home before the sale (the form covers a rental or a sale)","Submit the Smoke and Carbon Monoxide Alarm Certificate Application together with it","Give owner, purchaser, tenant and lock box details and the building type, bedrooms, heat, sewer/septic and water/well on the form"]$j$::jsonb, $j$[{"label":"Occupancy Transfer Inspection, per unit","amount":"$75.00"}]$j$::jsonb, $t$https://app.membershipware.com/api/blob/viewBlob?rf=t&i=rw1asl38m%252BrXS5Vw72pTaPeCCtbucN6tPpPtqA%2FZ3wOk67lJc0pLvULrgKxm9TvE$t$, $t$https://www.eggharborcity.org/building$t$, $j$[{"url":"https://app.membershipware.com/api/blob/viewBlob?rf=t&i=rw1asl38m%252BrXS5Vw72pTaPeCCtbucN6tPpPtqA%2FZ3wOk67lJc0pLvULrgKxm9TvE","label":"Official source (app.membershipware.com)"},{"url":"https://www.eggharborcity.org/formsanddocuments","label":"Official source (eggharborcity.org)"},{"url":"https://ecode360.com/8035021","label":"Official source (ecode360.com)"},{"url":"https://app.membershipware.com/api/public/mwjsPeople?et=DsEBpLP32xQDf9SDjaU%252BKg%3d%3d&eb=u32SQFY7Pxg4KbW4ofECYQ%3d%3d","label":"Official source (app.membershipware.com)"}]$j$::jsonb, $t$OCCUPANCY TRANSFER INSPECTION: RENTAL: _____ SALE: ______$t$, $t$d92e4cef5ab21c3724516e31aa084c4d085aa0f774dd0cccc55b97353312d674$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0107.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0107.json$t$, true),
  ($t$0107$t$, $t$Egg Harbor City$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Egg Harbor City Fire Official (Fire Marshal), Fire Prevention (town fire bureau)","Contact: Stephen Buchhofer, Fire Marshal (also Construction Official and Electric, Plumbing, Fire & Mechanical Subcode Official) · 609-965-0081 · EHCFirePrevention@eggharborcity.org","Apply: Fee depends on how many days before the Certificate of Occupancy must be issued: more than 10 days, 4 to 10 days, or fewer than 4 days. Inspections are available Tuesdays and Thursdays from 2 to 6 pm.","How to apply: Fill out the Certificate of Smoke Detector and Carbon Monoxide Alarm Inspection Request (Smoke and Carbon Monoxide Alarm Certificate Application on Forms & Documents) and submit it with the Occupancy Transfer Inspection form to the City, 500 London Ave. Questions: EHCFirePrevention@eggharborcity.org. After a failed reinspection the process starts over with a new fee.","Fire official in the NJ state directory, updated 1/27/2026: Stephen Buchhofer · (856) 656-5456 · swb6203@comcast.net","10-year sealed battery smoke alarm in every bedroom (depending on construction year)","Basement smoke alarm at the bottom of the stairwell at ceiling level (not between joists)","Hallway smoke alarms within 10 feet of all bedroom doors","Electric smoke alarms required by the building code cannot be replaced with battery alarms","Smoke detectors at least 3 feet from ceiling fan blade tips and air ducts; none in kitchens, bathrooms, dead air space, crawl spaces or attics","CO alarm in the hallway within 10 feet of all bedrooms; not plugged into a switched outlet","Fire extinguisher: residential 2A:10B:C, no larger than 10 lb, mounted within 10 feet of the kitchen (April 2026 form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO inspection, requested more than 10 days before the certificate is needed (per unit)","amount":"$55"},{"label":"Smoke/CO inspection, requested 4 to 10 days before the certificate is needed (per unit)","amount":"$90"},{"label":"Smoke/CO inspection, requested fewer than 4 days before the certificate is needed (per unit)","amount":"$160"},{"label":"First reinspection when more than one follow-up inspection is needed","amount":"$50"}]$j$::jsonb, $t$https://app.membershipware.com/api/blob/viewBlob?rf=t&i=mTuJlzExhzyqK3vbZ8XeAem7FEXaIzBDyP97NWQK82S%2FQ20zdH6b2vNSD%252BZxqSv7$t$, $t$https://www.eggharborcity.org/building$t$, $j$[{"url":"https://app.membershipware.com/api/blob/viewBlob?rf=t&i=mTuJlzExhzyqK3vbZ8XeAem7FEXaIzBDyP97NWQK82S%2FQ20zdH6b2vNSD%252BZxqSv7","label":"Official source (app.membershipware.com)"},{"url":"https://app.membershipware.com/api/public/mwjsPeople?et=DsEBpLP32xQDf9SDjaU%252BKg%3d%3d&eb=u32SQFY7Pxg4KbW4ofECYQ%3d%3d","label":"Official source (app.membershipware.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$City of Egg Harbor Fire Official EHCFireprevention@eggharborcity.org 500 London Ave Egg Harbor City, NJ 08215$t$, $t$91a294110363dd579e3ec6881eee2ca7cfea5856c81291afad10d243d08568d0$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0107.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0107.json$t$, true),
  ($t$0108$t$, $t$Egg Harbor Township$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Egg Harbor Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Pat J. Naticchione, Construction Official · 609-926-4122 · BuildingInspections@ehtnj.gov"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.ehtnj.gov/departments/planning___development/building_inspections.php$t$, $j$[{"url":"https://www.ehtnj.gov/community/forms.php","label":"Official source (ehtnj.gov)"},{"url":"https://www.ehtnj.gov/Building/Fillable%20CCO%20letter.pdf","label":"Official source (ehtnj.gov)"},{"url":"https://www.ehtnj.gov/departments/planning___development/building_inspections.php","label":"Official source (ehtnj.gov)"}]$j$::jsonb, $t$EHT does NOT require CCO Inspections for residential resales or rentals.$t$, $t$e5a6de5205e4642f5e2ed992f1bfc4d68c4ae6906d871e01c1ebe3a48e80e86f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0108.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0108.json$t$, true),
  ($t$0108$t$, $t$Egg Harbor Township$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Egg Harbor Township Bureau of Fire Inspections (town fire bureau)","Contact: Brian Cummings, Fire Official · 609-926-4070 · fireinspections@ehtnj.gov","Apply: Payments are not accepted after 4:15 pm.","How to apply: Download the 2025 smoke/CO affidavit from the Document Center (Fire Inspections). Either fill out the whole form as a notarized owner affidavit, or fill out only the top portion to request an on-site inspection. Submit it with the fee to the Bureau of Fire Inspections, 3515 Bargaintown Road, Egg Harbor Township, NJ 08234 (fax 609-926-4181).","Fire official in the NJ state directory (town), updated 9/2/2025: Brian D Cummings · (609) 926-4070 · Bcummings@ehtgov.org","Built 1978 and before: 10-year sealed battery smoke alarms on each level and outside each separate sleeping area","Built 1979 to 1987: hard-wired alarms near each sleeping area and in the basement; 10-year sealed battery alarms can be added for the other levels","Built 1988 to 1991: hard-wired, interconnected alarms on each level and outside each sleeping area","Built 1991 to present: hard-wired interconnected alarms with battery backup in all bedrooms, outside each sleeping area and on every level","Carbon monoxide alarm near the sleeping area(s), UL 2034 listed","Choice of a notarized owner affidavit or an on-site inspection request","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke Detector Application","amount":"$54.00"},{"label":"Second fee amount printed on the 2025 affidavit form (timing tier not labeled on the form)","amount":"$90"},{"label":"Third fee amount printed on the 2025 affidavit form (timing tier not labeled on the form)","amount":"$161"}]$j$::jsonb, $t$https://www.ehtnj.gov/Fire%20Inspection/2025affidavit9.9.25.pdf$t$, $t$https://www.ehtnj.gov/departments/planning___development/fire_inspections.php$t$, $j$[{"url":"https://www.ehtnj.gov/departments/planning___development/fire_inspections.php","label":"Official source (ehtnj.gov)"},{"url":"https://www.ehtnj.gov/Fire%20Inspection/2025affidavit9.9.25.pdf","label":"Official source (ehtnj.gov)"},{"url":"https://www.ehtnj.gov/Building/Fillable%20CCO%20letter.pdf","label":"Official source (ehtnj.gov)"},{"url":"https://www.ehtnj.gov/departments/planning___development/index.php","label":"Official source (ehtnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Official: Brian Cummings Fire Inspectors: Craig Thompson & Ray Conover Office Staff: Tammy Naylor, Clerk 1$t$, $t$c2c6b3fd06ab317ee442660317be593ed58a41f143aebaf51f205362ca19a42d$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0108.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0108.json$t$, true),
  ($t$0109$t$, $t$Estell Manor$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy - Sale (Housing Inspector's Certificate of Occupancy inspection)$t$, $j$["Issued by: City of Estell Manor Housing Inspector","Contact: Chase Farabella, Housing Inspector (also Zoning Officer and Code Enforcement) · 609-476-2692 ext. 104 · zoning@estellmanor.org","How to apply: Fill out the City's Certificate of Occupancy Application, tick 'Certificate of Occupancy - Sale', list the settlement date and a contact person to set up the appointment, and submit it to the Housing Inspector at 148 Cumberland Avenue, Estell Manor, NJ 08319 with the $50.00 fee payable to the City of Estell Manor. The smoke/CO certificate is a separate application through the NJ DCA portal."]$j$::jsonb, $j$[{"label":"Certificate of Occupancy inspection (sale or rental)","amount":"$50.00"}]$j$::jsonb, $t$http://www.estellmanor.org/images/new_co_chase.pdf$t$, $t$http://www.estellmanor.org/departments.html$t$, $j$[{"url":"http://www.estellmanor.org/images/new_co_chase.pdf","label":"Official source (estellmanor.org)"},{"url":"http://www.estellmanor.org/formslinks.html","label":"Official source (estellmanor.org)"},{"url":"http://www.estellmanor.org/contactus.html","label":"Official source (estellmanor.org)"},{"url":"http://www.estellmanor.org/departments.html","label":"Official source (estellmanor.org)"}]$j$::jsonb, $t$Request for: ( ) Certificate of Occupancy, Sale ( ) Certificate of Occupancy, Rental$t$, $t$6a69cd0a4ab1d88c13800d0f8d680932188c4735717df15c0902685878ba744e$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0109.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0109.json$t$, true),
  ($t$0109$t$, $t$Estell Manor$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6132 · BFCECodeAdmin@dca.nj.gov","Apply: More than 10 business days before closing for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety portal (Apply Smoke Certification). Pay by e-check or credit card before submitting; a valid email address is required. The City's instructions: complete the Smoke Cert data, submit, pay, and wait for the status 'Approved-Pending Inspection'. For help email BFCECodeAdmin@dca.nj.gov or call 609-633-6132.","Fire official in the NJ state directory (NJ DCA, state), updated 1/27/2026: Louis Kilmer · (609)633-6132","Secondary power source identification label for homes with solar, generators or batteries (the State application is now the CSACMASPSIL)","The City's CO form (August 2025) still describes the state certificate as covering a fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before closing","amount":"$45"},{"label":"4 to 10 business days before closing","amount":"$90"},{"label":"Less than 4 business days before closing","amount":"$161"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"http://www.estellmanor.org/images/new_co_chase.pdf","label":"Official source (estellmanor.org)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Estell Manor City$t$, $t$68bcfa3e47bc14dd06151cf4f4478ae1064cd9e2825d906e77b8463273a86e12$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0109.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0109.json$t$, true),
  ($t$0115$t$, $t$Longport Borough$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Land Use Compliance Certificate for a property sale (Certificate of Occupancy and/or Land Use Compliance Certificate)$t$, $j$["Issued by: Borough of Longport Building and Zoning Department","Contact: 609-823-2731 ext. 108, 109 or 120 · building@longport-nj.us","How to apply: Complete the 'Application for Land Use Compliance of a Property for Sale' (Housing section of the Borough forms page) with the settlement date, a point of contact and access details, and submit it with the $150.00 fee, a current site survey, a flood elevation certificate, the sales contract or proof of sale price, and Form 1A (smoke detector certificate) to the Building and Zoning Department, 2305 Atlantic Avenue, Longport, NJ 08403. The Building Department inspects and then issues the certificate.","Dwelling must comply with federal, state and local housing codes","Kept in a safe, sanitary condition with proper and adequate light and ventilation","Open permit review before the certificate is issued","Also: Current site survey: Required with the Land Use Compliance application for a sale.","Also: Flood elevation certificate: Required with the application.","Also: Sales contract, proof of sale price or interest conveyed: Required with the application.","Also: Open permit review: The office checks for open permits and sends a copy to the Tax Assessor."]$j$::jsonb, $j$[{"label":"Land Use Compliance application for a sale","amount":"$150.00"}]$j$::jsonb, $t$https://www.longportnj.gov/_Content/pdf/forms/Sale-Application.pdf$t$, $t$https://www.longportnj.gov/Departments/building-construction$t$, $j$[{"url":"https://www.longportnj.gov/_Content/pdf/forms/Sale-Application.pdf","label":"Official source (longportnj.gov)"},{"url":"https://www.longportnj.gov/api/data/GetFormsData","label":"Official source (longportnj.gov)"},{"url":"https://www.longportnj.gov/api/data/GetDirectoryDepartmentsData","label":"Official source (longportnj.gov)"}]$j$::jsonb, $t$A Certificate of Occupancy and/or Land Use Compliance Certificate will be issued following an inspection by the Building Department.$t$, $t$6c045ab3168dc787b10fea9ab90b878b977709a9ef0adc6d8b264d54fe89746e$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0115.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0115.json$t$, true),
  ($t$0115$t$, $t$Longport Borough$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Longport Bureau of Fire Prevention (town fire bureau)","Contact: Levon S Clayton, Fire Official (state fire directory) · 609-822-9578 · firechief@longport-nj.us","How to apply: Complete Form 1A (Application for Certificate of Smoke Detector Compliance) in the Borough sale packet and submit it with the Land Use Compliance application. Inspection by the Longport Fire Official, by appointment only. Pay by check only, payable to Longport Bureau of Fire Prevention; no certificate is issued before the fee is paid.","Fire official in the NJ state directory (town), updated 6/25/2026: Levon S Clayton · (609) 822-9578 · firechief@longport-nj.us","Smoke alarms on each level, in every bedroom, and outside each sleeping area within 10 feet of doorways","Since January 1, 2019: 10-year sealed lithium battery single-station smoke alarms; existing AC-powered alarms are accepted and must not be removed","Carbon monoxide alarms on each level and outside sleeping areas","Central-station monitored alarm systems must be inspected by a NJ certified fire protection contractor, with the report available at the fire inspection","Owner, agent or designee must be present; detectors mounted more than 9 feet up must be tested by the owner or agent","A penalty of up to $500.00 may apply if the sale closes before the certificate is received","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Smoke Detector Compliance application","amount":"$75.00"},{"label":"Each reinspection","amount":"$30.00"}]$j$::jsonb, $t$https://www.longportnj.gov/_Content/pdf/forms/Sale-Application.pdf$t$, $t$https://www.longportnj.gov/Departments/volunteer-fire-department$t$, $j$[{"url":"https://www.longportnj.gov/_Content/pdf/forms/Sale-Application.pdf","label":"Official source (longportnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Form “1A” to be completed in addition to the Land Use Compliance Form. Inspection conducted by the Longport Fire Official. Inspection conducted by appointment only. Additional Fee: $75.00 Payable to: Longport Bureau of Fire Prevention$t$, $t$987a1874a44fd79ecf8719395046b712b057727cfc770a2a33bd14e94403daaf$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0115.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0115.json$t$, true),
  ($t$0116$t$, $t$Margate City$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale / Land Use Certificate (Transfer of Title Certificate)$t$, $j$["Issued by: City of Margate City Department of Building Inspection (Construction Code Official)","Contact: Dino Cavalieri, Construction Official · 609-822-1974 · margate_inspection@margate-nj.com","Apply: Before closing","How to apply: Complete the Resale/Land Use Certificate Application (Title Transfers) with seller, agent and buyer details, the person to meet the inspector and the settlement date, and submit it with the $60.00 fee payable to the City of Margate (check, cash or card) to the Department of Building Inspection, 9001 Winchester Avenue, Margate City, NJ 08402. Then coordinate the inspection with the Building Department. Attach the Boca form for demolition or rehab if the buyer plans either.","Smoke alarms on each level, in every bedroom and outside each sleeping area within 10 feet of doorways","10-year sealed lithium battery smoke alarms (since January 1, 2019); existing AC-powered alarms accepted, do not remove","Carbon monoxide alarms on each level and outside sleeping areas","GFCI outlets at kitchen and bathroom counters, within 6 feet of a utility sink or wet bar, and in garages and outdoors","Portable fire extinguisher (2A-10B:C, 10 lb max) within 10 feet of the kitchen, on its bracket, top no higher than 5 feet, with the manual left for the new occupant","No open permits (checked by the office)","Also: Open permits: The resale application's office section records 'No Open Permits' or lists open permits and the date closed.","Also: Boca form for demolition or rehab: Attach the Boca Form for Demo or Boca Form for Rehab if the property will be demolished or rehabilitated."]$j$::jsonb, $j$[{"label":"Resale/Land Use Certificate application","amount":"$60.00"}]$j$::jsonb, $t$https://www.margate-nj.com/DocumentCenter/View/4584/2024-Application-for-Resale-Land-Use-Approval-Fillable$t$, $t$https://www.margate-nj.com/1253/Rentals-and-Resales-Housing-Forms-and-In$t$, $j$[{"url":"https://www.margate-nj.com/1253/Rentals-and-Resales-Housing-Forms-and-In","label":"Official source (margate-nj.com)"},{"url":"https://www.margate-nj.com/DocumentCenter/View/4584/2024-Application-for-Resale-Land-Use-Approval-Fillable","label":"Official source (margate-nj.com)"},{"url":"https://www.margate-nj.com/1202/ConstructionBuilding-Department","label":"Official source (margate-nj.com)"},{"url":"https://www.margate-nj.com/DocumentCenter/View/4755/Housing-Rental-and-Resale-Inspection-Requirements","label":"Official source (margate-nj.com)"}]$j$::jsonb, $t$Transfers of Title Certificates: To purchase or sell a property, a Land Use Certificate application must be completed before closing.$t$, $t$56e44581015fe076345fc8c7a7925468ef4e0e33dde8f7255e7cf73c40a08586$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":14,"q_ok":10,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0116.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0116.json$t$, true),
  ($t$0116$t$, $t$Margate City$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Margate City Department of Building Inspection (smoke detector compliance) / Margate City Fire Department (fire code enforcing agency) (town fire bureau)","Contact: Pat Baker, Fire Inspector (Building Department) · 609-822-2605 ext. 127 · margate_inspection@margate-nj.com","How to apply: The smoke, CO and extinguisher items are checked in the Building Department's rental and resale housing inspection. No separate smoke/CO certificate application or fee was found online; ask the Department of Building Inspection (609-822-1974) whether the $60.00 Resale/Land Use Certificate covers it.","Fire official in the NJ state directory, updated 5/26/2026: Daniel Adams · (609) 822-1974 · adams_dan@margate-nj.com","Smoke alarms on each level, in every bedroom and outside each sleeping area within 10 feet of doorways","10-year sealed lithium battery single-station smoke alarms since January 1, 2019; existing AC-powered alarms stay","Carbon monoxide alarms on each level and outside sleeping areas","Portable fire extinguisher 2A-10B:C, no more than 10 lb, within 10 feet of the kitchen in a path of egress, mounted on its bracket with the top no more than 5 feet above the floor; owner's manual left for the new occupant (August 2024 checklist)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.margate-nj.com/1202/ConstructionBuilding-Department$t$, $j$[{"url":"https://www.margate-nj.com/1202/ConstructionBuilding-Department","label":"Official source (margate-nj.com)"},{"url":"https://www.margate-nj.com/DocumentCenter/View/4755/Housing-Rental-and-Resale-Inspection-Requirements","label":"Official source (margate-nj.com)"},{"url":"https://www.margate-nj.com/1333/Fire","label":"Official source (margate-nj.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Pat Baker Fire Inspector 609-822-2605, ext. 127$t$, $t$6df38586584b3710bc87a7ad4ee785ff1f86f38a53360bd0eb4c75d1acb7d4b0$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":14,"q_ok":10,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0116.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0116.json$t$, true),
  ($t$0117$t$, $t$Mullica Township$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate$t$, $j$["Issued by: Zoning and Code Enforcement Office (Zoning Officer / Code Enforcement Official)","Contact: Steven Hadley, Zoning Officer / Code Enforcement Official · 609-561-7070 x 133 · zoning@mullicatownship.org","How to apply: Download the Resale Certificate Application from the Township Forms page ('RESALE APPLICATION'). Fill in block, lot, property address, lock box number and location, homeowner, buyer and realtor details, and return it with the $75.00 fee (the office section lists cash or check), a copy of approved well and septic testing and, in a flood zone, the elevation certificate. The form does not say whether to mail, email or drop it off, so ask the office (609-561-7070 x 133, zoning@mullicatownship.org). The Township then schedules the inspection. The Zoning and Code Enforcement Officer works Tuesday, Wednesday and Thursday, 8:30 am to 4 pm; an appointment is recommended.","Copy of approved well and septic testing submitted with the application","Copy of the elevation certificate if the home is in a flood zone","The Township inspects the home and marks the resale certificate passed or failed (inspection checklist not published)","Also: Well and septic test results: A copy of approved well and septic testing is needed to process the resale certificate.","Also: Flood zone elevation certificate: A copy of the elevation certificate is needed if the home is in a flood zone.","Also: Construction permits: Since February 9, 2026 the Uniform Construction Code in Mullica is enforced by the NJ DCA Southern Regional Office (DCA SRO contact 609 567-3653), so open construction permits are handled there."]$j$::jsonb, $j$[{"label":"Resale certificate application","amount":"$75.00"}]$j$::jsonb, $t$https://mullicatownship.org/wp-content/uploads/2026/03/RESALE-certificate-application-NEW.pdf$t$, $t$https://www.mullicatownship.org/departments/development-housing/code-enforcement/$t$, $j$[{"url":"https://mullicatownship.org/wp-content/uploads/2026/03/RESALE-certificate-application-NEW.pdf","label":"Official source (mullicatownship.org)"},{"url":"https://www.mullicatownship.org/forms/","label":"Official source (mullicatownship.org)"},{"url":"https://www.mullicatownship.org/departments/development-housing/code-enforcement/","label":"Official source (mullicatownship.org)"}]$j$::jsonb, $t$RESALE CERTIFICATE APPLICATION ... THE FOLLOWING INFORMATION WILL BE NEEDED TO PROCESS THE RESALE CERTIFICATE 1. COPY OF APPROVED WELL & SEPTIC TESTING 2. COPY OF ELEVATION CERTIFICATE IN FLOOD ZONE 4. APPLICATION FEE $75.00$t$, $t$8c8757287906916e59ac103cb65e7d07a06588e2af88393854fc057377c947e4$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0117.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0117.json$t$, true),
  ($t$0117$t$, $t$Mullica Township$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: More than 10 business days before closing for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety portal ('Start Your Smoke Certification Application'). Pay by e-check or credit card before submitting; a valid email address is required. The certificate is emailed once the application is submitted, the fee is paid and any required inspections are done. Homes heated by electricity with no CO alarm requirement should also email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 2/6/2026: Louis Kilmer · (609)633-6132","State online self-certification, now named the Certificate of Smoke Alarm, Carbon Monoxide Alarm, and Secondary Power Source Identification Label Compliance (CSACMASPSIL): smoke alarms, carbon monoxide alarms, and the secondary power source label for homes with solar, generators or batteries. The certificate name no longer includes the fire extinguisher, although the portal's checklist notice still refers to detectors and fire extinguishers","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before closing","amount":"$45"},{"label":"4 to 10 business days before closing","amount":"$90"},{"label":"Less than 4 business days before closing","amount":"$161"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Mullica Township$t$, $t$deda903bfa96bc2f187584eea1dd2ab773a37b829650579afdf537d0aa201e6a$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0117.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0117.json$t$, true),
  ($t$0118$t$, $t$Northfield$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance for the Resale of One and Two Family Dwellings (CCO)$t$, $j$["Issued by: Housing Officer (City Housing and Zoning office)","Contact: 609-641-2832 ext 140 · housing@cityofnorthfield.org","Apply: Inspections are made within 10 business days of the application. If settlement is 5 days or less from the application, the City does not guarantee an inspection before closing and an extra $10 fee may apply.","How to apply: Download the 'Application for Certificate of Compliance for Residential Resale (CCO)' packet from the City Forms page, fill in block, lot, settlement date, year built, seller, agent and buyer, and give it to the Housing Officer, City Hall, 1600 Shore Road, with the $85.00 non-refundable fee (checks payable to the City of Northfield) and the heating certification for oil or gas heat. Inspections are scheduled for Mondays only by calling 609-641-2832 ext 140. If repairs are still open at closing, the buyer can sign the notarized 'Resale Certification of As-Is Conditions' form; the home cannot be occupied until a re-inspection passes and the Certificate of Compliance is issued.","Smoke alarms and carbon monoxide alarms in good working order, placed by the year the home was built (see fire certificate)","Portable ABC fire extinguisher near the kitchen (see fire certificate)","Heating certification for every oil or gas fired heating unit, from a NJ licensed plumber or HVAC contractor","Sidewalks, walkways, stairs, driveways and parking areas in good repair","Yard free of weeds and overgrowth; garages, fences and other accessory structures sound","Pools clean; pools, hot tubs and spas over 24 inches deep fenced at least 48 inches high with self-closing, self-latching gates","Exterior wood painted or protected; house number plainly visible from the street","Roof, flashing, gutters and downspouts sound and draining properly","Windows that open can be held open; every habitable room has at least one openable window","Interior in good repair, sanitary, and free of rubbish or garbage","Bathroom window or mechanical exhaust vented outdoors","Heat provided; at least two outlets in each habitable room, a bathroom outlet, a laundry outlet, cover plates on all outlets, GFCI protection within 4 feet of water (if remodeled)","Fences, decks, sheds, pools and similar items built without zoning or construction permits delay the certificate until corrected","Also: Heating certification: Required for all oil and gas fired heating units, from a NJ licensed plumber or HVAC contractor.","Also: Unpermitted structures: Any fence, deck, shed, pool or similar item installed without zoning or construction permits delays the Certificate of Compliance until corrected or abated.","Also: Buying as-is: The buyer can sign a notarized Resale Certification of As-Is Conditions agreeing to make the repairs on the Conditional Certificate of Compliance; no occupancy until a re-inspection passes and the Certificate of Compliance is issued."]$j$::jsonb, $j$[{"label":"Resale CCO application and inspection, non-refundable","amount":"$85.00"},{"label":"Re-inspection due to violations","amount":"$25.00"},{"label":"Settlement 5 days or less after application (may apply)","amount":"$10"}]$j$::jsonb, $t$https://www.cityofnorthfield.org/pdf/RESALE-property-inspection-registration-packet-2026.pdf$t$, $t$https://www.cityofnorthfield.org/government/zoning.asp$t$, $j$[{"url":"https://www.cityofnorthfield.org/pdf/RESALE-property-inspection-registration-packet-2026.pdf","label":"Official source (cityofnorthfield.org)"},{"url":"https://www.cityofnorthfield.org/government/zoning.asp","label":"Official source (cityofnorthfield.org)"},{"url":"https://www.cityofnorthfield.org/pdf/Residential%20resale%20-%20certification%20of%20'as%20is'%20conditions.pdf","label":"Official source (cityofnorthfield.org)"},{"url":"https://www.cityofnorthfield.org/main/forms.asp","label":"Official source (cityofnorthfield.org)"}]$j$::jsonb, $t$APPLICATION FOR CERTIFICATE OF COMPLIANCE FOR THE RESALE OF ONE AND TWO FAMILY DWELLINGS (CCO)$t$, $t$a40655c36c3fecdbeed97f3591f7b422123c9273b555ddd4c666875e38e18993$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":3,"fee_bad":0,"fee_unchecked":3,"quotes":14,"q_ok":12,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0118.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0118.json$t$, true),
  ($t$0118$t$, $t$Northfield$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: More than 10 business days before closing for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety portal ('Start Your Smoke Certification Application'). Pay by e-check or credit card before submitting; a valid email address is required. The certificate is emailed once the application is submitted, the fee is paid and any required inspections are done. Homes heated by electricity with no CO alarm requirement should also email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 5/29/2025: Louis Kilmer · (609) 633-6132","Smoke alarms by year built (City packet): before 1977 battery alarm on each level and within 10 feet of bedrooms; 1977 onward A/C powered (hardwired) alarms; interconnected alarms from August 1984; from March 1991 A/C powered with battery backup on each level and inside each bedroom","Ten-year sealed battery single station smoke alarms where no alarms exist or when replacing battery alarms; hardwired alarms from original construction or a rehab project may not be replaced with battery alarms","Replace smoke alarms 10 years from manufacture or when they fail tests; replace combination smoke/CO alarms at the end-of-life signal or 10 years","Carbon monoxide alarm within 10 feet of bedroom doors; bedrooms with fuel burning appliances also need a CO alarm","Portable fire extinguisher (City packet dated July 2026 still lists it): minimum 2A-10B:C, no more than 10 pounds, within 10 feet of the kitchen in the path of egress, mounted with the manufacturer's bracket with the top no more than 5 feet above the floor, serviced and tagged by a DFS-certified contractor within 12 months or a recent purchase receipt, with the owner's manual left for the new occupant","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before closing","amount":"$45"},{"label":"4 to 10 business days before closing","amount":"$90"},{"label":"Less than 4 business days before closing","amount":"$161"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Northfield City Fire Prev Northfield City Bldg Dept$t$, $t$b40887b7dd767cae285659c81fdcfe239ef75008f8a8d95009ee72a69764da28$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":3,"fee_bad":0,"fee_unchecked":3,"quotes":14,"q_ok":12,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0118.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0118.json$t$, true),
  ($t$0119$t$, $t$Pleasantville$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (Occupancy Permit, Change of Ownership) or Transfer of Ownership Permit$t$, $j$["Issued by: Code Enforcement Department (Housing Division)","Contact: Ben Silkowitz, Construction/Zoning Official (Code Enforcement / Housing Division phone listed) · 609-484-3633","Apply: All applications take 7 to 10 business days for processing and inspection dates.","How to apply: Download the Certificate of Occupancy packet from the City Forms page and complete the 'Occupancy Permit/Transfer of Ownership Permit' application (check 'Occupancy Permit - Change of Ownership', or 'Transfer of Ownership Permit' if the buyer will fix violations). Submit it to Code Enforcement (City Hall Annex, 132 West Washington Avenue; mailing address 18 N. First Street) with the $60 fee by check or money order payable to City of Pleasantville (no cash), plus the fire safety and heat/hot water certificates. A Transfer of Ownership Permit needs a signed, notarized statement from the new owner and does not allow occupancy. Inspectors take scheduling calls from 8:30 to 9:30 am and 4:00 to 4:30 pm.","Fire safety certificate (smoke alarms, CO alarms) from the Pleasantville Fire Department","Heat and hot water heater certificate from a licensed plumber or HVAC technician (electric units do not need one)","Fireplace certification if there is one: gas units by an HVAC technician or plumber, wood burning fireplaces by a licensed chimney sweep","All utilities on at the time of inspection","Home fit for habitation under the City Property Maintenance Code: no fire or accident hazards, adequate ventilation, light and sanitary facilities, no dilapidation, disrepair, structural defects or uncleanliness","Buyers using an LLC must give the owner's or property caregiver's name and contact information","Also: Heat and hot water heater certificate: From any licensed plumber or HVAC technician; electric units do not need certification.","Also: Fireplace certification: If there is a fireplace: gas units by an HVAC technician or plumber, wood burning fireplaces by a licensed chimney sweep.","Also: Utilities on: All utilities must be on at inspection or the inspection is aborted and a $50 re-inspection fee applies."]$j$::jsonb, $j$[{"label":"Residential application (Occupancy Permit or Transfer of Ownership Permit), non-refundable","amount":"$60.00"},{"label":"Re-inspection, each","amount":"$50.00"},{"label":"Late cancellation (after 4:00 pm the day before)","amount":"$50.00"},{"label":"Inspection aborted because utilities are off","amount":"$50"},{"label":"Reprint after a name change within 5 days of printing","amount":"$2.00"}]$j$::jsonb, $t$https://www.pleasantville-nj.org/pdf/Certificate%20of%20Occupancy%20Form%20November%202023.pdf$t$, $t$https://www.pleasantville-nj.org/page.asp?var_incl=building.html$t$, $j$[{"url":"https://www.pleasantville-nj.org/pdf/Certificate%20of%20Occupancy%20Form%20November%202023.pdf","label":"Official source (pleasantville-nj.org)"},{"url":"https://www.pleasantville-nj.org/services/fire.asp","label":"Official source (pleasantville-nj.org)"},{"url":"https://www.pleasantville-nj.org/page.asp?var_incl=building.html","label":"Official source (pleasantville-nj.org)"},{"url":"https://www.pleasantville-nj.org/page.asp?var_incl=officials.html","label":"Official source (pleasantville-nj.org)"},{"url":"https://www.pleasantville-nj.org/government/forms.asp","label":"Official source (pleasantville-nj.org)"}]$j$::jsonb, $t$The City of Pleasantville requires a Certificate of Occupancy and a Yearly Rental Registration Certificate prior to occupancy of any rental property or sale of property.$t$, $t$af8eb94d126830423e6dcec863238537b284bed3d6ee01221c9a5ba34be39149$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":3,"fee_bad":0,"fee_unchecked":5,"quotes":17,"q_ok":14,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0119.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0119.json$t$, true),
  ($t$0119$t$, $t$Pleasantville$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Pleasantville Fire Department, Office of Fire Prevention (Fire Prevention Bureau) (town fire bureau)","Contact: Anton Brown, Captain, Fire Official (Fire Prevention/Investigations) · 609-569-2042 · prevention@pleasantvillefd.net","Apply: Inspections are on Mondays and Wednesdays; the expedited fee gets a same or next business day inspection. Cancel at least 48 hours before the inspection.","How to apply: Complete the Application for Certification of Smoke Detector, Carbon Monoxide Detector, Portable Fire Extinguisher Compliance (check 'Sale') and bring it to the Office of Fire Prevention inside the Fire Department, 1 N. First Street (1st Street side door), 8:30 am to 4:30 pm on weekdays. Pay by check or money order payable to the City of Pleasantville; fees are non-refundable and mail-ins are not accepted.","Fire official in the NJ state directory, updated 5/26/2026: Anton Brown · (609) 484-3670 · Abrown@pleasantvillefd.net","Homes built before April 4, 1991: smoke alarm on each level including the basement (not attic or crawl space) and near each separate sleeping area","Homes built after April 4, 1991: smoke alarm on each level and in each bedroom, 110-volt interconnected with battery backup","Battery smoke alarms must be 10-year sealed (hardwired alarms excluded)","Carbon monoxide alarms in the immediate vicinity of the sleeping areas","Portable fire extinguisher: the 2025 application says it is required for multi-family properties only (excluding one- and two-family homes), 2.5 to 10 lb ABC dry chemical, mounted within 10 feet of the kitchen. The Fire Department web page still says extinguishers are required in 1, 2 and 3 family dwellings.","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate application, non-refundable","amount":"$60"},{"label":"Expedited, same or next business day","amount":"$160"},{"label":"Duplicate certificate, each","amount":"$10.00"}]$j$::jsonb, $t$https://www.pleasantville-nj.org/pdf/Smoke%20Detector%20Carbon%20Monoxide%20Detector%20Fire%20Extinguisher%20Certification%20Application%20-%202025.pdf$t$, $t$https://www.pleasantville-nj.org/services/fire.asp$t$, $j$[{"url":"https://www.pleasantville-nj.org/pdf/Smoke%20Detector%20Carbon%20Monoxide%20Detector%20Fire%20Extinguisher%20Certification%20Application%20-%202025.pdf","label":"Official source (pleasantville-nj.org)"},{"url":"https://www.pleasantville-nj.org/services/fire.asp","label":"Official source (pleasantville-nj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$OFFICE: 609-569-2042$t$, $t$467c194f924c6197411322e61635f5cec2b21d9d19419494389d683a9e9a6844$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":3,"fee_bad":0,"fee_unchecked":5,"quotes":17,"q_ok":14,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0119.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0119.json$t$, true),
  ($t$0121$t$, $t$Somers Point$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Land/Structure Compliance (Certificate of Occupancy) inspection$t$, $j$["Issued by: Construction, Zoning and Code Enforcement Office (Dept. of Construction Enforcement)","Contact: Mark McCrane, Construction Official (Construction/Zoning Official) · 609-927-9088 x142 · mmccrane@spgov.org","How to apply: Fill out the Land/Structure Compliance Application (posted as 'Application Certificate of Occupancy' on the Construction, Zoning & Code Enforcement page) with the property use, occupancy, lockbox code, seller, agent, buyer, settlement date and whether the home will be rented, and submit it with the fee to the Construction Office (the form lists City Hall, 1 W. New Jersey Avenue; the web page lists 741 Shore Road), 9:00 am to 5:00 pm weekdays. The office-use section takes cash or check and records any open permits.","Walks and driveways free of trip hazards","Yard free of weeds and debris, grass cut","House number at least 4 inches high, visible from the street","Paint not peeling or cracking, no untreated wood exposed","Service entry cable, gutters, downspouts, decks, steps and building exterior (foundation, walls, roof, glazing, basement hatch) in good condition; 3 or more risers need a graspable rail","Floor coverings without trip hazards; walls and ceilings in good condition","Smoke alarm within 10 feet of bedrooms and on every level including the basement; CO alarm within 10 feet of all sleeping rooms","Fire extinguisher 2A:10B:C, 10 lb maximum, mounted in the kitchen, visible and readily accessible, top no more than 5 feet above the floor","Graspable rails on all stairs including the basement","Bathrooms have an operable window or a fan exhausting outside","GFCI protection on outlets within 6 feet of a sink and in the garage, basement and outside","A light fixture in every hallway, interior stairway, bathroom, kitchen, laundry room, boiler or furnace room and basement","Plumbing fixtures working with hot and cold water and no visible leaks; water heater relief valve discharge within 6 inches of the floor","Gas appliances vented with combustion air and clearances; dryer vented outside with metal flex duct; washer drains to the drain system","Door locks meet code (no double keyed locks); at least one insect screen in every room","Also: Open permits: The office-use section of the application records open permits for the property."]$j$::jsonb, $j$[{"label":"Inspection, per dwelling unit","amount":"$250.00"},{"label":"Reinspection, each","amount":"$100.00"},{"label":"Reinspection appointment when smoke/CO alarms or extinguisher fail (older notice on page 2 of the same form, dated 2007)","amount":"$15"}]$j$::jsonb, $t$https://www.somerspointgov.org/pdfs/LAND%20STRUCTURE%20COMPLIANCE_0001.pdf$t$, $t$https://www.somerspointgov.org/mainpages/construction.asp$t$, $j$[{"url":"https://www.somerspointgov.org/pdfs/LAND%20STRUCTURE%20COMPLIANCE_0001.pdf","label":"Official source (somerspointgov.org)"},{"url":"https://www.somerspointgov.org/mainpages/construction.asp","label":"Official source (somerspointgov.org)"}]$j$::jsonb, $t$LAND/STRUCTURE COMPLIANCE APPLICATION FEE: $250.00 PER DWELLING UNIT Reinspection fee $100.00 per reinspection ... SELLER: ... BUYER: ... SETTLEMENT DATE:$t$, $t$fbde9b073c3817c743e22c62a5a6c25b7749837f37f7ef55b123b6fdc155f7de$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0121.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0121.json$t$, true),
  ($t$0121$t$, $t$Somers Point$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: More than 10 business days before closing for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety portal ('Start Your Smoke Certification Application'). Pay by e-check or credit card before submitting; a valid email address is required. The certificate is emailed once the application is submitted, the fee is paid and any required inspections are done. Homes heated by electricity with no CO alarm requirement should also email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 8/12/2025: Louis Kilmer · (609) 633-6132","State online self-certification, now named the Certificate of Smoke Alarm, Carbon Monoxide Alarm, and Secondary Power Source Identification Label Compliance (CSACMASPSIL): smoke alarms, carbon monoxide alarms, and the secondary power source label for homes with solar, generators or batteries. The certificate name no longer includes the fire extinguisher, although the portal's checklist notice still refers to detectors and fire extinguishers","The City's resale inspection form (2023) also checks smoke alarms, CO alarms and a 2A:10B:C extinguisher of 10 lb or less mounted to the kitchen wall, and notes 10-year sealed lithium battery smoke alarms have been required since 1/1/2019 (existing hardwired alarms excepted)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before closing","amount":"$45"},{"label":"4 to 10 business days before closing","amount":"$90"},{"label":"Less than 4 business days before closing","amount":"$161"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://www.somerspointgov.org/mainpages/fire_inspect.asp","label":"Official source (somerspointgov.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The City no longer maintains a Bureau of Fire Prevention and Inspection. This service is currently provided by the State of New Jersey.$t$, $t$c6cc438350a19e7f9bc5bef446a47afc5f5f468be05334287b3ea6ef82b0cf52$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0121.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0121.json$t$, true),
  ($t$0122$t$, $t$Ventnor City$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Sale Certificate of Occupancy and Certificate of Land Use Compliance$t$, $j$["Issued by: Code Enforcement / Building Department (Housing)","Contact: Dino Cavalieri, Code/Construction Official · 609-823-7987 · dcavalie@ventnorcity.org","How to apply: Submit two forms from the Housing page to the Building / Code Enforcement Department, City Hall, 6201 Atlantic Avenue: the Sale Certificate of Occupancy Application (buyer, agent, proposed settlement date, whether smoke detectors are monitored, and the adults and children who will live in each unit) and the Application Certificate of Land Use Compliance (seller, property, zoning and use). A Certificate of Occupancy is needed per unit. Pay when the inspection is scheduled (cash, check or card). Housing inspections run Monday to Friday, 9:30 am to 1 pm, every half hour. The Housing page also posts a Rental-Sale Affidavit and a 'Conditional Letter - Unoccupied' form.","Curb and sidewalk free of trip hazards","House address posted","All railings and spindles in place (36 inch rail height)","Grass cut","Window screens in place from May 15 to October 1","ABC fire extinguisher with the gauge in the green (required for sales)","Smoke alarms in each bedroom, on each level and within 10 feet of all bedrooms; CO alarm on each sleeping floor and near any major gas appliance","If smoke detectors are monitored, a certificate from the alarm company","Dryer vented to the exterior","Electric on and appliances working","Two outlets in each bedroom; bathroom outlet plus a fan or exhaust window","Water heater pressure relief valve discharge checked","Blanks in the electric panel","Unit clean: no mold in tub, clean rugs, no chipping paint","Also: Certificate of Land Use Compliance: A separate Land Use application (seller, property, zoning classification and use) is needed with the Sale CO.","Also: Alarm company certificate: If smoke detectors are monitored, a certificate from the alarm company is required."]$j$::jsonb, $j$[{"label":"Sale Certificate of Occupancy, non-refundable (form updated 4/11/25)","amount":"$100"},{"label":"Certificate of Land Use Compliance","amount":"$100.00"},{"label":"Each form, per Code Enforcement FAQ (older figure; conflicts with the current forms)","amount":"$50.00"}]$j$::jsonb, $t$https://www.ventnorcity.org/media/Documents/CodeEnforcement/SALE%201.26.pdf$t$, $t$https://www.ventnorcity.org/departments/CodeEnforcement/housing$t$, $j$[{"url":"https://ventnorcity.org/departments/CodeEnforcement/code-enforcement-faq","label":"Official source (ventnorcity.org)"},{"url":"https://www.ventnorcity.org/media/Documents/CodeEnforcement/SALE%201.26.pdf","label":"Official source (ventnorcity.org)"},{"url":"https://www.ventnorcity.org/media/Documents/CodeEnforcement/LAND%201.26.pdf","label":"Official source (ventnorcity.org)"},{"url":"https://www.ventnorcity.org/departments/staff_directory/CodeEnforcement/","label":"Official source (ventnorcity.org)"}]$j$::jsonb, $t$What paperwork is needed to sell a home? In order to sell your home you will need a Land Use and Sale Certificate of Occupancy (per unit). Each form is $50.00 due at the time of scheduling.$t$, $t$14a4c16129c23cfb1eab549d7ebdaeb3764cbdee94ac39bf7f3b698886ece305$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":1,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":10,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0122.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0122.json$t$, true),
  ($t$0122$t$, $t$Ventnor City$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Ventnor City Building / Code Enforcement Department (smoke, CO and extinguisher check within the Sale Certificate of Occupancy) (town fire bureau)","Contact: Dino Cavalieri, Code/Construction Official · 609-823-7987 · dcavalie@ventnorcity.org","How to apply: No separate smoke certificate application or fee was found. The City's Certificate of Occupancy requirements letter says smoke alarms, CO alarms and portable fire extinguishers are required before any Certificate of Occupancy is issued, and the state fire directory lists the Ventnor City Building Department for smoke detector compliance, so the check is made during the Sale Certificate of Occupancy inspection.","Fire official in the NJ state directory, updated 5/26/2026: Joseph Iannuzzelli · (609) 823-7943 · jiannuzzelli@ventnorcity.org","Smoke alarms: one in each bedroom, one on each level, and one within 10 feet of all bedrooms (battery or hardwired accepted)","Carbon monoxide alarm on each sleeping floor and near any major gas burning appliance, per the manufacturer's instructions","Portable fire extinguisher, required for sales only: ABC type, no larger than 10 pounds, mounted within 10 feet of the kitchen, gauge in the green (City letter, 2008 scan, and current FAQ)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.ventnorcity.org/media/Documents/CodeEnforcement/SALE%201.26.pdf$t$, $t$https://www.ventnorcity.org/departments/CodeEnforcement/housing$t$, $j$[{"url":"http://www.ventnorcity.org/media/Documents/CodeEnforcement/FillableForms/CERTIFICATE%20OF%20OCCUPANCY%20REQUIREMENTS.pdf","label":"Official source (ventnorcity.org)"},{"url":"https://ventnorcity.org/departments/CodeEnforcement/code-enforcement-faq","label":"Official source (ventnorcity.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.ventnorcity.org/departments/Fire/fire-prevention","label":"Official source (ventnorcity.org)"}]$j$::jsonb, $t$are now required prior to the issuance of any Certificate of Occupancy under the Uniform Construction Code Act 52:27D-133.3.$t$, $t$c9351c019ec08baab3a5e745d16c85ee23a2bd6ee70229224ecfb0fe0fc43d0b$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":1,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":10,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0122.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0122.json$t$, true),
  ($t$0123$t$, $t$Weymouth Township$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy - Sale$t$, $j$["Issued by: Housing Office (Housing Officer)","Contact: Chase Farabella, Housing Officer · 609-476-2633 ext 3 · housing@weymouthnj.org","Apply: The Housing Officer inspects within 14 days of receiving the completed application and payment.","How to apply: Complete the Application for Certificate of Occupancy (check 'Certificate of Occupancy - Sale'; give block, lot, settlement date, owner and the contact person for the inspection appointment) and return it with the $50.00 inspection fee to the Housing Officer, 45 South Jersey Avenue, Dorothy, NJ 08317. The Housing Officer inspects within 14 days. Separately get the NJ DCA smoke/CO certificate online; the Township will not issue the CO until it receives it.","The Township will not issue the CO until it receives a valid NJ DCA Division of Fire Safety smoke alarm, carbon monoxide alarm and portable fire extinguisher certificate","Housing Officer inspection of the home (checklist not published)","Also: NJ DCA smoke/CO certificate before the Township CO: The Township CO is not issued until the Township receives the DCA smoke/CO certificate."]$j$::jsonb, $j$[{"label":"Certificate of Occupancy - Sale inspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.weymouthnj.org/Document%20Center/Forms%20and%20Documents/Housing%20Forms/CO-Application-8-2026%20updated.pdf$t$, $t$https://www.weymouthnj.org/township_offices/housing_office/index.php$t$, $j$[{"url":"https://www.weymouthnj.org/Document%20Center/Forms%20and%20Documents/Housing%20Forms/CO-Application-8-2026%20updated.pdf","label":"Official source (weymouthnj.org)"},{"url":"https://www.weymouthnj.org/Document%20Center/Forms%20and%20Documents/Housing%20Forms/DCA-Smoke-Detector-info-08-2026.pdf","label":"Official source (weymouthnj.org)"},{"url":"https://www.weymouthnj.org/township_offices/housing_office/index.php","label":"Official source (weymouthnj.org)"}]$j$::jsonb, $t$Request for ( ) Certificate of Occupancy - Sale ( ) Certificate of Occupancy - Rental$t$, $t$22540549d3990154dfd164f79c4f5fbc9cf2b9d524436ca60f4fd2bae8397491$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":14,"q_ok":12,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0123.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0123.json$t$, true),
  ($t$0123$t$, $t$Weymouth Township$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: More than 10 business days before closing for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety portal ('Start Your Smoke Certification Application'). Pay by e-check or credit card before submitting; a valid email address is required. The certificate is emailed once the application is submitted, the fee is paid and any required inspections are done. Homes heated by electricity with no CO alarm requirement should also email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 2/6/2026: Louis Kilmer · (609)633-6132","State online self-certification, now named the Certificate of Smoke Alarm, Carbon Monoxide Alarm, and Secondary Power Source Identification Label Compliance (CSACMASPSIL): smoke alarms, carbon monoxide alarms, and the secondary power source label for homes with solar, generators or batteries. The certificate name no longer includes the fire extinguisher, although the portal's checklist notice still refers to detectors and fire extinguishers","The Township's information sheet (revised 08/26/26) still describes the extinguisher rule: minimum 2A:10B:C, no more than 10 pounds, within 10 feet of the kitchen stove in the exit path, top no more than 5 feet above the floor on the manufacturer's bracket, serviced and tagged by a DFS-certified contractor within 12 months or a recent purchase receipt","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before closing","amount":"$45"},{"label":"4 to 10 business days before closing","amount":"$90"},{"label":"Less than 4 business days before closing","amount":"$161"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://www.weymouthnj.org/Document%20Center/Forms%20and%20Documents/Housing%20Forms/DCA-Smoke-Detector-info-08-2026.pdf","label":"Official source (weymouthnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The application for the Smoke Detector and Carbon Monoxide Alarm and Fire Extinguisher Compliance Certificate is obtained on line at https://firesolutions.dca.nj.gov/$t$, $t$ec0b3040d94f9b3cd0ce4774f82b7e927ad6fd308f04f85c9507238e7a878ccd$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":14,"q_ok":12,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0123.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0123.json$t$, true),
  ($t$0310$t$, $t$Delran Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog found signs that Delran Township does not require a resale certificate for sales, but no clear, current written statement. Call the office before closing.","Contact: Bill Lunemann, Construction Official · 856-461-8667 · constructioninspections@delrantownship.org","How to apply: The Township's Construction Office page tells sellers that the Fire District Office handles resale inspections; no separate township resale certificate is described. See the fire certificate section."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://delrantownship.org/construction-office/$t$, $j$[{"url":"https://delrantownship.org/construction-office/","label":"Official source (delrantownship.org)"},{"url":"https://delrantownship.org/fire-department/","label":"Official source (delrantownship.org)"}]$j$::jsonb, $t$Selling Your House? The Fire District Office handles inspections for resale. You will need to have your house inspected before you go to settlement;$t$, $t$2e2ea52a75fe1c29577aacd1674e266ac13c9c87082d920ba1f0aff209126c54$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["probably not required, but not clearly stated in writing"],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0310.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0310.json. Red flag: probably not required, but not clearly stated in writing$t$, true),
  ($t$0310$t$, $t$Delran Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Delran Township Fire District No. 1, Bureau of Fire Prevention (Local Enforcing Agency) (fire district)","Contact: Joseph Cunningham Jr., Fire Marshal / Fire Official · 856-461-5474 · LEA@delranfire.org","Apply: Apply more than 10 business days (excluding holidays) before the change of occupant for the lowest fee. Payment is due before the inspection.","How to apply: Fill out the Application for Inspection (Smoke Detector and CO Detector) and email it to LEA@delranfire.org or drop it off at the Fire District office in the Municipal Building, 900 S. Chester Avenue, Delran. Pay before the inspection by check payable to Delran Fire District #1 or online (list the inspection address as the invoice number).","Fire official in the NJ state directory (fire district), updated 3/5/2026: Joseph Cunningham, Jr · (856) 577-1077 · joseph.cunninghamjr@delranfire.org","Older homes need 10-year sealed battery smoke alarms (or AC powered alarms) on each level and outside sleeping areas","Homes built with hardwired, battery backup, interconnected alarms (for example Summer Hill, Forest Hill, Waters Edge, The Grande, the Orchard) must keep them on each level and in each bedroom, and they must be less than 10 years old","Carbon monoxide detectors must be less than 5 years old (check the manufacture or replace-by date) and installed outside each sleeping area","All smoke and CO detectors must be UL listed","House number: Arabic numerals, contrasting color, at least 3 inches tall, at least 30 inches above ground, visible from the street (Township Code Chapter 95)","The current form (February 2025) does not list a portable fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before closing","amount":"$45.00"},{"label":"Request received 4 to 10 business days before closing","amount":"$90.00"},{"label":"Request received fewer than 4 business days before closing","amount":"$161.00"}]$j$::jsonb, $t$https://www.delranfire.org/content/forms/file/APPLICATION%20FOR%20SD%20INSPECTION%202025.pdf$t$, $t$https://www.delranfire.org/content/prevention$t$, $j$[{"url":"https://www.delranfire.org/content/forms/file/APPLICATION%20FOR%20SD%20INSPECTION%202025.pdf","label":"Official source (delranfire.org)"},{"url":"https://www.delranfire.org/content/prevention","label":"Official source (delranfire.org)"},{"url":"https://www.delranfire.org/content/payment","label":"Official source (delranfire.org)"},{"url":"https://delrantownship.org/fire-department/","label":"Official source (delrantownship.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$N.J. State Fire Code N.J.A.C. 5:70-2.3 requires the inspection of One & Two Family Dwellings and R-2 Occupancies for smoke detectors and carbon monoxide detectors before it is sold or leased.$t$, $t$c7ffeecb487ee0be4890790afce32d895180f93648fb07f77804ce0b24eae9ad$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["probably not required, but not clearly stated in writing"],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0310.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0310.json. Red flag: probably not required, but not clearly stated in writing$t$, true),
  ($t$0414$t$, $t$Gloucester City$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Occupancy (Housing Code Section 55-13)$t$, $j$["Issued by: Gloucester City Housing and Building Department (Housing Inspector / Code Enforcement Official)","Contact: William Ackley, Chief Housing Inspector and Zoning Official · 856-456-7689 · housing@cityofgloucester.org","How to apply: Fill out the Application for Residential Certificate of Occupancy (check \"Sale\"), take a copy to the Municipal Court at 313 Monmouth St for the warrant waiver, and turn it in with payment (check or cash) to the Housing and Building Department, 700 Somerset St, Gloucester City, NJ 08030 (drop slot or mail also accepted). Incomplete applications are not accepted. A vacant property can instead get a Certificate for Transfer of Property Title ($75, valid 90 days) if a CO application is filed before it expires.","Valid for: Until the next change of occupant or transfer of title; not transferable","Home must meet the New Jersey State Housing Code (City Code 55-12)","Hard-wired, interconnected smoke detectors with battery backup on or near the ceiling of each level, certified by the Fire Official","Battery smoke detectors in each bedroom or sleeping area","All utilities must be on for the inspection","Warrant waiver from the Gloucester City Municipal Court (313 Monmouth St) showing no outstanding warrants for the buyer, owner and proposed occupants","Proof of identity for buyer and tenants; for an LLC, partnership or corporation, the record owner's name, address and phone","All outstanding Housing Office fees on the property (including vacant/abandoned property fees) must be paid first","Violations must be fixed and reinspected within 90 days of the first report (one extension to 120 days if asked in time), or a new application and fee are needed","Also: Municipal Court warrant waiver: Take a copy of the CO application to the Gloucester City Municipal Court, 313 Monmouth St, for a warrant waiver for the buyer, owner and proposed occupants (City Code 55-13 D(4)).","Also: Outstanding Housing Office fees: Under Ordinance 019-2017, all fees owed to the City Housing Office on the property, including vacant or abandoned property fees, must be paid before a Certificate of Occupancy or Transfer of Title is issued (notice attached to the 2019 application).","Also: Vacant property sale option: A vacant structure can be transferred with a Certificate for Transfer of Property Title ($75, valid 90 days, one battery smoke detector per level), but a CO application must be filed before it expires."]$j$::jsonb, $j$[{"label":"Initial inspection including first re-inspection (2019 form)","amount":"$100.00"},{"label":"Second re-inspection (2019 form)","amount":"$15.00"},{"label":"Each later re-inspection (2019 form)","amount":"$50.00"},{"label":"Certificate for Transfer of Property Title, vacant property sale only (a CO application must follow within 90 days)","amount":"$75"}]$j$::jsonb, $t$https://www.cityofgloucester.org/code-enforcement-housing-department/files/residential-certificate-occupancy-application$t$, $t$https://www.cityofgloucester.org/code-enforcement-housing-department$t$, $j$[{"url":"https://web.archive.org/web/20240616023236/https://www.cityofgloucester.org/home/bulletins/building-permits","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20150919155546/http://www.cityofgloucester.org/wp-content/uploads/2014/07/2015-Code-60-Chapter-55-Housing-Code.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20190921055011/https://www.cityofgloucester.org/wp-content/uploads/2019/03/Res-CO-2019.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20220308014711/https://www.cityofgloucester.org/code-enforcement-housing-department/pages/forms-documents","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20200926060845/https://www.cityofgloucester.org/departments/housing/","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$all property owners must obtain a Certificate of Occupancy in accordance with Gloucester City Code Section 55$t$, $t$7fdc84bf8282311fb3bd47d3049f8a0c1e3b0f55ca2bef069ba370b597093b6a$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":15,"q_ok":10,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0414.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0414.json$t$, true),
  ($t$0414$t$, $t$Gloucester City$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Gloucester City Fire Department (Fire Official Patrick R. Hagan); DCA directory lists 'Gloucester City Housing' as the smoke detector compliance contact (town fire bureau)","Contact: Patrick R Hagan, Fire Official · 856-456-7689 · pat.hagan@gloucestercityfd.org","How to apply: The City handles smoke detector certification with the Housing CO: City Code 55-13 says the CO is issued upon the Fire Official's certification of the smoke detectors, and the DCA directory lists Gloucester City Housing, 700 Somerset St (DCA lists 512 Monmouth St), (856) 456-7689, as the smoke detector compliance contact. No separate smoke/CO application or fee was found. Fire Official: Patrick R. Hagan, (856) 456-2652.","Fire official in the NJ state directory, updated 5/22/2026: Patrick R Hagan · (856) 456-2652 · pat.hagan@gloucestercityfd.org","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, null, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://web.archive.org/web/20150919155546/http://www.cityofgloucester.org/wp-content/uploads/2014/07/2015-Code-60-Chapter-55-Housing-Code.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$F Gloucester City$t$, $t$bd2e0f22fd2996d93f201735050fa954cdb56626ff6b2bc04e2c5fa85c73a753$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":15,"q_ok":10,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0414.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0414.json$t$, true),
  ($t$0423$t$, $t$Magnolia Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (Certificate of Change in Ownership / Change in Occupancy), Borough Code Chapter 112$t$, $j$["Issued by: Borough of Magnolia Construction Office (building inspector or housing inspector)","Contact: 856-783-1520","How to apply: Fill out the Certificate of Continued Occupancy Application (linked from the Borough's \"Certificate of Change in Occupancy\" page, with an inspection checklist) and turn it in to the Construction Office, 438 W. Evesham Ave, Magnolia, with the $75.00 fee. An inspector will contact you to schedule. The owner or the owner's agent must apply.","Home must meet the property maintenance standards the Borough adopted (BOCA National Property Maintenance Code, 1993) and all Borough ordinances","Hard-wired, interconnected smoke detectors with battery backup on or near the ceiling of each level","Battery smoke detectors in each bedroom or sleeping area","Smoke detectors must be certified by the fire official or other authorized person before the certificate is issued","Any repairs needed for the certificate are the current owner's responsibility, even if the problem was caused by a previous owner","Under Ordinance 12-2026 (adopted Sept 2, 2026) the owner stays responsible until the certificate is issued, no matter what the sale contract, settlement or escrow agreement says; each day of violation after notice is a separate offense"]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy inspection when a home is sold (Borough page; same as Code 15.112-11 \"Change of property ownership, Residential\")","amount":"$75.00"}]$j$::jsonb, null, $t$https://www.magnolia-nj.org/construction/page/certificate-change-occupancy$t$, $j$[{"url":"https://web.archive.org/web/20260111210243/https://www.magnolia-nj.org/construction/page/certificate-change-occupancy","label":"Official source (web.archive.org)"},{"url":"https://library.municode.com/nj/magnolia/codes/code_of_ordinances?nodeId=TIT15BUCO_CH112CEOC","label":"Official source (library.municode.com)"},{"url":"https://library.municode.com/nj/magnolia/codes/code_of_ordinances?nodeId=TIT15BUCO_CH112CEOC_15.112-11FE","label":"Official source (library.municode.com)"},{"url":"https://library.municode.com/nj/magnolia/ordinances/code_of_ordinances?nodeId=1442309","label":"Official source (library.municode.com)"},{"url":"https://www.magnolia-nj.org/construction/page/certificate-change-ownership","label":"Official source (magnolia-nj.org)"},{"url":"https://www.magnolia-nj.org/municipal-clerk/page/notice-final-adoption-ordinance-12-2026","label":"Official source (magnolia-nj.org)"}]$j$::jsonb, $t$Pursuant to Borough Code 17.270-31 Certificate of Occupancy Inspections are required whenever a home is being sold.$t$, $t$e3d88289924f856333fbcd8cba51d02342ee4c23691714381fa4911141fd77e9$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":7,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0423.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0423.json$t$, true),
  ($t$0423$t$, $t$Magnolia Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Magnolia Construction Office (smoke detector compliance) (town fire bureau)","Contact: 856-783-1520","Fire official in the NJ state directory (NJ DCA, state), updated 5/22/2026: Louis Kilmer · (609) 633-6132","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.magnolia-nj.org/construction/page/certificate-change-ownership$t$, $j$[{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$SMOKE DETECTOR COMPLIANCE Name: Magnolia Boro Constr Office Addr: 438 West Evesham Av Magnolia NJ 08049 Phone (856) 783-1520$t$, $t$15a8ef2048d26cacbc7c3bcb637378d16afe326b697e37d710d40b1c89b8b98b$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":7,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0423.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0423.json$t$, true),
  ($t$0502$t$, $t$Cape May$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Zoning Compliance (transfer of title)$t$, $j$["Issued by: Construction & Zoning Office (Zoning Officer)","Contact: Bruce Britton, Zoning Officer · 609-884-9556 · bbritton@capemaycity.com","How to apply: Fill out the Certificate of Zoning Compliance Application (block, lot, zoning district, current and new owners, use, number of units, settlement date) and submit it with the $85.00 fee to the Construction & Zoning Office, City Hall, 643 Washington Street, Cape May, NJ 08204.","Zoning compliance review of the property's use and number of units before transfer of title","Also: Certificate of Zoning Compliance for transfer of title: $85.00 application to the Construction & Zoning Office (form dated 05/2018); see the town certificate."]$j$::jsonb, $j$[{"label":"Certificate of Zoning Compliance application","amount":"$85.00"}]$j$::jsonb, $t$https://evocloud-prod3-public.s3.us-east-2.amazonaws.com/3/media/734.pdf$t$, $t$https://www.capemaycity.com/departments/ConstructionZoning$t$, $j$[{"url":"https://evocloud-prod3-public.s3.us-east-2.amazonaws.com/3/media/734.pdf","label":"Official source (evocloud-prod3-public.s3.us-east-2.amazonaws.com)"},{"url":"https://www.capemaycity.com/forms-center","label":"Official source (capemaycity.com)"},{"url":"https://www.capemaycity.com/departments/ConstructionZoning","label":"Official source (capemaycity.com)"}]$j$::jsonb, $t$The information below is necessary for the issuance of a Certificate of Zoning Compliance for the transfer of title to any building, structure or unit, within the City of Cape May. The Certificate of Zoning Compliance will be issued in accordance with Section 199-5., of the City of Cape May Code.$t$, $t$9625921a4cfd4684d5851d7d597777a7da522f2f5d9cc0779f48cbea3c335f58$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0502.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0502.json$t$, true),
  ($t$0502$t$, $t$Cape May$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Cape May Bureau of Fire Prevention (town fire bureau)","Contact: Mark Barham, Fire Official · 609-884-9587 · mbarham@capemaycity.com","Apply: Apply more than 10 business days before settlement for the lowest fee","How to apply: Fill out the Sale of Property Form (check the Certificate of Smoke Alarm, Carbon Monoxide Alarm option for 1-2 family dwellings, give the closing date and agent/title contact) and send it to the Bureau of Fire Prevention, fireprevention@capemaycity.com, 609-884-9599. Do not send payment with the application; the fee is set when the form is received and the Bureau invoices it (fire invoices can be paid online through the City's Tyler portal).","Fire official in the NJ state directory (town), updated 7/22/2026: Mark C Barham · (609) 884-9599 · mbarham@capemaycity.com","Sale of Property Form (created March 2025) still names the certificate as covering a portable fire extinguisher, but the Bureau's web page says fire extinguishers are no longer required in one- or two-family dwellings for sales or rentals; if one is kept it must be maintained (approved hanger, serviced within 12 months)","Smoke alarms no older than 10 years; battery-only smoke alarms must be the 10-year sealed battery type (listed on the Bureau page as top rental violations)","Carbon monoxide alarm near sleeping areas and on every level when there are fuel-burning appliances, an attached garage or a fireplace","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate (1-2 family), application received more than 10 business days from settlement","amount":"$150"},{"label":"Smoke/CO certificate (1-2 family), application received 4 to 10 business days from settlement","amount":"$250"},{"label":"Smoke/CO certificate (1-2 family), application received fewer than 4 business days from settlement","amount":"$375"}]$j$::jsonb, $t$https://www.capemaycity.com/media/Fire%20Prevention/Sale%20of%20Property%20Form.pdf$t$, $t$https://www.capemaycity.com/departments/FirePrevention$t$, $j$[{"url":"https://www.capemaycity.com/media/Fire%20Prevention/Sale%20of%20Property%20Form.pdf","label":"Official source (capemaycity.com)"},{"url":"https://www.capemaycity.com/departments/FirePrevention","label":"Official source (capemaycity.com)"},{"url":"https://www.capemaycity.com/departments/staff_directory/FirePrevention/","label":"Official source (capemaycity.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certificate of Smoke Alarm, Carbon Monoxide Alarm, and Portable Fire Extinguisher Compliance (Choose this option for 1 to 2 family dwellings)$t$, $t$60884dfadfb67e810bc71518fe8efe784ee222880b3f7cda912a96e576d9b3c2$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0502.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0502.json$t$, true),
  ($t$0503$t$, $t$Cape May Point Borough$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance$t$, $j$["Issued by: Zoning Official, Borough of Cape May Point","Contact: Bruce Britton, Zoning Official · 609-884-8468 x16 · bbritton@capemaypoint.org","How to apply: Fill out the Certificate of Compliance Application (name, mailing address, unit, street address, block, lot, date of settlement, and a key or lock box code for the interior inspection) and send it with the $100.00 per unit fee to the Office of the Zoning Official, Borough of Cape May Point, PO Box 490, Cape May Point, NJ 08212 (215 Lighthouse Avenue). Office hours are 4:00 PM to 6:00 PM Tuesday and Wednesday only.","Interior inspection of the structure or unit by the Zoning Official before settlement (key or lock box code needed)"]$j$::jsonb, $j$[{"label":"Certificate of Compliance inspection, per unit (capped at $300 per building)","amount":"$100.00"}]$j$::jsonb, $t$https://capemaypoint.org/uploaded_files/document/Certificate%20of%20Compliance%20Application.pdf$t$, $t$https://capemaypoint.org/zoning.php$t$, $j$[{"url":"https://capemaypoint.org/uploaded_files/document/Certificate%20of%20Compliance%20Application.pdf","label":"Official source (capemaypoint.org)"},{"url":"https://capemaypoint.org/zoning.php","label":"Official source (capemaypoint.org)"},{"url":"https://capemaypoint.org/documentcenter.php","label":"Official source (capemaypoint.org)"}]$j$::jsonb, $t$Certificate of Compliance Application$t$, $t$138f876547309da73686f6b65692341d36f2fda6f95fae5fcf013e992b493eb7$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":9,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0503.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0503.json$t$, true),
  ($t$0503$t$, $t$Cape May Point Borough$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (State is the fire code enforcing agency and issues smoke certificates) (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6132 · BFCE_CSDCMAC@dca.nj.gov","Apply: Apply more than 10 business days before closing for the lowest fee","How to apply: Apply online through the DCA Fire Safety portal ('Start Your Smoke Certification Application'). Payment by e-check or credit card is required before submitting, and a valid email address is required. Homes heated by electricity with no CO alarm requirement should also email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 7/31/2026: Louis Kilmer · (609)633-6132","The State application certifies smoke alarms, carbon monoxide alarms and the secondary power source identification label (homes with solar, generators or battery systems); it no longer lists a fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before closing","amount":"$45"},{"label":"4 to 10 business days before closing","amount":"$90"},{"label":"Less than 4 business days before closing","amount":"$161"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Cape May Point Borough$t$, $t$aafedde2fbabc88cf9bd8e80452ea242e80b9b5d64e9e5237de803d3c9e8aefb$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":9,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0503.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0503.json$t$, true),
  ($t$0506$t$, $t$Middle Township$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Middle Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Daniel Speigel, Construction Official · 609-465-8740 · dspeigel@middletownship.com","Also: Open construction permits: The fire bureau will not issue the smoke/CO certificate while any construction permit is open."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://middletownship.com/departments/contruction/$t$, $j$[{"url":"https://middletownship.com/departments/contruction/","label":"Official source (middletownship.com)"}]$j$::jsonb, $t$Please be advised that the Township of Middle DOES NOT issue a Certificate of Occupancy or a Zoning Certificate for the transfer of a property/business nor for the renting of a property. The only time a Certificate of Occupancy is issued is at the origination of the building, change of use, reconstruction or an addition per the Uniform Construction Code 5:23-2.24.$t$, $t$8a3075732f6303d9b25610b67db6aa58953514da4924db4bf26edcd41ee4feb3$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0506.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0506.json$t$, true),
  ($t$0506$t$, $t$Middle Township$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Bureau of Fire Prevention, Middle Township Fire Districts (run by Fire District #1) (fire district)","Contact: Douglas Greenberg, Fire Official (per state fire directory) · 609-465-8710 · firebureau@cmchfire.com","Apply: Apply more than 10 days before closing for the lowest fee; the certificate must be used within six months","How to apply: Download the 2025 Home Sale Application Packet (CSACMAPFEC) from the Fire District 1 Forms page, complete and initial all 4 pages (seller must sign), and submit it with a check or money order payable to Bureau of Fire Prevention to 115 Mechanic Street, Cape May Court House, NJ 08210 (firebureau@cmchfire.com, 609-465-8710). Forms dated before August 2025 are not accepted. Applications left in the mailbox count as received the next business day. Office hours Monday to Thursday 8:00am to 4:00pm, Friday 8:00am to 1:00pm.","Fire official in the NJ state directory (fire district), updated 8/17/2026: Douglas Greenberg · (609) 465-8710 · greenbergdm@cmchfire.com","Smoke alarms by year built: before 1977, 10-year sealed battery alarms on each level and outside each sleeping area; newer homes need AC-powered (hardwired) alarms per the construction code of their year, interconnected from August 1984, and in each bedroom with battery backup from March 1991","Do not replace AC-powered alarms with battery alarms; alarms over 10 years old (or with no date) must be replaced; no tape or velcro mounting","Low-voltage fire alarm systems in homes built 1977 or later must be kept and tested by a NJ licensed alarm contractor, with the passed report sent to the Bureau before the inspection; systems installed 2011 or later must be monitored","CO alarm (UL 2034) in the hallway within 10 feet of each sleeping area when there is a fuel-burning appliance or attached garage, plus one in any bedroom with a fuel-burning appliance; not more than 10 years old","Portable fire extinguisher 2-A:10-B:C, no larger than 10 lbs, new or tagged within 12 months, on the manufacturer's bracket within 10 feet of the kitchen, top no higher than 5 feet (still listed in the 2025 packet)","Secondary power source label within 18 inches of the main electrical panel and meter for homes with solar, backup generators or batteries","Certificate will not be issued if there are any open construction permits","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate, application received more than 10 days prior to closing","amount":"$78.00"},{"label":"Certificate, application received 4 to 10 days prior to closing","amount":"$115.00"},{"label":"Certificate, application received less than 4 days prior to closing","amount":"$210.00"},{"label":"Reinspection","amount":"$75.00"}]$j$::jsonb, $t$https://assets.zyrosite.com/m6LZvpK60zuj57RE/2025-csacmapfec-application-packet-1-mjEGJvOnNVH91QGq.pdf$t$, $t$https://middletownshipfiredistrict1.com/forms$t$, $j$[{"url":"https://assets.zyrosite.com/m6LZvpK60zuj57RE/2025-csacmapfec-application-packet-1-mjEGJvOnNVH91QGq.pdf","label":"Official source (assets.zyrosite.com)"},{"url":"https://middletownshipfiredistrict2.com/","label":"Official source (middletownshipfiredistrict2.com)"},{"url":"https://assets.zyrosite.com/m6LZvpK60zuj57RE/bureau-hours-door-sign-Y4LDBO7RJjIMXgol.pdf","label":"Official source (assets.zyrosite.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$BUREAU OF FIRE PREVENTION MIDDLE TOWNSHIP FIRE DISTRICTS #1, 3 & 4 115 Mechanic Street Cape May Court House, NJ 08210 O: 609.465.8710 F: 609.465.3851 firebureau@cmchfire.com$t$, $t$324ff38370e2f95c5447fd152445ba7bb0f042aefff58a9992e1dd02e2e6b4b3$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0506.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0506.json$t$, true),
  ($t$0507$t$, $t$North Wildwood$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Zoning Use Compliance$t$, $j$["Issued by: Planning & Zoning (Zoning Officer)","Contact: Daniel Speigel, Construction Official/Fire Official/Zoning Officer · 609-522-2030 Ext. 1562 · dspeigel@northwildwood.com","Apply: Apply more than 10 business days before the certificate is needed for the lowest fee","How to apply: Fill out the Application for Certificate of Zoning Use Compliance (page 1 of the City's 'Forms required for sale of properties'), with property, seller/agent, owner and buyer details, settlement date, current use and number of units, and key or access code. Pay by check (a separate check from the fire certificate), exact cash, or credit card with a 2.75% surcharge, at City Hall, 901 Atlantic Avenue, North Wildwood, NJ 08260.","Zoning review that the current use (single family, two-family, multi-family and number of units) is permitted or a legal preexisting nonconforming use","Also: Certificate of Zoning Use Compliance: Required before a sale or transfer; separate application and check from the fire certificate. See the town certificate."]$j$::jsonb, $j$[{"label":"Zoning certificate, requested more than 10 business days before needed","amount":"$50.00"},{"label":"Zoning certificate, requested 4 to 9 days before needed","amount":"$70.00"},{"label":"Zoning certificate, requested less than 4 days before needed","amount":"$125.00"}]$j$::jsonb, $t$https://northwildwood.com/wp-content/uploads/2026/03/Forms-required-for-sale-of-properties.pdf$t$, $t$https://northwildwood.com/departments/construction-office/$t$, $j$[{"url":"https://northwildwood.com/wp-content/uploads/2026/03/Forms-required-for-sale-of-properties.pdf","label":"Official source (northwildwood.com)"},{"url":"https://northwildwood.com/public-safety/fire-housing-bureau/","label":"Official source (northwildwood.com)"},{"url":"https://ecode360.com/37124931","label":"Official source (ecode360.com)"},{"url":"https://northwildwood.com/departments/construction-office/","label":"Official source (northwildwood.com)"}]$j$::jsonb, $t$Application for Certificate of Zoning Use Compliance$t$, $t$62f5b7084be18e6d80a65a2136ec0e088967b9de05359ce687d09a0f271d8a30$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0507.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0507.json$t$, true),
  ($t$0507$t$, $t$North Wildwood$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: North Wildwood Fire & Housing Bureau (Fire Prevention Bureau) (town fire bureau)","Contact: Daniel Speigel, Fire Official · 609-522-2160 · dspeigel@northwildwood.com","Apply: Apply more than 10 business days before settlement for the lowest fee; do not submit until all items are in place","How to apply: Fill out the Application for a Certificate of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance (page 2 of 'Forms required for sale of properties'), note keys or lock box code, and submit with a separate check (or exact cash, or credit card with a 2.75% surcharge) to the Fire & Housing Bureau, 901 Atlantic Ave., North Wildwood (609-522-2160, fireinspector@northwildwood.com). Smoke detector applications are taken Monday to Friday 8AM to 4PM.","Fire official in the NJ state directory, updated 2/13/2025: Daniel F Speigel · (609) 522-2030 · dspeigel@northwildwood.com","Smoke alarms in each sleeping room, within 10 feet outside each sleeping area, and on every level","Hardwired smoke alarms older than 10 years must be replaced; battery smoke alarms must be the 10-year sealed battery type","CO alarms within 10 feet outside each sleeping area and on every level when there are fuel-burning appliances or an attached garage","Fire extinguisher at least 2A:10BC, new (current year) or tagged by a licensed agent, for each cooking area, hung in a visible spot or labeled cabinet (still listed on the March 2026 form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke / CO alarm and extinguisher certificate, per unit, applied more than 10 business days before settlement","amount":"$45.00"},{"label":"Smoke / CO alarm and extinguisher certificate, per unit, applied 4 to 10 business days before settlement","amount":"$90.00"},{"label":"Smoke / CO alarm and extinguisher certificate, per unit, applied less than 4 business days before settlement","amount":"$161.00"},{"label":"Re-inspection (same as the first inspection fee, by timing)","amount":"$45.00 to $161.00"},{"label":"Fire Code Status Report, for properties registered and inspected annually only","amount":"$25.00"}]$j$::jsonb, $t$https://northwildwood.com/wp-content/uploads/2026/03/Forms-required-for-sale-of-properties.pdf$t$, $t$https://northwildwood.com/public-safety/fire-housing-bureau/$t$, $j$[{"url":"https://northwildwood.com/public-safety/fire-housing-bureau/","label":"Official source (northwildwood.com)"},{"url":"https://northwildwood.com/wp-content/uploads/2026/03/Forms-required-for-sale-of-properties.pdf","label":"Official source (northwildwood.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Department Head: Daniel Speigel Fire Official$t$, $t$909008a980cfd3005f7f76ebbf8713bd1392b796da7907ff07ca1ffd5eda78fe$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0507.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0507.json$t$, true),
  ($t$0508$t$, $t$Ocean City$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Zoning Compliance Certification (homes built after January 1, 1996 only)$t$, $j$["Issued by: City of Ocean City (requested on the same sale-of-property inspection application; Zoning Office)","Contact: Jessica Fenton, Zoning Official · 609-399-6111 ext 9759 · jfenton@ocnj.us","How to apply: Use the City's Sale of Property inspection application (the same form as the smoke/CO certificate); give the date of the final CO (year built) so the City knows zoning certification is needed. Send it to 115 12th Street, Ocean City, NJ 08226, (609) 399-6111 x 9727, smokedetector@ocnj.us.","Zoning compliance check at the in-person sale inspection, for homes built after January 1, 1996","Also: Zoning Compliance Certification for homes built after January 1, 1996: Required on sale per the City's 2025 sale inspection form; see the town certificate."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.ocnj.us/media/KnightBuilding/Smoke%20Detector/salecertapp2025.pdf$t$, $t$https://www.ocnj.us/zoning$t$, $j$[{"url":"https://www.ocnj.us/media/KnightBuilding/Smoke%20Detector/salecertapp2025.pdf","label":"Official source (ocnj.us)"},{"url":"https://www.ocnj.us/departments/staff_directory/Administration/","label":"Official source (ocnj.us)"},{"url":"https://www.ocnj.us/zoning","label":"Official source (ocnj.us)"}]$j$::jsonb, $t$Homes built after January 1, 1996 also require Zoning Compliance Certification.$t$, $t$7b208924a6ddef427db7b37726961f2077978dea4fad8177c58ed66b56043f38$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0508.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0508.json$t$, true),
  ($t$0508$t$, $t$Ocean City$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Ocean City Division of Fire Prevention (Municipal Code, Licensing and Fire Prevention, Knight Building) (town fire bureau)","Contact: 609-399-6111 ext. 9727 · smokedetector@ocnj.us","Apply: Book before closing; inspections Monday to Friday 9am to 3pm at scheduled times","How to apply: Fill out the Inspection Request: Sale of Property Application for Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance (closing date, requested inspection date and time, access: meet owner/agent/tenant or lock box code, buyer and agent details, year of final CO). Submit to 115 12th Street, Ocean City, NJ 08226, call 609-399-6111 ext. 9727, or email smokedetector@ocnj.us. Payment by mail, in person or online. The seller or the seller's agent must get it before the sale or transfer of title.","Fire official in the NJ state directory (NJ DCA, state), updated 2/13/2025: Louis Kilmer · (609)633-6132","Homes built before 1977: 10-year sealed battery smoke alarms on each level and outside each sleeping area","Built January 1977 to February 21, 1983: hardwired (120 volt) smoke alarms on each level and near each sleeping area (interconnection not required)","Built February 22, 1983 to April 30, 1993: hardwired multi-station smoke alarms on each level and near each sleeping area, interconnected","Built May 1, 1993 to present: hardwired interconnected smoke alarms with battery backup in all bedrooms, outside each sleeping area and on every level","CO alarms (UL 2034) near sleeping areas when there are fuel-burning devices or an attached garage","Portable fire extinguisher 2A-10B:C for the sale of 1-2 family units, on its bracket within 10 feet of the kitchen in the path of egress, top no more than 5 feet up (City requirements sheet dated February 2024, before P.L.2025, c.19)","Inspections are in person only; self-certifications are no longer accepted","Individually owned condo units in multifamily buildings also need the certificate","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Sale inspection, per unit, property built before 1996","amount":"$50"},{"label":"Sale inspection, per unit, property built after 1996 (form also requires Zoning Compliance Certification for these homes)","amount":"$100"}]$j$::jsonb, $t$https://www.ocnj.us/media/KnightBuilding/Smoke%20Detector/salecertapp2025.pdf$t$, $t$https://www.ocnj.us/firepreventionfaq$t$, $j$[{"url":"https://www.ocnj.us/firepreventionfaq","label":"Official source (ocnj.us)"},{"url":"https://www.ocnj.us/media/KnightBuilding/Smoke%20Detector/salecertapp2025.pdf","label":"Official source (ocnj.us)"},{"url":"https://www.ocnj.us/media/KnightBuilding/Smoke%20Detector/SmokeRequirements.pdf","label":"Official source (ocnj.us)"},{"url":"https://www.ocnj.us/municipalcodeandlicensing","label":"Official source (ocnj.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certification is required for all residential rental units in one- and two-family dwellings and for the sale or transfer of title of residential units in one- and two-family dwellings, and individually owned condo units in multiple dwellings.$t$, $t$3c166b47bfb504d64eff5d1a0ca4e8b60739202b2a037d97860356bc4b08d407$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0508.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0508.json$t$, true),
  ($t$0509$t$, $t$Sea Isle City$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance, Floodplain Venting Requirements (flood vent check at sale)$t$, $j$["Issued by: Construction Office (Construction Official)","Contact: Neil Byrne, Construction Official, Building Sub-code Official, Zoning Officer & Certified Floodplain Manager · 609-263-1166 · construction@seaislecitynj.us","How to apply: Use the City's 'Smoke Detector, Extinguisher, CO Alarm & Venting application' packet from the Construction Forms page. Fill in the property address, owner's name and the mailing address for the certificate on the venting certificate page and return it to the Construction Office, City Hall 2nd floor, 233 John F. Kennedy Blvd. The Construction Official then inspects the flood venting.","Construction Official visits the home to verify the required square inches of flood venting","Flood vents: at least one square inch of net open area per square foot of enclosed area (non-engineered vents), or one engineered inch per square foot for engineered vents","Required vents and crawl space access door(s) must be located; if they fall short, the owner is given a set number of days to meet the City venting requirements"]$j$::jsonb, $j$[]$j$::jsonb, $t$https://evocloud-prod3-public.s3.us-east-2.amazonaws.com/56/media/96877.pdf$t$, $t$https://www.seaislecitynj.us/departments/ConstructionOffice$t$, $j$[{"url":"https://www.seaislecitynj.us/departments/ConstructionOffice/ConstructionOfficeFAQs","label":"Official source (seaislecitynj.us)"},{"url":"https://evocloud-prod3-public.s3.us-east-2.amazonaws.com/56/media/96877.pdf","label":"Official source (evocloud-prod3-public.s3.us-east-2.amazonaws.com)"},{"url":"https://www.seaislecitynj.us/departments/ConstructionOffice","label":"Official source (seaislecitynj.us)"},{"url":"https://www.seaislecitynj.us/media/Construction%20Office/Flood%20Protection%20Info..pdf","label":"Official source (seaislecitynj.us)"}]$j$::jsonb, $t$What inspections do I need to sell my property? A self-inspection must be performed certifying that the smoke detectors, carbon monoxide alarms and fire extinguishers are placed properly throughout the house, are in working order, and are not expired. The City Construction Official will go to the property to verify the number of required square inches of flood venting. Both of these forms are on the Construction Office page on the City’s municipal website.$t$, $t$b2300138eb1ea19215cf5ee1809fcf7b28f8733c935d63736df786e192511b1a$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":14,"q_ok":8,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0509.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0509.json$t$, true),
  ($t$0509$t$, $t$Sea Isle City$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Sea Isle City (Construction Office / Municipal Services, municipal fire code enforcing agency) (town fire bureau)","Contact: Robert Wojcik, Fire Official (per NJ DCA fire directory) · 609-263-4461 · rwojcik@seaislecitynj.us","Apply: Certificate is mailed; allow processing time. If the sale does not happen within 6 months a new application is needed.","How to apply: Download the Application for Certificate of Smoke Detector, Carbon Monoxide Alarm, Portable Fire Extinguisher Compliance from the Construction Forms page. Check off each item, sign in front of a notary, and return it with a $45 per unit check (payable to the City of Sea Isle City), cash or money order to Municipal Services, 2nd floor, 233 John F. Kennedy Blvd., Sea Isle City, NJ 08243. The certificate is mailed to the mailing address on the form. Fees are non-refundable and the certificate is not transferable.","Fire official in the NJ state directory (town), updated 2/1/2024: Robert Wojcik · (609) 263-1366 · rwojcik@seaislecitynj.us","Owner or authorized representative does the inspection and signs a notarized self-certification; no inspector visit for the alarms","Smoke detector on each level including basements (not attic or crawl space), and a smoke detector and CO alarm outside each separate sleeping area, within ten feet of it","Homes built after January 1977: AC powered and/or interconnected smoke alarms must be kept in working order; a ten year sealed battery smoke detector is required if detectors are not hard wired","CO alarm required when the home has fuel-burning appliances, a fireplace or wood/coal stove, or an attached garage; battery alarms are acceptable","City form still lists a portable fire extinguisher: minimum rating 2A-10B:C, no more than 10 pounds, within ten feet of the kitchen area, on its bracket, top no more than 5 feet above the floor, near an exit (seasonal summer units exempt)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke, CO alarm and fire extinguisher certificate, per unit","amount":"$45"}]$j$::jsonb, $t$https://evocloud-prod3-public.s3.us-east-2.amazonaws.com/56/media/96877.pdf$t$, $t$https://www.seaislecitynj.us/departments/ConstructionOffice/constructionforms$t$, $j$[{"url":"https://evocloud-prod3-public.s3.us-east-2.amazonaws.com/56/media/96877.pdf","label":"Official source (evocloud-prod3-public.s3.us-east-2.amazonaws.com)"},{"url":"https://www.seaislecitynj.us/departments/volunteerfiredepartment/firedepartmentfaqs","label":"Official source (seaislecitynj.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Application For Certificate of Smoke Detector Carbon Monoxide Alarm Portable Fire Extinguisher Compliance$t$, $t$62846efda849eb991124413acac841b9f7b269e6a88fae4cf833374503adc606$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":14,"q_ok":8,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0509.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0509.json$t$, true),
  ($t$0510$t$, $t$Stone Harbor Borough$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Title Transfer (zoning and flood conformance inspection)$t$, $j$["Issued by: Office of Code Enforcement (Construction Office), Zoning Official / Flood Plain Administrator","Contact: Rick Allen, Construction Official and Flood Plain Administrator · 609-368-6814 · AllenR@shnj.org","How to apply: Fill out the Application for Certificate of Title Transfer (property address, block and lot, seller, purchaser, agent, scheduled closing date) and submit it with payment (check or cash) to the Office of Code Enforcement, Borough Hall first floor, 9508 Second Avenue, Stone Harbor, NJ 08247. Listing a realtor lets the official use the realtor's key.","Zoning conformance inspection","Flood conformance inspection against the required design flood elevation (DFE + 2 or 11 feet), with the assessed value of the structure recorded","Inspector enters with the realtor's key; if no realtor or manager is listed, the owner must set an appointment during the inspection week","Also: Open permits closed: All open Uniform Construction Code permits must be closed before settlement (Fire Prevention Bureau guide)."]$j$::jsonb, $j$[{"label":"Zoning fee","amount":"$50.00"},{"label":"Flood inspection fee","amount":"$50.00"},{"label":"Total due","amount":"$100.00"}]$j$::jsonb, $t$https://stoneharbornj.org/wp-content/uploads/2023/04/APPLICATION-FOR-CERTIFICATE-OF-TITLE-TRANSFER.pdf$t$, $t$https://stoneharbornj.org/departments/construction/$t$, $j$[{"url":"https://stoneharbornj.org/wp-content/uploads/2023/04/APPLICATION-FOR-CERTIFICATE-OF-TITLE-TRANSFER.pdf","label":"Official source (stoneharbornj.org)"},{"url":"https://web.archive.org/web/20250713195307/http://stoneharbornj.org/departments/construction/","label":"Official source (web.archive.org)"},{"url":"https://stoneharbornj.org/departments/construction/","label":"Official source (stoneharbornj.org)"}]$j$::jsonb, $t$APPLICATION FOR CERTIFICATE OF TITLE TRANSFER THE BOROUGH OF STONE HARBOR OFFICE OF CODE ENFORCEMENT$t$, $t$9da0e4946380eefbca16cee86c8bdfd40765294fce2ba727e3f526d102c67bd0$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":11,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0510.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0510.json$t$, true),
  ($t$0510$t$, $t$Stone Harbor Borough$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Stone Harbor Fire Prevention Bureau (Stone Harbor Bureau of Fire Prevention) (town fire bureau)","Contact: Mike Gihorski, Acting Fire Official · 609-368-5102 · fireofficial@shnj.org","Apply: More than 10 business days before the change of occupant for the lowest fee","How to apply: Fill out the CSACMAPFEC application (owner, buyer, block and lot, agent, settlement date, key or appointment details) and submit it with a check or money order payable to 'Borough of Stone Harbor' to the Stone Harbor Fire Prevention Bureau, 9508 Second Avenue, Stone Harbor, NJ 08247. The Bureau inspects before issuing the certificate.","Fire official in the NJ state directory, updated 3/6/2025: Michael Gihorski · (609) 368-5102 · fireofficial@shnj.org","On-site inspection by the Stone Harbor Bureau of Fire Prevention; closing or leasing before the certificate is issued carries a $500.00 penalty","Smoke alarms over ten years old must be replaced; battery alarms must be 10-year sealed battery type; wired alarms may not be replaced with battery alarms","Smoke alarm type and number depend on the year built or renovated (for example, homes from March 1991 on need wired, interconnected alarms on all levels and inside each sleeping room)","CO alarms on sleeping levels within 10 feet of every bedroom door when there is an attached garage, fuel-burning appliance or fireplace; CO alarms not more than 10 years old; homes built 2015 or later need hard-wired CO alarms","Low-voltage fire alarm systems must be tested by a NJ licensed alarm contractor with an NFPA 72 report sent to the Bureau","Form (October 2022) still requires a fire extinguisher: minimum 2A:40BC, not over 10 pounds, in or within 10 feet of the kitchen on its bracket, top no more than 5 feet up, serviced within the past year or bought within 6 months with receipt, manual left for the buyer","All open construction permits must be closed before settlement","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"1 unit, request more than 10 business days before change of occupant","amount":"$50.00"},{"label":"2 units in one structure, more than 10 business days before","amount":"$65.00"},{"label":"1 unit, request 5 to 9 business days before change of occupant","amount":"$100.00"},{"label":"2 units in one structure, 5 to 9 business days before","amount":"$115.00"},{"label":"1 unit, request 4 or fewer business days before change of occupant","amount":"$155.00"},{"label":"2 units in one structure, 4 or fewer business days before","amount":"$170.00"},{"label":"Re-inspection after a failed inspection","amount":"$25.00"},{"label":"Penalty for closing or leasing before the certificate is issued","amount":"$500.00"}]$j$::jsonb, $t$https://stoneharbornj.org/wp-content/uploads/2022/10/CSACMAPFEC-2022.pdf$t$, $t$https://stoneharbornj.org/departments/stone-harbor-public-safety/stone-harbor-fire-prevention-bureau/$t$, $j$[{"url":"https://stoneharbornj.org/wp-content/uploads/2022/10/CSACMAPFEC-2022.pdf","label":"Official source (stoneharbornj.org)"},{"url":"https://stoneharbornj.org/departments/stone-harbor-public-safety/stone-harbor-fire-prevention-bureau/","label":"Official source (stoneharbornj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$I understand that a satisfactory inspection must be performed by the Stone Harbor Bureau of Fire Prevention prior to the issuance of the CSACMAPFEC$t$, $t$6b61043b20124eec236ac73765d44d2df0fba27cc4919bbc26e34a3ee2868af7$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":11,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0510.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0510.json$t$, true),
  ($t$0511$t$, $t$Upper Township$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Upper Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Dory Cooper, Construction Official · 609-628-2011 ext. 225 · constructioncode@uppertownship.com","How to apply: No Township resale inspection. The Township's Construction Code page sends sellers to the NJ DCA online smoke detector and carbon monoxide certification."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://uppertownship.com/departments/construction-code/$t$, $j$[{"url":"https://uppertownship.com/departments/construction-code/","label":"Official source (uppertownship.com)"}]$j$::jsonb, $t$The Construction Department does not do inspections for resale of residential or non-residential structures.$t$, $t$bfff49ca0d07ef4325e452cc05ff94953c3b41373091da6cdda97a7690cbabda$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":9,"q_ok":7,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0511.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0511.json$t$, true),
  ($t$0511$t$, $t$Upper Township$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: More than 10 business days before closing for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety portal ('Start Your Smoke Certification Application'). Pay by e-check or credit card before submitting; a valid email address is required. The certificate is emailed once the application is submitted, the fee is paid and any required inspections are done. Homes heated by electricity with no CO alarm requirement should also email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 8/5/2026: Louis Kilmer · (609)633-6132","State online self-certification (CSACMASPSIL): smoke alarms, carbon monoxide alarms, and the secondary power source identification label for homes with solar, generators or batteries; the current state application no longer lists a fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before closing","amount":"$45"},{"label":"4 to 10 business days before closing","amount":"$90"},{"label":"Less than 4 business days before closing","amount":"$161"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://uppertownship.com/departments/construction-code/","label":"Official source (uppertownship.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Construction Department does not do inspections for resale of residential or non-residential structures. You can use the above link for the required smoke detector and carbon monoxide certification. This certification is administered by the NJ Department of Community Affairs.$t$, $t$5351ab9e62b4c9b992faf7ef40049c44be2ab2304eb17539e710c6467169a858$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":9,"q_ok":7,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0511.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0511.json$t$, true),
  ($t$0514$t$, $t$Wildwood$t$, $t$CAPE MAY$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) and Zoning Certification, via the combined Application for Transfer of Ownership$t$, $j$["Issued by: City of Wildwood Construction / Code Enforcement Office (CCO) and Zoning Office (zoning certification)","Contact: Kate Dunn, Technical Assistant to the Construction Official / Planning and Zoning Board Secretary · 609-522-2444 ext. 2910 · kdunn@wildwoodnj.gov","Apply: 10 or more business days before settlement for the lowest zoning fee; reports take several days after the inspection to process","How to apply: Fill out the one combined City of Wildwood Application for Transfer of Ownership (property, units, bedrooms, seasonal or year-round, settlement date, owner, buyer, agent) and turn it in with payment at City Hall, 4400 New Jersey Avenue. No application is accepted without payment; do not fax or mail it without payment. The current fire form says separate checks are required for the fire, CCO and zoning certificates. Reports are faxed or emailed when done.","Continued Occupancy (CCO) inspection","Zoning certification","Smoke detector and carbon monoxide compliance inspection (see the fire certificate)","Status of Fire Code report, only for properties that need a yearly fire inspection (single family homes do not)"]$j$::jsonb, $j$[{"label":"CCO, residential property with 1 to 5 units","amount":"$95.00"},{"label":"Zoning certification, 10 or more business days before settlement","amount":"$50.00"},{"label":"Zoning certification, 4 to 10 business days before settlement","amount":"$70.00"},{"label":"Zoning certification, less than 4 business days before settlement","amount":"$125.00"},{"label":"Status of Fire Code (only properties that need a yearly fire inspection)","amount":"$25.00"}]$j$::jsonb, $t$https://wildwoodnj.gov/files/Transfer-of-ownership.pdf$t$, $t$https://wildwoodnj.gov/construction$t$, $j$[{"url":"https://wildwoodnj.gov/files/Transfer-of-ownership.pdf","label":"Official source (wildwoodnj.gov)"},{"url":"https://wildwoodnj.gov/codeenforcement","label":"Official source (wildwoodnj.gov)"},{"url":"https://wildwoodnj.gov/construction","label":"Official source (wildwoodnj.gov)"},{"url":"https://wildwoodnj.gov/firedepartment/images/CSACMAC%20Application%20FILLABLE.pdf","label":"Official source (wildwoodnj.gov)"}]$j$::jsonb, $t$We have changed from 4 different applications to one combined application. You are still required to have the four different inspections, but only need to fill out the one form.$t$, $t$b030dfecab0b8af959b084e63e5cf6d8f51e5f097e5b351ff40b90ce097cf43b$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":5,"fee_bad":0,"fee_unchecked":3,"quotes":15,"q_ok":8,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0514.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0514.json$t$, true),
  ($t$0514$t$, $t$Wildwood$t$, $t$CAPE MAY$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Wildwood Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Jacob M. Spiegel, Fire Official · 609-846-2031 · jspiegel@wildwoodnj.gov","Apply: 10 or more business days before settlement for the lower fee","How to apply: Fill out the Application for a Certificate of Smoke Alarm and Carbon Monoxide Alarm Compliance (CSACMAC) for 1 or 2 family dwellings and submit it with payment (separate check from the CCO and zoning fees) to the Fire Prevention Bureau, 4400 New Jersey Avenue, Wildwood, NJ 08260, fax 609-522-4965 or email fireprev@wildwoodnj.gov. Credit cards are accepted with a 3% surcharge. The inspection is scheduled once the application is received; a failed inspection needs a re-inspection with a re-inspection fee (amount not stated).","Fire official in the NJ state directory, updated 8/21/2024: Jacob Spiegel · (609) 846-2030 · jspiegel@wildwoodnj.org","On-site inspection by the Wildwood Fire Prevention Bureau; do not apply until everything is in place","Smoke alarms in each sleeping room (City ordinance), outside (within 10 feet of) each sleeping area, and on every level","Hardwired smoke alarms must be replaced if more than 10 years past the manufacture date; battery smoke alarms must be sealed battery type","CO alarms outside (within 10 feet of) each sleeping area and on every level when there are fuel-burning appliances or an attached garage","Homes with a generator, solar panels, battery storage or other secondary power source need a printed label reading 'CAUTION: MULTIPLE SOURCES OF POWER.' within 18 inches of the main electrical panel and the electric meter (handwritten labels not accepted)","The January 2026 form does not list a fire extinguisher","Any outstanding fees on the property must be settled before the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Application received 10 or more business days before settlement","amount":"$75.00"},{"label":"Application received less than 10 business days before settlement","amount":"$150.00"},{"label":"Penalty for failing to obtain the certificate (up to)","amount":"$2,000.00"}]$j$::jsonb, $t$https://wildwoodnj.gov/firedepartment/images/CSACMAC%20Application%20FILLABLE.pdf$t$, $t$https://wildwoodnj.gov/firedepartment/prevention-inspections$t$, $j$[{"url":"https://wildwoodnj.gov/firedepartment/images/CSACMAC%20Application%20FILLABLE.pdf","label":"Official source (wildwoodnj.gov)"},{"url":"https://wildwoodnj.gov/firedepartment/prevention-inspections","label":"Official source (wildwoodnj.gov)"},{"url":"https://wildwoodnj.gov/firedepartment/index","label":"Official source (wildwoodnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Application for a Certificate of Smoke Alarm and Carbon Monoxide Alarm Compliance (CSACMAC), 1 or 2 Family Dwellings$t$, $t$865e708462df74fd7d60e1551d2c226eb53e67b31995c31a83c8fe7a7c2b3cb9$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":5,"fee_bad":0,"fee_unchecked":3,"quotes":15,"q_ok":8,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0514.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0514.json$t$, true),
  ($t$0813$t$, $t$Newfield Borough$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (Application for Certificate of Occupancy Pursuant to Ordinance, resale)$t$, $j$["Issued by: Borough of Newfield Construction Office","Contact: Derek Leary, Construction Official · 856-697-1100 ext. 11 or 16 (the 2021 form lists ext. 10)","How to apply: Fill out the Borough \"Application for Certificate of Occupancy Pursuant to Ordinance\" (check RESALE, give the settlement date, buyer and agents), sign it as the current owner and return it to Borough Hall, 18 Catawba Avenue (mail to PO Box 856, Newfield, NJ 08344) with the fee. Call the Construction Office to schedule. The Construction Official keeps office hours Wednesday 3:00 pm to 5:00 pm.","If the home has a private well, a copy of the well certification must be supplied before the CO can be issued","Form asks whether the dwelling is empty, the settlement date, buyer and both agents"]$j$::jsonb, $j$[{"label":"Certificate of Occupancy application (resale, rental or annual; 2021 form)","amount":"$75.00"},{"label":"Re-inspection (2021 form)","amount":"$30.00"}]$j$::jsonb, $t$https://www.newfieldborough.org/wp-content/uploads/2021/07/Certificate-of-Occupancy.pdf$t$, $t$https://www.newfieldborough.org/contact-us/$t$, $j$[{"url":"https://web.archive.org/web/20210731031050/https://www.newfieldborough.org/wp-content/uploads/2021/07/Certificate-of-Occupancy.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260615041939/https://www.newfieldborough.org/forms/","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260516144035/https://www.newfieldborough.org/contact-us/","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20190311153043/http://www.newfieldborough.org/wp-content/uploads/2018/04/Application-for-Occupancy.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$APPLICATION FOR CERTIFICATE OF OCCUPANCY PURSUANT TO ORDINANCE$t$, $t$87a211889cb65ed6ec8ddc57be5c6c3b7290b562db06d5833e66008bd9e5103e$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":6,"q_bad":2,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0813.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0813.json$t$, true),
  ($t$0813$t$, $t$Newfield Borough$t$, $t$GLOUCESTER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Entire borough: issued by Newfield Borough Construction Office (smoke detector compliance contact listed in the state fire directory)","Entire borough contact: Derek Leary, Construction Official · 856-697-1100","Entire borough, how to apply: Call the Borough Construction Office at 856-697-1100 and ask whether the smoke/CO check is part of the resale CO inspection.","Entire borough: issued by Gloucester County Fire Marshal's Office (county local enforcing agency for the Uniform Fire Code)","Entire borough contact: Shawn Layton, Chief County Fire Marshal · 856-307-7912 · gcfmo@co.gloucester.nj.us","Entire borough, how to apply: The state directory lists the Newfield Borough Construction Office (18 Catawba Ave, 856-697-1100) as the smoke detector compliance contact, so start with the Borough. The County Fire Marshal's Office is the fire code enforcing agency.","Fire official in the NJ state directory (county fire marshal), updated 6/16/2026: Shawn K Layton · (856) 307-7912 · slayton@co.gloucester.nj.us","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.newfieldborough.org/contact-us/$t$, $j$[{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.gloucestercountynj.gov/359/Office-of-the-Fire-Marshal","label":"Official source (gloucestercountynj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Addr: 18 Catawba Av Phone (856) 697-1100 SMOKE DETECTOR COMPLIANCE Newfield Boro Constr$t$, $t$fee71cd8a5e3323cd514c1310dba400b3ee2b9f58e848de2083147e1d9046e0d$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":6,"q_bad":2,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0813.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0813.json$t$, true),
  ($t$1201$t$, $t$Carteret Borough$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (Residential Certificate of Continued Occupancy)$t$, $j$["Issued by: Department of Code Enforcement (Building, Construction and Land Use Department)","Contact: Debbie Bialowarczuk, Inspector / Property Maintenance · 732-541-3925 · Building@carteret.net","How to apply: Fill out the Application for Certificate of Occupancy and the notarized Addendum for Residential Certificate of Continued Occupancy (owner, purchaser, realtor, closing date, attorneys, occupants). Submit it with payment to the Department of Code Enforcement, 61 Cooke Avenue, Carteret. Payment by cash, certified check, or attorney or broker check. The Building, Construction and Land Use page also says to email forms to SolteszJ@carteret.net.","Valid for: The form says the application is void 90 days from the date of issuance","Smoke detector on each level of the home","Smoke detector and carbon monoxide alarm outside each sleeping area, within 10 feet","All smoke detectors and carbon monoxide alarms in working order","Battery powered detectors and alarms must have 10 year sealed batteries","2A:10BC fire extinguisher mounted within 10 feet of the kitchen (form dated March 2020, before the 2025 state change)","All utilities working: HVAC, water heater, furnace, electric, water and sewer","No work done that needed a construction (UCC) or zoning permit without one, and no open permits","Exterior of the house not in disrepair","Grounds trimmed and free of debris","Concrete, asphalt and masonry not in disrepair, with no tripping hazards","List the names and ages of all occupants on the application","Owner signs a notarized certification on the Addendum","Also: Open permits: The CO addendum requires the owner to certify there is no unpermitted work and no open permits."]$j$::jsonb, $j$[{"label":"Certificate of Occupancy inspection, 1-family","amount":"$100.00"},{"label":"Certificate of Occupancy inspection, 2-family","amount":"$150.00"},{"label":"Temporary Certificate of Occupancy","amount":"$75.00"},{"label":"Name change (as printed on the form)","amount":"$50.00"},{"label":"Each additional inspection after the initial and one follow-up (non-compliance or no-show)","amount":"$50.00"}]$j$::jsonb, $t$https://www.carteret.net/wp-content/uploads/2020/05/Application-for-Residential-Certificate-of-Continued-Occupancy.pdf$t$, $t$https://www.carteret.net/construction-office-3/$t$, $j$[{"url":"https://www.carteret.net/wp-content/uploads/2020/05/Application-for-Residential-Certificate-of-Continued-Occupancy.pdf","label":"Official source (carteret.net)"},{"url":"https://www.carteret.net/building-construction-land-use-forms/","label":"Official source (carteret.net)"},{"url":"https://www.carteret.net/construction-office-3/","label":"Official source (carteret.net)"}]$j$::jsonb, $t$APPLICATION FOR CERTIFICATE OF OCCUPANCY$t$, $t$4ed12da80642c03c51112f362a2aea6584c29c60045e32e058823f77b814e458$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":16,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1201.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1201.json$t$, true),
  ($t$1201$t$, $t$Carteret Borough$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Carteret Fire Department, Fire Prevention (Fire Official) (town fire bureau)","Contact: Eric Wahl, Chief of Department/Fire Official · 732-541-8000 · wahle@carteret.net","How to apply: No smoke and CO certificate application or fee schedule is posted on the Borough website. The state fire directory lists the Borough Building Department at 732-541-3810 as the smoke detector compliance contact, and the Borough page lists 732-541-3810 as Building Inspection Scheduling. Call to confirm how to request the certificate.","Fire official in the NJ state directory, updated 7/31/2025: Eric Wahl · (732) 541-4387 · wahle@carteret.net","Borough CO addendum: battery powered smoke and CO alarms must have 10 year sealed batteries","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.carteret.net/fire-department/$t$, $j$[{"url":"https://www.carteret.net/fire-department/","label":"Official source (carteret.net)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.carteret.net/construction-office-3/","label":"Official source (carteret.net)"}]$j$::jsonb, $t$Chief of Department/Fire Official: Chief Eric Wahl$t$, $t$817fa816159e0f988bae440055cfad8bc38bce6f8c10ae634ec64f0add994287$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":16,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1201.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1201.json$t$, true),
  ($t$1203$t$, $t$Dunellen Borough$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate (new Certificate of Occupancy on change of ownership)$t$, $j$["Issued by: Construction Department, Borough of Dunellen","Contact: Scott Brescher, Construction Official / Building Sub-Code · 732-968-3323","How to apply: Fill out the Resale Certificate Registration form (closing date, location and unit, block/lot, owner, buyer, real estate agent, contact for inspection and email to send the certificate) and deliver it with payment to the Construction Department, second floor of Borough Hall, 355 North Avenue, Dunellen. The form has office fields for check or exact cash. Call the Construction Office to schedule.","All construction permits must be closed before a housing inspection can be scheduled","Application must be complete (closing date, block/lot, owner, buyer, agent, inspection contact, email for the certificate) or it will be denied","The Borough forms page lists this Resale Certificate as covering smoke and carbon monoxide compliance","Also: Open construction permits: No housing inspection can be scheduled until all construction permits are closed."]$j$::jsonb, $j$[{"label":"Initial inspection, per unit","amount":"$125.00"},{"label":"Two-family / multi-family, per unit","amount":"$125.00 x unit"},{"label":"Re-inspection","amount":"$80.00"},{"label":"Emergency inspection (added to the original inspection fee)","amount":"$150.00"}]$j$::jsonb, $t$https://www.dunellen-nj.gov/Documents/Departments/Construction/Resale%20Certificate%20Registration.pdf?t=202606031344260$t$, $t$https://www.dunellen-nj.gov/departments/construction/index.php$t$, $j$[{"url":"https://www.dunellen-nj.gov/Documents/Departments/Construction/Zoning_law__Chapter_115.pdf?t=202605131531450","label":"Official source (dunellen-nj.gov)"},{"url":"https://www.dunellen-nj.gov/Documents/Departments/Construction/Resale%20Certificate%20Registration.pdf?t=202606031344260","label":"Official source (dunellen-nj.gov)"},{"url":"https://www.dunellen-nj.gov/forms/index.php","label":"Official source (dunellen-nj.gov)"},{"url":"https://www.dunellen-nj.gov/departments/construction/index.php","label":"Official source (dunellen-nj.gov)"}]$j$::jsonb, $t$A new certificate of occupancy shall be required for any and all changes of ownership, tenancy or use.$t$, $t$e8ff2c514bcd88219f33b8cb82f8a8303b2828c844130b4bdb9ed71377b210da$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":5,"fee_bad":0,"fee_unchecked":4,"quotes":16,"q_ok":12,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1203.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1203.json$t$, true),
  ($t$1203$t$, $t$Dunellen Borough$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Entire borough (county agency): issued by Middlesex County Fire Marshal (county fire code enforcing agency)","Entire borough (county agency) contact: Michael Gallagher, Fire Official (Middlesex County Fire Marshal) · 732-316-7174 · mike.gallagher@co.middlesex.nj.us","Entire borough (county agency), how to apply: Not posted on the Borough site. The county office (1001 Fire Academy Drive, Sayreville) is listed by the state as the smoke detector compliance contact for Dunellen. Call to confirm the application and fee.","Entire borough: issued by Borough of Dunellen Construction Department (Resale Certificate - Smoke & Carbon Monoxide Compliance)","Entire borough contact: Scott Brescher, Construction Official / Building Sub-Code · 732-968-3323","Entire borough, how to apply: The Borough forms page labels its Resale Certificate Registration as \"Resale Certificate - Smoke & Carbon Monoxide Compliance\". Its fee ($125.00 per unit initial inspection) is listed under the town certificate; it is not a second charge.","Fire official in the NJ state directory (county fire marshal), updated 1/12/2026: Michael Gallagher · (732) 316-7174 · mike.gallagher@co.middlesex.nj.us","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Entire borough (county agency): Smoke/CO inspection, 10 or more business days before closing","amount":"$50.00"},{"label":"Entire borough (county agency): Smoke/CO inspection, less than 10 business days before closing","amount":"$75.00"},{"label":"Entire borough (county agency): Smoke/CO inspection, less than 4 business days before closing","amount":"$125.00"},{"label":"Entire borough (county agency): Reinspection after a failed inspection","amount":"$20.00"},{"label":"Entire borough (county agency): Not present for a scheduled inspection without notice","amount":"$75.00"}]$j$::jsonb, null, null, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.southrivernj.org/DocumentCenter/View/856/Smoke-Detector--Carbon-Monoxide-Detector-Inspection-PDF","label":"Official source (southrivernj.org)"},{"url":"https://www.dunellen-nj.gov/forms/index.php","label":"Official source (dunellen-nj.gov)"}]$j$::jsonb, $t$C Dunellen Borough$t$, $t$201c5be692bc1d9fef2a3f81a27a72dc16792e87c9a4c3f5f82cdbb71621d899$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":5,"fee_bad":0,"fee_unchecked":4,"quotes":16,"q_ok":12,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1203.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1203.json$t$, true),
  ($t$1204$t$, $t$East Brunswick Township$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per East Brunswick Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Steven R. Curtis, Construction Official · 732-390-6875 · scurtis@eastbrunswick.org"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.eastbrunswick.org/162/Continued-Certificate-of-Occupancy-Requi$t$, $j$[{"url":"https://www.eastbrunswick.org/162/Continued-Certificate-of-Occupancy-Requi","label":"Official source (eastbrunswick.org)"},{"url":"https://www.eastbrunswick.org/158/Construction-Inspection","label":"Official source (eastbrunswick.org)"}]$j$::jsonb, $t$Note: By Ordinance, East Brunswick Township does not require or issue a Certificate of Occupancy for residential resale or rentals.$t$, $t$3a8398d81cd1034f945213e607ea691d94b1b084669246f4a49ab00f077f178f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":23,"q_ok":22,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1204.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1204.json$t$, true),
  ($t$1204$t$, $t$East Brunswick Township$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["East Brunswick Bureau of Fire Safety, Fire…: issued by East Brunswick Bureau of Fire Safety, Fire Districts #1 and #3 (Fire Marshal's Office) (fire district). Covers: Homes in East Brunswick Fire District #1 or Fire District #3 (District #1 is the enforcing agency for District #3). District #3 is described by its fire company as about 4 square miles in the…","East Brunswick Bureau of Fire Safety, Fire… contact: Jaysen A. Whalen, Fire Marshal, Bureau of Fire Safety, East Brunswick Fire Dist. #1 & #3 · 732-651-8806 · JWhalen@ebfmo.org","East Brunswick Bureau of Fire Safety, Fire…, apply: Request at least two weeks before the closing or rental date; lowest fee when scheduled more than 10 days before closing","East Brunswick Bureau of Fire Safety, Fire…, how to apply: Use the online SMOKE/CO INSPECTION REQUEST form on the Fire Marshal's Office website (address, owner, buyer or tenant, requester email and phone, closing/rental date). Pay by credit card through the payment link on the site (debit cards not accepted). Questions: CSmith@ebfmo.org or 732-651-8806.","Fire District #2: issued by East Brunswick Fire District #2 Bureau of Fire Prevention (fire district). Covers: Homes in East Brunswick Fire District #2 (served by the East Brunswick Independent Fire Company)","Fire District #2 contact: 732-210-4582 · administrativeassistant@ebfd2.org","Fire District #2, apply: Ten or more business days before closing for the lowest fee; certificate valid six months","Fire District #2, how to apply: Download the Smoke Alarm Inspection Application from the District #2 Fire Prevention Forms page. Email it to administrativeassistant@ebfd2.org or bring it to 216 Joseph Street (William Peck Annex), East Brunswick. Checks payable to E.B. Bureau of Fire Prevention, Dist. 2; credit cards accepted (the Payments page has a pay link; include your invoice number). Inspections are Monday, Wednesday and Friday, 4:00 to 6:00 PM, and the certificate is issued on the spot when the home passes.","Fire official in the NJ state directory (fire district), updated 2/6/2026: Jaysen A Whalen · (732) 651-8806 · fireofficial@ebfmo.com","Districts 1 and 3: working hardwired or 10 year sealed battery smoke detector on each floor including the basement near the stairs, and within 10 feet of each bedroom; hardwired detectors must stay hardwired; detectors over 10 years old must be replaced; UL listed","Districts 1 and 3: a low voltage fire alarm system needs a passing inspection report from the alarm company, a NJ-certified fire protection contractor or a licensed electrician, shown to the inspector","Districts 1 and 3: CO detector in the hallway within 10 feet of any bedroom if the home has a fuel burning appliance or attached garage; stand-alone CO detectors no more than 7 years old, combination smoke/CO no more than 10 years old","Districts 1 and 3: house numbers at least 4 inches high (or at least 2 inches on both sides of a curbside mailbox), visible from the street and contrasting","District 2: alarm type depends on year built (before 1977 10 year sealed battery; 1977 to 1984 electric; 1984 to 1990 electric interconnected; after 1990 electric interconnected with battery back-up and one in each bedroom); CO alarm within 10 feet of each sleeping area","District 2: secondary power sources (solar, generator, etc.) must be properly labeled (new February 2025)","All districts: portable fire extinguisher recommended, not required (since February 2025)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"East Brunswick Bureau of Fire Safety, Fire…: Smoke/CO inspection scheduled more than 10 days before closing","amount":"$50.00"},{"label":"East Brunswick Bureau of Fire Safety, Fire…: Scheduled 4 to 10 days before closing","amount":"$75.00"},{"label":"East Brunswick Bureau of Fire Safety, Fire…: Scheduled 4 days or less before closing","amount":"$125.00"},{"label":"Fire District #2: Smoke/CO inspection, ten or more business days before closing","amount":"$50.00"},{"label":"Fire District #2: Less than ten business days before closing","amount":"$75.00"},{"label":"Fire District #2: Less than four business days before closing","amount":"$125.00"},{"label":"Fire District #2: Re-inspection for a failed inspection","amount":"$20.00"},{"label":"Fire District #2: No-show for a scheduled inspection without notice","amount":"$75.00"}]$j$::jsonb, $t$https://www.ebfmo.org/smoke-form.php$t$, $t$https://www.ebfmo.org/$t$, $j$[{"url":"https://www.ebfmo.org/","label":"Official source (ebfmo.org)"},{"url":"https://www.ebfmo.org/smoke-form.php","label":"Official source (ebfmo.org)"},{"url":"https://www.ebfmo.org/form/SmokeCOExtinguisherGuidelines03.pdf","label":"Official source (ebfmo.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.brookviewfire.com/","label":"Official source (brookviewfire.com)"},{"url":"https://firebasestorage.googleapis.com/v0/b/ebfd2-61921.appspot.com/o/forms%2FSmoke%20Alarm%20Inspection%20Application.pdf?alt=media&token=d21889d2-eeec-42d8-910e-a0c45b5440de","label":"Official source (firebasestorage.googleapis.com)"},{"url":"https://www.ebfd2.org/fireprevention/about","label":"Official source (ebfd2.org)"}]$j$::jsonb, $t$Residents of East Brunswick Fire District 1 and 3 selling or renting their home will need a “Certificate of Smoke alarm, carbon monoxide alarm” (CSACMAC).$t$, $t$efd8025df93904469813a51fb62d17980806ebafa152e5d9d931a10c470b9513$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":23,"q_ok":22,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1204.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1204.json$t$, true),
  ($t$1205$t$, $t$Edison Township$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale Certificate (Edison Certificate for Change of Ownership/Tenancy)$t$, $j$["Issued by: Code Enforcement, Township of Edison","Contact: 732-248-7257 · Resale@edisonnj.gov","Apply: Have the inspection done at least 3 weeks before closing (the form); the instruction page says at least 4 weeks","How to apply: Print the Residential Resale Certificate Application (Township Forms and Applications, Code Enforcement section), fill it out and email it to Resale@edisonnj.gov. Code Enforcement processes it and calls for payment by credit card. The form also accepts a certified check or money order; no cash, no personal checks, no refunds. Inspections are between 9:00 AM and 3:00 PM.","Smoke certificate from Fire Prevention must be issued before the Resale Certificate","Check for open permits; any work that needed a permit must get a compliance permit, be inspected and closed","Additions, alterations, finished basements or attics, garage conversions, patios, decks, pools and spas must have zoning and building approvals","Pool or spa: fence and childproof gate required","Handrails and guardrails secure and proper height; stair riser openings under 4 inches","Water heater, furnace, air conditioner and boiler installed with permits and working","Water heater: pressure relief valve, bonding cable, relief pipe (not black pipe) ending 6 inches from the floor, unthreaded","Oil and gas flue connections secure; gas appliances have shut-off valves","Clothes dryer vented outside","No openings in garage ceilings or walls next to living space","House numbers on the front of the house, at least 4 inches high","Existing GFI outlets working","No junk or debris in basement, attic or yard","No keyed locks on bedrooms; exit doors without a keyed inside lock","No imminent hazards","Also: Open permits and assessed improvements: Before the resale inspection, check with the Building Department for open permits and with the Tax Assessor that all improvements are assessed; unrecorded items may need permits even if a prior owner installed them."]$j$::jsonb, $j$[{"label":"Residential Resale Certificate (1 or 2 family)","amount":"$150"}]$j$::jsonb, $t$https://www.edisonnj.org/Residential%20Resale%20Certificate%20Application.pdf?t=202606091615470$t$, $t$https://www.edisonnj.org/document_center/index.php$t$, $j$[{"url":"https://www.edisonnj.org/Residential%20Resale%20Certificate%20Application.pdf?t=202606091615470","label":"Official source (edisonnj.org)"},{"url":"https://www.edisonnj.org/departments/engineering_department/code_enforcement.php","label":"Official source (edisonnj.org)"}]$j$::jsonb, $t$Note: As per Edison Township Ordinance 14-1.6 a Certificate must be obtained prior to closing of the property. Failure to do so will result in penalties and fines up to $2,000 as per Township ordinance.$t$, $t$0ea4e9225ea201322df308246560fb4e638586f5756098ebbe57029096964c8d$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":18,"q_ok":18,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1205.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1205.json$t$, true),
  ($t$1205$t$, $t$Edison Township$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Edison Division of Fire, Bureau of Fire Prevention (Fire Marshal's Office) (town fire bureau)","Contact: Daniel DiNuzzo, Fire Official / Fire Marshal (Bureau of Fire Prevention) · 732-248-7558 · ddinuzzo@edisonfd.org","Apply: Fees are based on alternating business days (by zip code) before the inspection; more than 10 alternating business days gets the lowest fee","How to apply: Fill out the Application for Certificate of Fire Prevention Compliance (CSACMASPSIL) and submit it in person at the Bureau of Fire Prevention, 100 Municipal Boulevard, Edison. Checks payable to Township of Edison. All fees are non-refundable, and after two failures or no-shows the full fee must be paid again. Inspections are between 9:00 am and 1:00 pm; certificates are valid for 180 days. Closing before the certificate is issued carries a $500 penalty.","Fire official in the NJ state directory, updated 9/2/2025: Daniel DiNuzzo · (732) 248-7244 · ddinuzzo@edisonfd.org","Battery smoke alarms must be 10 year sealed battery type; existing hardwired alarms cannot be replaced with battery alarms","Smoke alarms no more than 10 years old","Smoke alarm on every level including the basement (3 or more steps counts as a separate level), within 10 feet of bedroom doors; basement alarm on the ceiling or beam at the base of the stairs; finished loft or attic living space needs an alarm","Alarm type follows the year the house was built (hardwired and interconnected rules for homes built after 1977, and alarms in each bedroom for homes built from March 1991)","CO alarm within 10 feet of sleeping areas; a bedroom with a fuel burning appliance needs its own CO alarm; bring the CO alarm instructions to the inspection","Secondary power sources (solar, battery storage, installed generator) must be labeled per P.L.2025, c.19","Supervised or monitored alarm systems must be kept working at change of occupancy","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 alternating business days before inspection","amount":"$60.00"},{"label":"Request received 5 to 10 alternating business days before inspection","amount":"$90.00"},{"label":"Request received 1 to 4 alternating business days before inspection","amount":"$140.00"},{"label":"Failure to appear for a scheduled appointment without notice","amount":"$50.00"},{"label":"Re-inspection after a failed inspection","amount":"$20.00"},{"label":"Demolition letter","amount":"$25.00"}]$j$::jsonb, $t$https://www.edisonnj.org/Departments/Fire%20Division/2026%20Smoke%20Inspection%20Application%202026.pdf?t=202604150853340$t$, $t$https://www.edisonnj.org/departments/fire_division/index.php$t$, $j$[{"url":"https://www.edisonnj.org/Departments/Fire%20Division/2026%20Smoke%20Inspection%20Application%202026.pdf?t=202604150853340","label":"Official source (edisonnj.org)"},{"url":"https://www.edisonnj.org/Departments/Fire%20Division/2025%20Smoke%20Cert%20Requirements%20with%20dates.pdf?t=202509021201020","label":"Official source (edisonnj.org)"},{"url":"https://www.edisonnj.org/departments/fire_division/index.php","label":"Official source (edisonnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$This form MUST be submitted in person.$t$, $t$685f7c0145af16a84064f4d24065c7001834e07de0484344395fbca965795917$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":18,"q_ok":18,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1205.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1205.json$t$, true),
  ($t$1206$t$, $t$Helmetta Borough$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of continued occupancy (Certificate of Resale / Rental Compliance)$t$, $j$["Issued by: Borough of Helmetta Code Enforcement (Code Enforcer / Fire Marshal)","Contact: George Wallace, Code Enforcer/Fire Marshal · 732-521-4946 ext. 109 · G.Wallace@HelmettaBoro.com","How to apply: Complete the top of the Borough Application for Certificate (block/lot, owner, selling price, closing date, requested by owner or agent) and return it with a $100.00 check payable to the Borough of Helmetta, 51 Main Street, Helmetta. The smoke/CO application is a separate form with its own fee. Realtors are asked to give the Resale and Rental Inspection Checklist to the homeowner before the inspection.","Valid for: 90 days after issue date","Smoke alarms on all levels including attic spaces and basements; 10 year sealed battery or hardwired interconnected, less than 10 years old","Smoke and CO alarms within 10 feet of all sleeping areas (the resale packet copy says CO alarms less than 7 years old; the separate checklist says less than 10)","Walls, floors and ceilings in good condition, no holes","Working kitchen and bathrooms: hot and cold water with shut-off valves, drain traps, toilets secured with shut-off valve","Anti-tip device on stoves","Outlets, junction boxes and electrical equipment working with cover plates; panel openings closed; service cable secured","Water heater, boiler, furnace and HVAC working and vented; replacements must have a construction permit","Fireplaces, wood stoves and chimneys maintained","Exit doors working; no double keyed deadbolts (thumb-latch locks)","Windows operate; no broken panes or torn or missing screens","Gutters, leaders, roof and foundation in good repair","No extension cords used as permanent wiring (garage door openers, sump pumps and appliances plugged directly into outlets)","All open construction permits finalized","House numbers at least 4 inches high, visible from the curb; handrails on stairs with 3 or more risers","Yard maintained; pools protected with fences and self-closing, self-latching gates","Also: Open construction permits: All open construction permits must be finalized before the Certificate of Resale / Rental Compliance is issued."]$j$::jsonb, $j$[{"label":"Certificate application (resale)","amount":"$100.00"}]$j$::jsonb, $t$https://www.helmettaboro.com/FCpdf/Certificate%20of%20Occupancy%2Epdf$t$, $t$https://www.helmettaboro.com/cn/formcenter/?did=1718$t$, $j$[{"url":"https://www.helmettaboro.com/FCpdf/Certificate%20of%20Occupancy%2Epdf","label":"Official source (helmettaboro.com)"},{"url":"https://www.helmettaboro.com/FCpdf/Code%20Enforcement%20Information%2Edocx","label":"Official source (helmettaboro.com)"},{"url":"https://www.helmettaboro.com/FCpdf/Residential%20Resale%20and%20Rental%20Inspection%20Checklist%281%29%2Epdf","label":"Official source (helmettaboro.com)"},{"url":"https://www.helmettaboro.com/cn/contactinfo/?did=1731","label":"Official source (helmettaboro.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$PLEASE COMPLETE TOP PORTION AND RETURN WITH CHECK FOR $100.00 PAYABLE TO THE BOROUGH OF HELMETTA$t$, $t$ef6df50fae7609c32f899bcb6a56ce542046549f0fa62b89039783b511be92e7$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":15,"q_ok":9,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1206.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1206.json$t$, true),
  ($t$1206$t$, $t$Helmetta Borough$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Helmetta Bureau of Fire Prevention (Fire Marshal) (town fire bureau)","Contact: George Wallace, Code Enforcer/Fire Marshal · 732-521-4946 ext. 109 · G.Wallace@HelmettaBoro.com","Apply: Submit at least 7 days before the requested inspection date for the lowest fee; payment must be received before scheduling","How to apply: Fill out the Property Resale Residential Smoke Detector, Carbon Monoxide Detector, Fire Extinguisher Compliance Application (Building Dept. forms page) and submit it with a check payable to \"BOROUGH OF HELMETTA\" to the Bureau of Fire Prevention, 51 Main Street. Payment must be received before an inspection is scheduled. Questions: Fire Marshal, 732-521-4946 ext. 109.","Fire official in the NJ state directory, updated 2/13/2025: George Wallace · (732) 521-4946 · G.Wallace@HelmettaBoro.com","Smoke alarms: 10 year sealed battery type or hardwired interconnected, less than 10 years old, on all levels including attics and basements","CO alarms within 10 feet of all sleeping areas (less than 7 years old per the resale packet checklist)","The Borough resale smoke/CO form (January 2025) and fire checklist still list a fire extinguisher; they were written before P.L.2025, c.19 removed the state extinguisher requirement, so confirm with the Fire Marshal","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO inspection with seven days prior notice","amount":"$50.00"},{"label":"Less than seven days notice","amount":"$75.00"},{"label":"Less than 48 hours notice","amount":"$100.00"},{"label":"Re-inspection (inoperable, misplaced or missing smoke/CO detector)","amount":"$15.00"}]$j$::jsonb, $t$https://www.helmettaboro.com/FCpdf/Property%20Resale%281%29%2Epdf$t$, $t$https://www.helmettaboro.com/cn/formcenter/?did=1718$t$, $j$[{"url":"https://www.helmettaboro.com/FCpdf/Property%20Resale%281%29%2Epdf","label":"Official source (helmettaboro.com)"},{"url":"https://www.helmettaboro.com/FCpdf/Fire%20Inspection%20Checklist%20%28Helmetta%29%2Edocx","label":"Official source (helmettaboro.com)"},{"url":"https://www.helmettaboro.com/cn/contactinfo/?did=1731","label":"Official source (helmettaboro.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$PAYMENT MUST BE RECEIVED BEFORE ANY INSPECTION CAN BE SCHEDULED.$t$, $t$92e218c62346ed949f322b9b940f97b38b14cf5f16ff263329a1ccb2961bcf43$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":15,"q_ok":9,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1206.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1206.json$t$, true),
  ($t$1207$t$, $t$Highland Park Borough$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate$t$, $j$["Issued by: Department of Code Enforcement, Borough of Highland Park","Contact: Christian Sumano, Housing Inspector · 732-819-3797 · csumano@hpboro.com","How to apply: The owner or realtor submits the Resale Application (linked on the Borough Code Enforcement / Property Maintenance page) to the Department of Code Enforcement, 221 South 5th Avenue, Highland Park. Pay by check, cash (exact change) or money order payable to BOROUGH OF HIGHLAND PARK; no credit cards or online payment. Inspections are at the exact time the office gives; an adult 18 or older must be present to give access.","Valid for: Temporary Resale Certificate: up to 3 months (extension possible)","All open building permits must be closed before closing","Smoke/CO certificate from the Middlesex County Fire Marshal must be submitted to Code Enforcement before the final Resale Certificate is issued","Final water meter reading scheduled and done with the Tax/Water Department before closing","A Temporary Resale Certificate is possible when the home is not habitable at closing or the buyer accepts existing violations; the buyer then schedules the resale inspection","Also: Final water meter reading: Schedule and complete a final water meter reading with the Tax Collector/Water Department before closing (Maryann Auntenale, 732-819-3787).","Also: Open building permits: All open building permits must be closed before closing; ask the Construction Department at 732-777-6013. Non-owners must file an OPRA request with the Clerk for permit records."]$j$::jsonb, $j$[{"label":"Resale Application","amount":"$75"},{"label":"Temporary Resale Application (only when a Temporary Resale Certificate is used; in addition to the Resale Application)","amount":"$50"}]$j$::jsonb, $t$https://www.hpboro.com/home/showpublisheddocument/214/639160866633730000$t$, $t$https://www.hpboro.com/departments/construction/housing-inspections-1167$t$, $j$[{"url":"https://web.archive.org/web/20260607053145/https://www.hpboro.com/departments/construction/housing-inspections-1167","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$The owner of any residential building or dwelling unit, whether single-family or multi-family, must obtain a Resale Certificate before the change/transfer in ownership.$t$, $t$3e56fce59069e8e18a5db208f91209f309293d01b23af4abe46065a241539323$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":18,"q_ok":18,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1207.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1207.json$t$, true),
  ($t$1207$t$, $t$Highland Park Borough$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Middlesex County Office of the Fire Marshal (county fire code enforcing agency)","Contact: Michael Gallagher, Fire Official (Middlesex County Fire Marshal), per state directory · 732-316-7171 · firemarshal@co.middlesex.nj.us","How to apply: Request and register the Smoke/CO certificate with the Middlesex County Fire Marshal's Office, 1001 Fire Academy Drive, Sayreville (732-316-7171, firemarshal@co.middlesex.nj.us), then send a copy to Borough Code Enforcement. The Borough page links a smoke/CO document that could not be opened; the county website blocks automated access, so no fee schedule was found.","Fire official in the NJ state directory (county fire marshal), updated 1/16/2026: Michael Gallagher · (732) 316-7171 · mike.gallagher@co.middlesex.nj.us","The affidavit option is no longer available; an inspection by the Middlesex County Office of the Fire Marshal is required","A copy of the valid Smoke/CO Certificate must be given to Borough Code Enforcement","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO inspection, 10 or more business days before closing","amount":"$50.00"},{"label":"Smoke/CO inspection, less than 10 business days before closing","amount":"$75.00"},{"label":"Smoke/CO inspection, less than 4 business days before closing","amount":"$125.00"},{"label":"Reinspection after a failed inspection","amount":"$20.00"},{"label":"Not present for a scheduled inspection without notice","amount":"$75.00"}]$j$::jsonb, null, $t$https://www.hpboro.com/departments/construction/housing-inspections-1167$t$, $j$[{"url":"https://web.archive.org/web/20260607053145/https://www.hpboro.com/departments/construction/housing-inspections-1167","label":"Official source (web.archive.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.southrivernj.org/DocumentCenter/View/856/Smoke-Detector--Carbon-Monoxide-Detector-Inspection-PDF","label":"Official source (southrivernj.org)"}]$j$::jsonb, $t$A Smoke Detector and Carbon Monoxide (CO) Inspection is required at the time of change in occupancy or ownership in accordance with the NJ Uniform Fire Code (N.J.A.C. 5:70-2.3) and Middlesex County Fire Marshal Ordinance 10-1811.$t$, $t$783bc11bea7c6280f198fed01d7538e182f39f3d513aa40889eb67dece06845a$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":18,"q_ok":18,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1207.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1207.json$t$, true),
  ($t$1210$t$, $t$Middlesex Borough$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Sale / Re-Rent Certificate (Residential Resale Certificate)$t$, $j$["Issued by: Department of Code Enforcement, Zoning and Construction","Contact: Matthew Dillingham, Director of Code Enforcement and Zoning · 732-356-7400 ext. 260 · zoning@middlesexboro-nj.gov","How to apply: Fill in Sections 1 and 2 of the Borough's Residential Sale / Re-Rent Application (fillable PDF) and return them with the Middlesex Borough Police Department resident form (new buyer's information) and a check payable to Middlesex Borough for $125 to the Construction/Code Enforcement office, 1200 Mountain Avenue, Middlesex, NJ 08846. The smoke/CO part (Section 3) goes separately to the Middlesex County Fire Marshal; the Borough does not accept that form or its payment.","Smoke alarm on each floor, including the basement, within 10 feet of all sleeping areas (the Borough sheet says alarms must be within 7 years of the manufacture date)","CO alarm within 10 feet of all sleeping areas, outside the rooms","Fire extinguisher mounted within 10 feet of the kitchen, ABC type, 2.5 to 10 pounds","Running water, working electric service and at least one flushable toilet","Handrails and guards on steps of 3 or more risers or 30 inches","Well water and/or septic report from the Board of Health, if applicable","Water heater grounded (jump bonded); relief discharge tube not reduced and ending within 6 inches of the floor","Solid aluminum dryer vent pipe, not flex pipe","Anti-tilt device on the stove","House numbers visible from the street","Exit doors open from inside without a key or special knowledge","No mold or water damage","Any outstanding Borough fines or liens paid in full","New owner's Resident Info (Police Department emergency file) form must be turned in before inspections are scheduled; the property will be photographed","Change of title only (vacant, not yet habitable home): floor plan layout of all floors","Also: Police Department resident emergency file / alarm registration form: The resale packet's last page is a Middlesex Borough Police Department 'Resident Emergency File/Alarm Registration Form' that must be returned with the new buyer's information. It notes an initial $25.00 registration fee for residential alarm systems.","Also: Outstanding fines or liens: The Borough's resale checklist says any outstanding fines or liens must be paid in full before the certificate is issued."]$j$::jsonb, $j$[{"label":"Residential Sale / Re-Rent inspection, per unit","amount":"$125.00"}]$j$::jsonb, $t$https://www.middlesexboro-nj.gov/s/Updated-ResidentialSaleRe-RentCertificateApplication-1.pdf$t$, $t$https://www.middlesexboro-nj.gov/zoningcode-enforcement$t$, $j$[{"url":"https://www.middlesexboro-nj.gov/construction","label":"Official source (middlesexboro-nj.gov)"},{"url":"https://www.middlesexboro-nj.gov/s/Updated-ResidentialSaleRe-RentCertificateApplication-1.pdf","label":"Official source (middlesexboro-nj.gov)"},{"url":"https://www.middlesexboro-nj.gov/forms","label":"Official source (middlesexboro-nj.gov)"},{"url":"https://www.middlesexboro-nj.gov/zoningcode-enforcement","label":"Official source (middlesexboro-nj.gov)"}]$j$::jsonb, $t$When selling a residential home, the actual CO needed is a Residential Resale Certificate.$t$, $t$b5bfc66b1d5bfad4a6f7abf7f9aac1a7b2dc5be4a7289c78a2031bbd151e2a83$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":19,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1210.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1210.json$t$, true),
  ($t$1210$t$, $t$Middlesex Borough$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Middlesex County Fire Marshal's Office","Contact: Michael Gallagher, Fire Official (Middlesex County Fire Marshal) · 732-316-7171 · mike.gallagher@co.middlesex.nj.us","Apply: Apply 10 or more business days before closing for the lowest County fee","How to apply: Complete Section 3 of the Borough packet (the Middlesex County Fire Marshal 'Smoke & Carbon Monoxide Detector Application') and send it to the County Fire Marshal, not the Borough; the Borough's instructions say to email it to firemarshal@co.middlesex.nj.us. Middlesex County Fire Marshal, 1001 Fire Academy Drive, Sayreville, NJ 08879, phone 732-316-7171.","Fire official in the NJ state directory (county fire marshal), updated 2/6/2026: Michael Gallagher · (732) 316-7174 · mike.gallagher@co.middlesex.nj.us","County letter: smoke alarms on every level (basement, first and second floors, not crawl spaces or unfinished attics) and within 10 feet of sleeping rooms; no older than 10 years or the maker's expiration date","County letter: CO alarm outside each separate sleeping area; no older than 5 years or the maker's expiration date (other County pages say 7 years for stand-alone CO alarms)","County letter: house numbers at least 4 inches high, visible from the street and in a contrasting color (2 inches if on both sides of a curbside mailbox)","County letter: smoke/CO alarms, house numbers and fire extinguisher must all comply; certificate is issued at the inspection and valid for 6 months","Smoke alarms within 10 feet of every bedroom and at least one on every floor, including finished and unfinished basements (not needed in an unfinished attic)","Smoke alarms may not be more than 10 years old; stand-alone CO alarms not more than 7 years old; combination alarms not more than 10 years old","A hard-wired smoke alarm must be replaced with a hard-wired alarm","A replacement battery smoke alarm must have a sealed 10-year lithium battery","Fire extinguisher (listed on the County form in the Borough's 2026 packet): 2-A:10-B:C, about 5 pounds, wall-mounted on the way out of the kitchen, no higher than 5 feet, with a receipt or NJ licensed contractor tag from the past 12 months","Homes built 1984 or later need interconnected electric alarms; homes built 1990 or later also need battery backup and an alarm in each bedroom","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"County smoke/CO inspection, 10 or more business days before closing","amount":"$50.00"},{"label":"County smoke/CO inspection, less than 10 business days before closing","amount":"$75.00"},{"label":"County smoke/CO inspection, less than 4 business days before closing","amount":"$125.00"},{"label":"Reinspection after a failed inspection","amount":"$20.00"},{"label":"Not present for a scheduled inspection without notice","amount":"$75.00"},{"label":"Smoke/CO/extinguisher inspection (County Fire Marshal), as stated on the Borough's 2026 resale packet","amount":"$50"},{"label":"Smoke/CO certificate fee on the County's 2020 self-inspection affidavit form (archived copy)","amount":"$50"}]$j$::jsonb, $t$https://www.middlesexboro-nj.gov/s/Updated-ResidentialSaleRe-RentCertificateApplication-1.pdf$t$, null, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.middlesexboro-nj.gov/s/Updated-ResidentialSaleRe-RentCertificateApplication-1.pdf","label":"Official source (middlesexboro-nj.gov)"},{"url":"https://web.archive.org/web/20201128112400/http://www.middlesexcountynj.gov/Government/Departments/PSH/Documents/Fire-Marshal/Residential%20Smoke%20Detector%20and%20Carbon%20Monoxide%20Inspection%20Info%20and%20Application.pdf","label":"Official source (web.archive.org)"},{"url":"https://www.southrivernj.org/DocumentCenter/View/856/Smoke-Detector--Carbon-Monoxide-Detector-Inspection-PDF","label":"Official source (southrivernj.org)"}]$j$::jsonb, $t$C Middlesex Borough$t$, $t$0a140ca04d1e08c93668e68b877d4b79ca0c9a3248f16ade6c08f71a6e2d52bb$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":19,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1210.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1210.json$t$, true),
  ($t$1213$t$, $t$New Brunswick$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Code Compliance (owner-occupied 1-2 family sold to an owner-occupant: Letter of Exemption instead)$t$, $j$["Issued by: Bureau of Housing Inspections, Division of Community Services","Contact: Alex Adkins, Director of Inspections · 732-745-5075","How to apply: Download the Code Compliance application (or, for an owner-occupied 1-2 family home sold to an owner-occupant, the no-fee Letter of Exemption application plus the notarized Buyer's and Seller's Affidavits) from the Housing Inspection Forms page, fill in every field, and submit it to the Bureau of Housing Inspections, Civic Square, 25 Kirkpatrick Street, New Brunswick, NJ 08903, with a check (write your phone number on the check). Fees are non-refundable.","Inspection checks for Building, Zoning and Property Maintenance Code violations; the seller must fix any violations before the sale","Required for all residential sales except owner-occupied 1-2 family homes","Owner-occupied 1-2 family home sold to a buyer who will live there: apply for a no-fee Letter of Exemption with a notarized Seller's Affidavit and Buyer's Affidavit","With the exemption, the buyer takes responsibility that all alterations, additions and renovations have zoning approval and valid construction permits; the seller must hand over those approvals and permits at closing","The smoke alarm/CO certificate is still required even with a Letter of Exemption"]$j$::jsonb, $j$[{"label":"Code Compliance inspection, one- or two-family dwelling","amount":"$40.00"},{"label":"Code Compliance inspection, each additional unit","amount":"$20.00"},{"label":"Letter of Exemption (owner-occupied 1-2 family sold to an owner-occupant)","amount":"NO FEE"}]$j$::jsonb, $t$https://www.cityofnewbrunswick.org/Code%20Compliance%20Application%20with%20Fee%20-%20S%20Edit%202021-0908%20MASTER.pdf$t$, $t$https://www.cityofnewbrunswick.org/residents/services/housing_inspections.php$t$, $j$[{"url":"https://www.cityofnewbrunswick.org/Code%20Compliance%20Application%20with%20Fee%20-%20S%20Edit%202021-0908%20MASTER.pdf","label":"Official source (cityofnewbrunswick.org)"},{"url":"https://www.cityofnewbrunswick.org/Sellers%20Affidavit%20-%20S%20Edit%202021-0226%20-%20MASTER.pdf","label":"Official source (cityofnewbrunswick.org)"},{"url":"https://www.cityofnewbrunswick.org/Buyers%20Affidavit%20-%20S%20Edit%202021-0226%20-%20MASTER.pdf","label":"Official source (cityofnewbrunswick.org)"},{"url":"https://www.cityofnewbrunswick.org/residents/departments/forms.php","label":"Official source (cityofnewbrunswick.org)"},{"url":"https://www.cityofnewbrunswick.org/residents/services/housing_inspections.php","label":"Official source (cityofnewbrunswick.org)"},{"url":"https://www.cityofnewbrunswick.org/Code%20Compliance%20Application%20Owner%20to%20Owner%20NO%20FEE%20-%20S%20Edit%202021-0226%20-%20MASTER.pdf","label":"Official source (cityofnewbrunswick.org)"}]$j$::jsonb, $t$Chapter 15.12 of the Revised General Ordinance requires that all residential, other than single and two-family, owner-occupied dwellings must be inspected by the Bureau of Housing Inspections to verify if any Building, Zoning, or Property Maintenance Code Violations exist.$t$, $t$41542f930b6a668eeea0129e0308ccee91a182af9c20861388a3c4ea466b0e43$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":18,"q_ok":18,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1213.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1213.json$t$, true),
  ($t$1213$t$, $t$New Brunswick$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: New Brunswick Fire Department, Division of Fire Safety (town fire bureau)","Contact: Victor Ortiz, Fire Official · 732-745-5086 · vortiz@cityofnewbrunswick.org","How to apply: Apply online through the City's SDL Portal (create an account first, then use the Smoke Alarm request). The Division of Fire Safety is at 78 Bayard Street, New Brunswick, NJ 08901, 732-745-5086.","Fire official in the NJ state directory, updated 6/4/2026: Victor Ortiz · (732) 745-5086 · vortiz@cityofnewbrunswick.org","Smoke alarms no older than 10 years, on every level and within 10 feet of sleeping rooms; on the ceiling or on the wall within 6 inches of the ceiling, at least 3 feet from ceiling fan blades and heating/AC registers","CO alarms no older than 7 years, on every level with sleeping rooms and within 10 feet of those rooms","10-year sealed battery smoke alarms required in 1-2 family homes; AC-powered (hard-wired) alarms may never be replaced with 10-year sealed battery alarms","Failure to obtain the certificate carries a $500.00 penalty","The City's April 2025 sheet still uses the older certificate name that includes a portable fire extinguisher, but it lists no extinguisher item","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/middlesex/newbrunswick/requests/smokeAlarm$t$, $t$https://www.cityofnewbrunswick.org/residents/public_safety/fire/fire_prevention.php$t$, $j$[{"url":"https://www.cityofnewbrunswick.org/residents/public_safety/fire/fire_prevention.php","label":"Official source (cityofnewbrunswick.org)"},{"url":"https://www.cityofnewbrunswick.org/residents/public_safety/fire/forms___information.php","label":"Official source (cityofnewbrunswick.org)"},{"url":"https://www.cityofnewbrunswick.org/CSACMAPFECC%20info%20sheet%20-%20S%20edit%202025-0404%20MASTER.pdf","label":"Official source (cityofnewbrunswick.org)"},{"url":"https://www.cityofnewbrunswick.org/residents/public_safety/fire/contact_information.php","label":"Official source (cityofnewbrunswick.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$This Division also conducts SMOKE DETECTOR and CARBON MONOXIDE ALARM compliance inspections on all one and two family homes for sale or lease in the City.$t$, $t$af7ff725701bec559b6b29bae698a200ccac6b01850ca92a0d8daab8a5d8894e$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":18,"q_ok":18,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1213.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1213.json$t$, true),
  ($t$1214$t$, $t$North Brunswick Township$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Home Sale Certificate$t$, $j$["Issued by: Building Division (Construction Official), Department of Community Development","Contact: Tom Paun, Construction Official/Building Subcode · 732-247-0922 ext. 450 · TWPNBcommdev@northbrunswicknj.gov","Apply: Start as early as possible before closing so open permits, inspections or unpermitted work can be cleared","How to apply: Fill out the Application for a Home Sale Certificate (both sides), sign the certification in front of a notary, and submit it with the fee payable to the Township of North Brunswick to the Building Division, 710 Hermann Road, North Brunswick, NJ 08902 (732-247-0922 ext. 450, TWPNBcommdev@northbrunswicknj.gov).","Valid for: 120 days; one administrative extension of up to 30 days","Township reviews the property's permit and inspection history","No open or outstanding construction permits or inspections","Permitted work must have its final approvals","Any work done without a required permit must be permitted and inspected (the form asks about A/C, furnace, boiler and water heater replacements in the past 10 years, plus generator, radon system, addition, finished basement, fireplace or wood stove, shed over 200 sq ft, pool, hot tub, deck and gazebo)","Owner signs a notarized certification on the application","Permits and Certificates of Approval issued through this process are sent to the Tax Assessor and can lead to an added assessment","If the seller will not do it, the buyer's attorney can request a waiver on law firm letterhead so the buyer takes on the Home Sale Certificate after closing; the home cannot be occupied during renovations (other than minor work) until the certificate is issued"]$j$::jsonb, $j$[{"label":"Home Sale Certificate, single-family home","amount":"$150"},{"label":"Home Sale Certificate, condo, townhouse or mobile home","amount":"$125"}]$j$::jsonb, $t$https://www.northbrunswicknj.gov/DocumentCenter/View/1219$t$, $t$https://www.northbrunswicknj.gov/204/Selling-Your-Home$t$, $j$[{"url":"https://www.northbrunswicknj.gov/204/Selling-Your-Home","label":"Official source (northbrunswicknj.gov)"},{"url":"https://www.northbrunswicknj.gov/DocumentCenter/View/1219","label":"Official source (northbrunswicknj.gov)"},{"url":"https://www.northbrunswicknj.gov/DocumentCenter/View/1221","label":"Official source (northbrunswicknj.gov)"},{"url":"https://www.northbrunswicknj.gov/m/directory/department?did=35","label":"Official source (northbrunswicknj.gov)"},{"url":"https://web.archive.org/web/20260903060730/https://northbrunswicknj.gov/wp-content/uploads/2026/07/FIRE-MARSHAL-HOME-SALE-REQUIREMENTS-JUL-2026.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$A Home Sale Certificate is required for residential property sales and helps ensure that permits and required inspections associated with the property have been properly completed before the sale.$t$, $t$0781a63cb44b27b8b8e173cc964d24a4f34a91ea1e256270d12a4673d97a340c$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":19,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1214.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1214.json$t$, true),
  ($t$1214$t$, $t$North Brunswick Township$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: North Brunswick Fire Prevention Bureau (Fire Marshal's Office) (town fire bureau)","Contact: Daryle Masters, Fire Marshal · 732-247-0922 ext. 290 · dmasters@northbrunswicknj.gov","Apply: Apply 10 or more business days before closing for the lowest fee; the certificate expires 60 days after issue","How to apply: Complete the Fire Marshal's 'Application for a Certificate of Compliance of Smoke Alarms, Carbon Monoxide Alarms, and Portable Fire Extinguishers' (page 2 of the Fire Marshal Home Sale Requirements sheet) and pay in advance with a check payable to 'Township of North Brunswick'; the office then schedules the inspection. Fire Prevention Bureau, 710 Hermann Road, 732-247-0922 ext. 453. The current Township website does not post the sheet; the July 2026 version is available as an archived copy.","Fire official in the NJ state directory (town), updated 1/21/2026: Daryle F Masters · (732) 247-0922 · dmasters@northbrunswicknj.gov","Smoke alarms on every level including basements (not attics or crawl spaces) and outside each sleeping area","Battery smoke alarms must be 10-year sealed battery alarms; existing hard-wired alarms must be kept and cannot be replaced by battery units","CO alarm within 10 feet of every bedroom (battery, hard-wired or plug-in; combination smoke/CO alarms are acceptable)","Fire extinguisher still required on the July 2026 sheet: listed, labeled, charged and operable, rated at least 2A:10BC (4, 5 or 6 lb ABC), under the kitchen sink or within 10 feet of the kitchen exit path; it does not need to be mounted","Application and payment must be made before an inspection is scheduled","Certificate valid for 60 days and not transferable","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO/extinguisher inspection, requested 10 business days ahead","amount":"$50"},{"label":"Smoke/CO/extinguisher inspection, requested 6 to 9 business days ahead","amount":"$100"},{"label":"Smoke/CO/extinguisher inspection, requested 5 business days ahead","amount":"$150"},{"label":"Additional fee for a two-family home (and each additional unit in a multi-family home)","amount":"$50"},{"label":"Missed appointment or reinspection","amount":"$25"}]$j$::jsonb, $t$https://web.archive.org/web/20260903060730/https://northbrunswicknj.gov/wp-content/uploads/2026/07/FIRE-MARSHAL-HOME-SALE-REQUIREMENTS-JUL-2026.pdf$t$, $t$https://www.northbrunswicknj.gov/212/Fire-Prevention-Bureau$t$, $j$[{"url":"https://www.northbrunswicknj.gov/212/Fire-Prevention-Bureau","label":"Official source (northbrunswicknj.gov)"},{"url":"https://www.northbrunswicknj.gov/m/directory/department?did=18","label":"Official source (northbrunswicknj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://web.archive.org/web/20260903060730/https://northbrunswicknj.gov/wp-content/uploads/2026/07/FIRE-MARSHAL-HOME-SALE-REQUIREMENTS-JUL-2026.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$The Office conducts inspections throughout the Township to ensure compliance with the New Jersey Uniform Fire Code$t$, $t$30e983bf0c545813c6146e3b2acc72a320089495c9acbcb1d4e567dc163adc02$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":19,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1214.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1214.json$t$, true),
  ($t$1216$t$, $t$Perth Amboy$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Code Compliance$t$, $j$["Issued by: Department of Code Enforcement (Housing inspection) with the Fire Prevention inspection","Contact: Irving Lozada, Director of Code Enforcement · 732-826-0183","Apply: If no violations are found, a permanent certificate can be issued within 7 to 10 days","How to apply: Complete the Certificate of Code Compliance Application (with the emergency contact page) and submit it to the Department of Code Enforcement, 375 New Brunswick Avenue, Perth Amboy, NJ 08861, with a check or money order (cash is not accepted). Residents with a senior citizen exemption on their tax bill are exempt from the fees.","Exterior: no flaking or peeling paint; street numbers at least 3 inches; no holes or cracks in foundation and walls; trim, chimneys, windows, handrails, guards, sidewalks and steps in good repair","Unused oil tanks removed or filled with a permit","All open permits must have final approval","GFI outlets outside and in kitchens, baths and laundry areas (within 6 feet of water); covers on all outlets and switches; globes on light fixtures","Interior walls, trim, floors, ceilings and carpets in good, clean condition; bath and kitchen floors non-porous","Windows operable, stay open and have locks; windows and doors weather tight","Furnace safe with a red-marked emergency shut-off; flue connections tight; water heater relief valve extension tube within 6 inches of the floor","Door from garage to living space must be fire rated","Plumbing fixtures and appliances working; cabinets secured with handles","No infestation; unit clean and ready for occupancy","Fireplaces and wood stoves certified by a certified chimney sweep","No keyed locks or deadbolts on interior doors","Buyer must give a notarized letter that the attic, basement and garage will not be used as sleeping rooms or rental units","Two-family or larger homes, or a one-family bought as a rental, must be registered as rental property by the buyer","Conditional 45-day certificate possible with the buyer's notarized letter taking responsibility for violations; not issued with any fire violations","Also: Open permits: All open permits must have a completed, passed final inspection before the Certificate of Code Compliance is issued.","Also: Rental registration: Since November 1, 2018, all 2-family or larger properties, and any 1-family bought as a rental, must be registered by the buyer with the Office of Housing & Social Services, 1 Olive Street, (732) 826-4300."]$j$::jsonb, $j$[{"label":"Housing inspection, single dwelling unit","amount":"$40.00"},{"label":"Housing inspection, two dwelling units","amount":"$80.00"},{"label":"Residential unit reinspection","amount":"$25.00"}]$j$::jsonb, $t$https://www.perthamboynj.org/common/pages/GetFile.ashx?key=NpIQAdls$t$, $t$https://www.perthamboynj.org/government/departments/code_enforcement$t$, $j$[{"url":"https://www.perthamboynj.org/common/pages/GetFile.ashx?key=NpIQAdls","label":"Official source (perthamboynj.org)"},{"url":"https://www.perthamboynj.org/government/departments/code_enforcement","label":"Official source (perthamboynj.org)"}]$j$::jsonb, $t$CERTIFICATE OF CODE COMPLIANCE APPLICATION$t$, $t$fd7f555a69a4a40af47474f412d673baac0fdaf8fed07b0fb0d087f641927522$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1216.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1216.json$t$, true),
  ($t$1216$t$, $t$Perth Amboy$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Perth Amboy Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Kevin R Metz, Fire Official · 732-826-0183 · kmetz@perthamboynjfd.org","How to apply: The Fire Prevention fee is listed on the City's Certificate of Code Compliance application, submitted to Code Enforcement at 375 New Brunswick Avenue (the same building as Fire Headquarters). The Fire Department's Fire Prevention Forms page also lists an 'FPB Resale Checklist' and a code compliance application, but those files did not download.","Fire official in the NJ state directory, updated 1/21/2026: Kevin R Metz · (732) 826-0183 · kmetz@perthamboynjfd.org","The Code Compliance packet says smoke alarm, CO alarm and fire extinguisher rules are listed in the full packet; those pages were not in the online file","A conditional certificate will not be issued with any fire violations","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire Prevention inspection, single dwelling unit (paid with the Certificate of Code Compliance application)","amount":"$100.00"},{"label":"Fire Prevention inspection, two dwelling units (paid with the Certificate of Code Compliance application)","amount":"$150.00"}]$j$::jsonb, $t$https://www.perthamboynj.org/common/pages/GetFile.ashx?key=NpIQAdls$t$, $t$https://www.perthamboynj.org/government/departments/fire$t$, $j$[{"url":"https://www.perthamboynj.org/government/departments/fire","label":"Official source (perthamboynj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.perthamboynj.org/common/pages/GetFile.ashx?key=NpIQAdls","label":"Official source (perthamboynj.org)"}]$j$::jsonb, $t$The Fire Department runs the Bureau of Fire Prevention.$t$, $t$186ce6fc477224772e4ec65f3bd1213e3d7dfc995b602c66693dc449874ee63c$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1216.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1216.json$t$, true),
  ($t$1217$t$, $t$Piscataway Township$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Municipal Certificate of Continued Compliance (MCCC)$t$, $j$["Issued by: Municipal Certificate of Continued Compliance (MCCC) Office, Department of Community Development (Property Maintenance), 505 Sidney Road","Contact: Ben Pobicki, Supervisor of Property Maintenance / MCCC · 732-562-2393 · mccc@piscatawaynj.org","Apply: Township strongly recommends applying at least 4 weeks before the closing date; an inspection date may be up to 10 days after the application is submitted","How to apply: Fill out the 'Sale of Residential Property' MCCC application and bring or send it with the fee to the MCCC Office at the Public Works Center, 505 Sidney Road, Piscataway, NJ 08854. The office then schedules the inspection (Monday to Friday, 8:00 a.m. to 12:00 p.m. and 1:30 to 3:30 p.m.). The inspection report and approved MCCC are emailed to the owner.","All utilities (gas, water, electric) must be on at the time of inspection","Gutters, downspouts, sidewalk, driveway, apron, stairs, chimney and siding in good condition","Screens on windows and doors of habitable rooms; all windows operable, no broken or cracked glass","Guardrails and graspable handrails on stairs with 4 or more risers or more than 30 inches high","House number at least 3 inches high on the house or mailbox","Tree limbs off the house; trees and shrubs cut back 12 inches from the house","Driveway must be paved or another hard surface (no stone or gravel)","GFCI outlets outdoors, in bathrooms, kitchens, laundry areas, garages, unfinished basements and within 6 feet of any sink","At least 2 outlets per habitable room; working lights in halls, stairs, baths, laundry and furnace rooms","No plumbing leaks; flexible drain piping must be replaced; water heater relief valve with extension within 6 inches of the floor","Gas shut-off valve behind gas stove and dryer; stove anti-tip bracket","Bath ventilation (window or fan); safety glazing on windows in tub or shower areas","Solid core or steel 20-minute rated door between garage and house","Smoke and CO alarms within 10 feet of sleeping areas and on every level including the basement; 10-year sealed battery alarms; hardwired alarms under 10 years old","Licensed-professional letters for the heating unit and fireplace, plus septic and well water test results if applicable; any work done without a required permit must be permitted and all permits closed","Also: Open or unpermitted work: Any work done without a required permit must be permitted and all open permits closed before the MCCC is issued, even if a prior owner did the work.","Also: Heating, fireplace, septic and well documents: If applicable, provide a licensed professional's letter that the heating unit is clean and working, a fireplace letter, septic inspection and clean-out proof, and a passing well water test from a state certified lab.","Also: Finished basement permit: The MCCC checklist says a finished basement permit is required, even if the basement was finished when the home was bought."]$j$::jsonb, $j$[{"label":"MCCC, single-family home, condo or townhome","amount":"$150"},{"label":"MCCC, two-family","amount":"$300"},{"label":"Temporary MCCC (after applying for an MCCC)","amount":"$125"},{"label":"Reinspection, third inspection and each one after","amount":"$100"}]$j$::jsonb, $t$https://www.piscatawaynj.org/Document_Center/Department/Community%20Development/MCCC/MCCC%20Sale%20of%20Property%20form%202026.pdf$t$, $t$https://www.piscatawaynj.org/departments/community_development/municipal_certificate_of_continued_compliance_(mccc)/index.php$t$, $j$[{"url":"https://www.piscatawaynj.org/departments/community_development/municipal_certificate_of_continued_compliance_(mccc)/index.php","label":"Official source (piscatawaynj.org)"},{"url":"https://www.piscatawaynj.org/departments/community_development/municipal_certificate_of_continued_compliance_(mccc)/applications_forms_helpful_information.php","label":"Official source (piscatawaynj.org)"},{"url":"https://www.piscatawaynj.org/Document_Center/Department/Community%20Development/MCCC/MCCC%20Sale%20of%20Property%20form%202026.pdf","label":"Official source (piscatawaynj.org)"},{"url":"https://www.piscatawaynj.org/Document_Center/Department/Community%20Development/MCCC/MCCC%20Checklist%202026.pdf","label":"Official source (piscatawaynj.org)"}]$j$::jsonb, $t$As of January 1, 2019, a Municipal Certificate of Continued Compliance (MCCC) is required when selling or renting a home in Piscataway to ensure the health, safety and general welfare of residents.$t$, $t$3e6cedaf6cfe5c497a1d11bd077e35ee70ad27e0927ad38de6a5406ba40a7424$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1217.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1217.json$t$, true),
  ($t$1217$t$, $t$Piscataway Township$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Piscataway Township Fire Prevention Bureau (town fire bureau)","Contact: Matt Jandernal, Fire Marshal · 732-562-2315 · fireprevention@piscatawaynj.org","Fire official in the NJ state directory (town), updated 6/4/2026: Matthew Jandernal · (732) 562-2315 · mjandernal@piscatawaynj.org","Township MCCC checklist: battery smoke alarms must be the sealed 10-year battery type; hardwired (110v) smoke alarms must be less than 10 years old and must not be replaced with battery alarms","Township MCCC checklist: smoke and CO alarms within 10 feet of each sleeping area and on each level of possible living space, including the basement even if unfinished (not attic or crawl space)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.piscatawaynj.org/departments/fire_prevention_bureau/index.php$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.piscatawaynj.org/departments/fire_prevention_bureau/index.php","label":"Official source (piscatawaynj.org)"},{"url":"https://www.piscatawaynj.org/Document_Center/Department/Community%20Development/MCCC/MCCC%20Checklist%202026.pdf","label":"Official source (piscatawaynj.org)"}]$j$::jsonb, $t$M Piscataway Township$t$, $t$df96971279aa088d6f8c30a04da23aff4b2675b3929cd9e5cadda20f72cbe3a6$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1217.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1217.json$t$, true),
  ($t$1218$t$, $t$Plainsboro Township$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Housing Certificate of Occupancy (Resale Inspection)$t$, $j$["Issued by: Housing Division, Department of Code Enforcement","Contact: Nicole Flagg, Housing Official · 609-799-0909 ext. 1220 · nflagg@plainsboronj.com","Apply: Apply early: the Township FAQ says the current wait for an inspection is about 1 month because of seasonal volume","How to apply: Submit the online Resale Inspection Application (with online payment) on the Township Form Center, or contact the Housing Division at 641 Plainsboro Road, Plainsboro, NJ 08536 (609-799-0909 ext. 1214, housingdivision@plainsboronj.com). A Buyer's Acceptance Form is also available online.","Valid for: 90 days","Smoke alarms tested; interconnected alarms must all sound together; smoke alarms replaced every 10 years (NFPA 72)","Smoke alarms at least 3 feet from air vents or bathrooms with a tub or shower","CO alarms near all sleeping areas in homes with fuel-burning appliances, fireplaces or attached garages","Permanent 'CAUTION: MULTIPLE SOURCES OF POWER' label within 18 inches of the main panel and meter if the home has a generator, solar panels, battery storage or other secondary power","GFCI outlets tested (bathrooms, kitchens, garages, basements, outside); defective ones replaced","Fireplace or wood stove over 3 years old needs a Level 2 (NFPA 211) safety certification before the certificate is issued","Oil or gas furnace must be inspected and certified safe by a heating professional before the certificate is issued","Bath exhaust fans working and free of lint; kitchen range hood filter clean and working","Electric power on for the inspection; an adult (18+) must be present (no lock box access)","All Building Division permits must be inspected and closed","Also: Open building permits: All permits with the Building Division must be inspected and closed (Building Division 609-799-0909 ext. 2545).","Also: Heating and fireplace certifications: A heating professional's certification for oil or gas furnaces, and a Level 2 NFPA 211 certification for fireplaces or wood stoves over 3 years old, must be received before the Housing Certificate of Occupancy is issued.","Also: Buyer's Acceptance Form: The Housing Division posts a Buyer's Acceptance Form online; the fee ordinance charges $150 for composing a buyer's acceptance agreement and performing a reinspection."]$j$::jsonb, $j$[{"label":"Resale inspection, single family or townhouse","amount":"$175.00"},{"label":"Resale inspection, condominium","amount":"$100.00"},{"label":"Reinspection, sold dwellings, second and later inspections","amount":"$100"},{"label":"Composing a buyer's acceptance agreement and performing a reinspection","amount":"$150"}]$j$::jsonb, $t$https://www.plainsboronj.com/FormCenter/Housing-Division-9/Resale-Inspection-Application-61$t$, $t$https://www.plainsboronj.com/156/Housing-Division$t$, $j$[{"url":"https://www.plainsboronj.com/Faq.aspx?TID=17","label":"Official source (plainsboronj.com)"},{"url":"https://www.plainsboronj.com/156/Housing-Division","label":"Official source (plainsboronj.com)"},{"url":"https://www.plainsboronj.com/FormCenter/Housing-Division-9/Resale-Inspection-Application-61","label":"Official source (plainsboronj.com)"},{"url":"https://www.plainsboronj.com/DocumentCenter/View/18601/Amending-Housing-Fee-Ordinance","label":"Official source (plainsboronj.com)"},{"url":"https://www.plainsboronj.com/512/Fee-Schedules","label":"Official source (plainsboronj.com)"},{"url":"https://www.plainsboronj.com/445/Resale-Inspection-Guidelines","label":"Official source (plainsboronj.com)"}]$j$::jsonb, $t$A housing inspection is required for the sale or rental of any residential dwelling unit.$t$, $t$0aa1ba574998ece9bf9136f5f5b987e696cebd94ef35c69f3b421047d5c1cf7f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":2,"fee_bad":0,"fee_unchecked":2,"quotes":19,"q_ok":16,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1218.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1218.json$t$, true),
  ($t$1218$t$, $t$Plainsboro Township$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Plainsboro Township Code Enforcement Department (Housing Division resale inspection; Fire Prevention Division is the fire code enforcing agency) (town fire bureau)","Contact: William Gorka, Fire Official · 609-799-0909 ext. 1208 · wgorka@plainsboronj.com","Fire official in the NJ state directory (town), updated 1/14/2026: William Gorka · (609) 799-0909 · wgorka@plainsboronj.com","The Housing resale inspection tests smoke alarms (interconnected alarms must all sound together; replace every 10 years) and checks CO alarms near sleeping areas","Homes with a generator, solar panels, battery storage or other secondary power need a permanent 'CAUTION: MULTIPLE SOURCES OF POWER' label within 18 inches of the main panel and meter","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.plainsboronj.com/155/Fire-Prevention-Division$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.plainsboronj.com/155/Fire-Prevention-Division","label":"Official source (plainsboronj.com)"},{"url":"https://www.plainsboronj.com/DocumentCenter/View/18602/Amending-Fire-Prevention-Ordinance","label":"Official source (plainsboronj.com)"},{"url":"https://www.plainsboronj.com/DocumentCenter/View/5182/Resale-Guidelines","label":"Official source (plainsboronj.com)"}]$j$::jsonb, $t$M Plainsboro Township$t$, $t$7137aced888499039bf00e2a7fafd63711187600e344cae3dbd42f70c59191b0$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":2,"fee_bad":0,"fee_unchecked":2,"quotes":19,"q_ok":16,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1218.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1218.json$t$, true),
  ($t$1219$t$, $t$Sayreville Borough$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Resale Compliance (Certificate of Residential Resale Compliance)$t$, $j$["Issued by: Department of Code Enforcement and Zoning, 49 Dolan Street","Contact: Joan Kemble, Clerk, Code Enforcement · 732-390-7077 · joank@sayreville.com","Apply: Code requires applying at least 10 business days before the sale; fees rise when the inspection is scheduled 10 or fewer business days before closing. Resale inspections are held Mondays and Wednesdays.","How to apply: Apply online through the Borough's FastTrackGov citizen portal ('Apply for a Rental or Resale Inspection'): create an account, complete the application, and the office emails the fee (usually within one business day). Pay online and request a preferred inspection date (resales on Monday and Wednesday); the office confirms by email.","Valid for: 60 days from the date of issue","Working smoke and CO alarms on every level and within 10 feet of sleeping areas (smoke: 10-year sealed or hardwired interconnected; CO under 7 years old; UL/ETL listed)","Exit doors open from inside without a key (no double-keyed deadbolts)","Handrail or guard on stairs with 3 or more steps or open sides over 30 inches","House numbers visible from the street and at least 4 inches tall","Walls, ceilings, floors, windows, doors and screens in good repair","Outlets, switches and boxes working with cover plates; no extension cords in place of permanent wiring","Bathroom window or exhaust fan; hot water at least 110 F; no leaks","Stove anti-tip device; only one kitchen in a single-family home","Basement, attic or garage bedrooms must meet habitable space rules (egress windows, two exits) or the inspection fails","Water heater, furnace, boiler and vents safe and working","Electric panel covered; secondary power source warning labels if the home has solar or a generator","All required permits for replaced appliances, systems and improvements obtained and closed by a licensed contractor ('as-is' sales are not exempt)","Roof, gutters, foundation, fireplace and chimney in good repair; yard clean and maintained","Pool over 18 inches deep fenced at least 48 inches high with self-closing, self-latching gate","Water curb stop must work; open permits and code issues resolved before the certificate is issued","Also: Open permits: Contact Code Enforcement when the home is first listed to check for open permits; unpermitted water heaters, furnaces or finished basements can hold up the certificate.","Also: Water curb stop: The water curb stop must be working; contact the Sayreville Water Department at 732-390-7060 before closing.","Also: 'As is' sales: Houses sold 'as-is' are not exempt from the permit requirements; the Director may issue an 'AS IS' letter ($300) for a property in such disrepair that compliance cannot be obtained, with conditions to be met within 30 days of closing."]$j$::jsonb, $j$[{"label":"Resale inspection scheduled more than 10 business days before closing","amount":"$100.00"},{"label":"Resale inspection scheduled 4 to 10 business days before closing","amount":"$150.00"},{"label":"First reinspection when inspection was scheduled 4 to 10 business days before closing","amount":"$75.00"},{"label":"Resale inspection scheduled less than 4 business days before closing","amount":"$200.00"},{"label":"First reinspection when inspection was scheduled less than 4 business days before closing","amount":"$100.00"},{"label":"Each additional reinspection after a denial","amount":"$150.00"},{"label":"'AS IS' letter in lieu of the certificate (at the Director's discretion)","amount":"$300.00"}]$j$::jsonb, $t$https://sayrevillenj.portal.fasttrackgov.com/Common/ApplicationLinks.aspx$t$, $t$https://www.sayreville.com/cn/webpage.cfm?tpid=18114$t$, $j$[{"url":"https://library.municode.com/nj/sayreville_borough/codes/code_of_ordinances?nodeId=CHXIIBUHO_12-3.5PRREREIN","label":"Official source (library.municode.com)"},{"url":"https://www.sayreville.com/FCpdf/Residential%20Resale%20and%20Rental%20Inspection%20Checklist%202025A%2Epdf","label":"Official source (sayreville.com)"},{"url":"https://www.sayreville.com/cn/webpage.cfm?tpid=18114","label":"Official source (sayreville.com)"},{"url":"https://www.sayreville.com/cn/contactinfo/?did=2629","label":"Official source (sayreville.com)"},{"url":"https://www.sayreville.com/FCpdf/Residential%20Resale%20Rental%20Applicant%20Instructions%2Epdf","label":"Official source (sayreville.com)"}]$j$::jsonb, $t$Certificate of Resale Compliance for all property at time of sale.$t$, $t$f37ae5d33bc6cf8d2778f92a740100ec9fdfb2748de0dd5f6c2fd9fe46b2727e$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":0,"fee_bad":0,"fee_unchecked":11,"quotes":18,"q_ok":12,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1219.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1219.json$t$, true),
  ($t$1219$t$, $t$Sayreville Borough$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Sayreville Bureau of Fire Prevention (Fire Official) (town fire bureau)","Contact: Kevin E. Krushinski, Fire Marshal / Fire Official · 732-390-7009 · fireprevention@sayreville.com","Apply: Schedule more than 10 business days before closing for the lowest fee","How to apply: The Borough's 'Selling Your Home' page lists the Fire Prevention Resale Checklist with the resale application steps (online portal). Questions: Fire Prevention, 49 Dolan Street, 732-390-7009.","Fire official in the NJ state directory (town), updated 6/4/2026: Kevin E Krushinski · (732) 390-7079 · fireprevention@sayreville.com","Standalone battery smoke alarms must be 10-year sealed units; smoke alarms must be less than 10 years old","Hardwired or interconnected alarms kept as installed; wireless interconnected alarms do not replace hardwired systems; repairs may need a licensed electrician","Alarms on every finished level, in basements (near the stairs), in finished attics, and outside each sleeping area within 10 feet of bedroom doors","CO alarms within 10 feet of all sleeping areas and less than 7 years old (or as the maker requires)","All alarms must carry a UL, ETL or equal testing-lab label; security-system detectors do not count","Fresh batteries in any alarm that uses replaceable batteries","'CAUTION: MULTIPLE SOURCES OF POWER' printed label within 18 inches of the main panel and meter for homes with solar, battery storage or generators","Portable fire extinguishers are no longer required (effective February 3, 2025)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, inspection scheduled more than 10 business days before closing","amount":"$50.00"},{"label":"Smoke/CO certificate, inspection scheduled 4 to 10 business days before closing ($75.00)","amount":"75.00"},{"label":"Smoke/CO certificate, inspection less than 4 business days before closing ($125.00)","amount":"125.00"},{"label":"Reinspection (missing, outdated or non-working equipment, or no one present) or cancellation with less than 24 hours notice","amount":"$50.00"}]$j$::jsonb, null, $t$https://www.sayreville.com/cn/webpage.cfm?tpid=8897$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.sayreville.com/FCpdf/Smoke%20Resale%20Requirements%202026%2Epdf","label":"Official source (sayreville.com)"},{"url":"https://www.sayreville.com/cn/webpage.cfm?tpid=8897","label":"Official source (sayreville.com)"},{"url":"https://library.municode.com/nj/sayreville_borough/codes/code_of_ordinances?nodeId=CHXVFIPR_15-1STUNFISAAC","label":"Official source (library.municode.com)"},{"url":"https://www.sayreville.com/cn/contactinfo/?did=2629","label":"Official source (sayreville.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$M Sayreville Borough$t$, $t$f0bf89bfbb71b3c871ad290185aae44d1b83fa08e37a26ccb3ed44cd7d8122cb$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":0,"fee_bad":0,"fee_unchecked":11,"quotes":18,"q_ok":12,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1219.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1219.json$t$, true),
  ($t$1220$t$, $t$South Amboy$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for Sale (resale certificate)$t$, $j$["Issued by: City of South Amboy Building Department","Contact: 732-525-5927","How to apply: Complete the City's 'Certificate of Occupancy for Sale' form (property, seller, buyer, estimated closing date, and the attorney holding escrow for outstanding municipal charges) and return it to the Building Department, 140 North Broadway, South Amboy, NJ 08879 (phone 732-525-5927, fax 732-727-6139). The application fee line on the form is filled in by the City; no amount is printed.","Full property maintenance inspection; the resale certificate is not issued unless the property is 100% compliant","Address numbers visible from the street; yard free of weeds and debris","Clear path to the electrical panel; all outlets, switches and junction boxes covered; no extension cords as permanent wiring","Combustibles at least 3 feet from furnace and water heater; access to the furnace room","Water heater with cold water shut-off and pressure relief valve with down spout; gas shut-off on gas heaters","Windows open easily and stay open; no cracked or broken glass; screens on door windows used for ventilation","Handrail on stairs more than 3 risers high; guardrails on open stairs, landings or balconies over 30 inches","Appliances and plumbing fixtures properly installed and working","Working smoke detector on each level including the basement; CO detector near all bedrooms","Work done without required permits must be permitted and all open permits finaled (fines up to $2,000 per week)","All utilities on at the time of inspection","Solid core door between garage and living area","Fire extinguisher (at least 2.5 lb.) mounted in the kitchen area (as printed on the City guideline sheet)","Also: Final sewer bill: If a final bill is needed for a closing, first final the water with Middlesex Water (732-634-1500), then send a copy of the final water bill with the attorney or title company contact to the Tax/Utility Collector (Joanne Katko, 732-525-5924); the final sewer takes 5 business days once all information is in.","Also: Outstanding municipal charges: The CO for Sale form asks for the attorney holding escrow for outstanding municipal charges (tax or sewer).","Also: Open permits: Work done without required permits must be permitted, and any outstanding permits must have final approvals."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.southamboynj.gov/_Content/pdf/forms/Certificate-of-Occupancy-for-Sale.pdf$t$, $t$https://www.southamboynj.gov/departments/code-enforcement$t$, $j$[{"url":"https://www.southamboynj.gov/_Content/pdf/forms/Certificate-of-Occupancy-for-Sale.pdf","label":"Official source (southamboynj.gov)"}]$j$::jsonb, $t$THIS FORM MUST COMPLETED AND RETURNED BEFORE CERTIFICATE OF OCCUPANCY IS ISSUED$t$, $t$43a162f3ea77a7d9387258b1e7bcd3a114fec844b4e520c2bc814b18edea2892$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":11,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1220.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1220.json$t$, true),
  ($t$1220$t$, $t$South Amboy$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Middlesex County Fire Marshal's Office","Contact: Michael Gallagher, Fire Official (Middlesex County Fire Marshal) · 732-316-7171 · mike.gallagher@co.middlesex.nj.us","Apply: Apply 10 or more business days before closing for the lowest County fee","How to apply: Complete the Middlesex County Fire Marshal's Smoke & Carbon Monoxide Detector Application and send it to the County Fire Marshal, 1001 Fire Academy Drive, Sayreville (firemarshal@co.middlesex.nj.us, 732-316-7171); make checks payable to the Office of the Fire Marshal. The only copy of the current County form found online is posted on the South River Borough site; South Amboy's own site posts no smoke form.","Fire official in the NJ state directory (county fire marshal), updated 11/13/2025: Michael Gallagher · (732) 316-7171 · mike.gallagher@co.middlesex.nj.us","City 'Fire Code' sheet (undated, in the CO for Sale packet): 10-year sealed battery smoke detector on each level including the basement, unless the home has original A/C powered single or multiple-station alarms","Smoke detectors in every separate sleeping area within 10 feet of each bedroom door; a loft or attic used as living space with 7 feet or more headroom often needs one","CO alarm near sleeping areas; combination smoke/CO units must be 10-year sealed battery units","Homes with a monitored alarm system: the owner must be able to give the alarm company name and silence and reset the alarm after the test","County Fire Marshal sheet: smoke alarms no older than 10 years; CO alarms no older than 5 years (or the maker's date); detector type depends on the year built (1990 and later: electric with battery backup, all interconnected, one in each bedroom); house numbers at least 4 inches; certificate valid 6 months","The same undated sheet lists fire extinguisher rules (2A-10B:C, 10 lb. or less, mounted within 10 feet of the kitchen, top no more than 5 feet above the floor, serviced or bought within 12 months); P.L.2025, c.19 removed the state extinguisher requirement, so confirm whether this still applies","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO inspection, 10 or more business days before closing (County Fire Marshal schedule, posted on the South River Borough site)","amount":"$50.00"},{"label":"Smoke/CO inspection, less than 10 business days before closing (County Fire Marshal schedule, posted on the South River Borough site)","amount":"$75.00"},{"label":"Smoke/CO inspection, less than 4 business days before closing (County Fire Marshal schedule, posted on the South River Borough site)","amount":"$125.00"},{"label":"Reinspection after a failed inspection (County Fire Marshal schedule, posted on the South River Borough site)","amount":"$20.00"},{"label":"Not present for a scheduled inspection without notice (County Fire Marshal schedule, posted on the South River Borough site)","amount":"$75.00"}]$j$::jsonb, $t$https://www.southrivernj.org/DocumentCenter/View/856/Smoke-Detector--Carbon-Monoxide-Detector-Inspection-PDF$t$, $t$https://www.southamboynj.gov/Page/fire-prevention$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.southamboynj.gov/Page/fire-prevention","label":"Official source (southamboynj.gov)"},{"url":"https://www.southamboynj.gov/Departments/fire","label":"Official source (southamboynj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://web.archive.org/web/20201128112400/http://www.middlesexcountynj.gov/Government/Departments/PSH/Documents/Fire-Marshal/Residential%20Smoke%20Detector%20and%20Carbon%20Monoxide%20Inspection%20Info%20and%20Application.pdf","label":"Official source (web.archive.org)"},{"url":"https://www.southrivernj.org/DocumentCenter/View/856/Smoke-Detector--Carbon-Monoxide-Detector-Inspection-PDF","label":"Official source (southrivernj.org)"}]$j$::jsonb, $t$C South Amboy City$t$, $t$f8560c3ce8e066cf065b58f88cb833a2d7bccbe920e1d29d2d25b36516d46466$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":11,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1220.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1220.json$t$, true),
  ($t$1221$t$, $t$South Brunswick Township$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale Certificate of Occupancy (RRCO)$t$, $j$["Issued by: Housing Officer, Planning and Zoning Office (Zoning Office)","Contact: Mike Proietti, Resale forms contact, Planning and Zoning (title not shown) · 732-329-4000 ext. 7228","How to apply: Apply online with the Township's Residential Resale Certificate of Occupancy form (pay by credit card or e-check), or use the PDF application and mail a check payable to South Brunswick Township to the Zoning Office, PO Box 190, Monmouth Junction, NJ 08852. The application is not processed until payment is received. After the home passes, call the Planning Office the next day for the certificate (certificates are not issued in the field).","Valid for: 120 days (one extension of up to 30 days may be granted)","General inspection of the visible parts of the home","No work done that needed a construction or zoning permit without one (for example replaced A/C, furnace or water heater, generator, radon system, addition, finished basement, fireplace or wood stove, shed over 200 sq ft, pool, hot tub, deck, gazebo)","No open permits or inspections on the property","No visible violations or unsafe conditions","Any unpermitted work must be permitted and inspected before the RRCO is issued, even if a prior owner did it","Also: Unpermitted work and open permits: The RRCO application asks about replaced A/C, furnace, water heater, generator, radon system, additions, finished basement, fireplace, sheds over 200 sq ft, pools, hot tubs, decks and gazebos; any done without permits must be permitted and inspected before the RRCO is issued, and permits and approvals are reported to the Tax Assessor.","Also: Buyer waiver: A buyer may take on the RRCO obligation with a written waiver (sample letter from the buyer's attorney to the Housing Officer); the home cannot be occupied until the RRCO or a new CO is issued."]$j$::jsonb, $j$[{"label":"RRCO, detached homes (1- to 4-family)","amount":"$150.00"},{"label":"RRCO, townhome or condominium","amount":"$125.00"}]$j$::jsonb, $t$https://sobrunswick.forms.govos.com/f/ResidentialCCO$t$, $t$https://southbrunswicknj.gov/planning/housing-forms/$t$, $j$[{"url":"https://library.municode.com/nj/south_brunswick_township/codes/code_of_ordinances?nodeId=CH22BUBURE_ARTXIRECEOC_S22-425RERECEOCRRRE","label":"Official source (library.municode.com)"},{"url":"https://southbrunswicknj.gov/wp-content/uploads/2024/06/RRCO-application-060524.pdf","label":"Official source (southbrunswicknj.gov)"},{"url":"https://southbrunswicknj.gov/planning/housing-forms/","label":"Official source (southbrunswicknj.gov)"},{"url":"https://southbrunswicknj.gov/building/","label":"Official source (southbrunswicknj.gov)"},{"url":"https://sobrunswick.forms.govos.com/f/ResidentialCCO","label":"Official source (sobrunswick.forms.govos.com)"},{"url":"https://library.municode.com/nj/south_brunswick_township/codes/code_of_ordinances?nodeId=CH22BUBURE_ARTXIRECEOC_S22-426FE","label":"Official source (library.municode.com)"}]$j$::jsonb, $t$No owner, agent or broker shall sell, transfer or grant with right of occupancy, whether or not for consideration, any residential dwelling, unit or premises on which a building is located and used for human occupancy, unless a residential resale certificate of occupancy is first obtained from the housing officer by use of the appropriate application and fees provided herein.$t$, $t$056cbb8a50f1aa1b0a689c769fe4e804c7b7244fa9d47a9c490dd5b864cb5f4f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":16,"q_ok":14,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1221.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1221.json$t$, true),
  ($t$1221$t$, $t$South Brunswick Township$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: South Brunswick Township Fire Safety Bureau (town fire bureau)","Contact: John J. Funcheon, Fire Marshal · 732-329-4000 ext. 7214 · jfuncheo@sbtnj.net","How to apply: Download the Application and Certification in Lieu of Inspection, check every box, have it notarized, and send it with a check or money order payable to 'South Brunswick Township' to the Fire Safety Bureau, 540 Ridge Road, P.O. Box 190, Monmouth Junction, NJ 08852. The certificate is emailed to the seller or the seller's representative.","Fire official in the NJ state directory (town), updated 6/4/2026: John J Funcheon · (732) 329-4000 · jfuncheo@sbtnj.net","Owner or authorized representative self-certifies on a notarized form (Application and Certification in Lieu of Inspection); no fire inspection visit","Smoke alarms on each level including the basement (not attic or crawl space) and outside each separate sleeping area within 10 feet of bedrooms","CO alarm(s) outside sleeping areas","All alarms working and within the maker's warranty; battery smoke alarms must be the 10-year sealed battery type","AC powered or interconnected alarms in homes built after January 1977 must be kept working","Certificate is not transferable; a new application is needed if the change of occupancy does not happen within 6 months","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate application (non-refundable)","amount":"$50"},{"label":"Smoke/CO certificate application fee in Township Code","amount":"$50.00"}]$j$::jsonb, $t$https://southbrunswicknj.gov/wp-content/uploads/2022/06/SMOKE_CERT_APP_AND_DIRECTIONS_2020_2-1.pdf$t$, $t$https://southbrunswicknj.gov/fire-safety/residential-information/$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://southbrunswicknj.gov/fire-safety/residential-information/","label":"Official source (southbrunswicknj.gov)"},{"url":"https://southbrunswicknj.gov/wp-content/uploads/2022/06/SMOKE_CERT_APP_AND_DIRECTIONS_2020_2-1.pdf","label":"Official source (southbrunswicknj.gov)"},{"url":"https://southbrunswicknj.gov/fire-safety/","label":"Official source (southbrunswicknj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://library.municode.com/nj/south_brunswick_township/codes/code_of_ordinances?nodeId=CH46FIPRPR_ARTIVFICO_DIV1GE_S46-104ADREINFE","label":"Official source (library.municode.com)"}]$j$::jsonb, $t$M South Brunswick Township$t$, $t$feee96a4219b95a2863f9ad9f30d524d51ac5b38e1bb5d659f44c802b4a377cb$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":16,"q_ok":14,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1221.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1221.json$t$, true),
  ($t$1222$t$, $t$South Plainfield Borough$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Municipal Compliance (Residential Resale or Tenant), for smoke and CO detectors and Certificate of Occupancy$t$, $j$["Issued by: Borough of South Plainfield Building Department","Contact: Dominic Demico Jr, Construction Official · 908-226-7645 · schedulemyinspection@southplainfieldnj.com","Apply: Certificates are generated within 2 business days after the inspection; do not schedule the closing until the certificate is issued and all open permits and violations are cleared","How to apply: Fill out the Certificate of Municipal Compliance packet (Inspection Request and House Evaluation forms) and submit it in person at the Building Department, 2480 Plainfield Avenue, with a check or money order payable to Borough of South Plainfield. Inspections are held 9:00 am to 12:00 pm, Monday to Friday. The certificate can be picked up or mailed.","Smoke detectors on each habitable level, on or within 6 inches of the ceiling (not in corners), and within 10 feet of the farthest bedroom door","10-year sealed battery smoke detectors; homes built after 1977 with AC or interwired detectors must keep that type; smoke detectors expire after 10 years","CO detectors near all bedrooms, no more than 10 feet from the farthest bedroom door (not inside a bedroom unless there is also one in the hall)","Alarm systems need annunciators within 10 feet of bedrooms and on each level; notify the alarm company before the test","2A-10B:C fire extinguisher, 10 lb. or less, within 10 feet of the kitchen in the path of egress, mounted with the maker's bracket, top no more than 5 feet above the floor (as printed on the June 2023 form)","Sump pump area open for inspection; sump pumps must not discharge into the sanitary sewer","Water heater/boiler discharge valve and any fire sprinkler system are checked","All open permits closed before the inspection; work found done without permits (pools, spas, decks, sheds, garage conversions, basement work, wood stoves, furnace or water heater replacement, central A/C, oil to gas, tank removal) carries a minimum $250 penalty","House Evaluation form: finished basement, A/C, furnace or boiler, generator, sump pump, water heater, deck, shed, pool and radon system (original or replaced)","Inspection may be refused if the property has health or safety issues; corrective action falls on the seller","Also: Open permits and unpermitted work: All open permits must be closed before the inspection; work found done without permits carries a minimum $250 penalty.","Also: Owner mailing address update: The packet includes a form to update the owner's tax and sewer mailing address."]$j$::jsonb, $j$[{"label":"1- to 4-family home or townhouse, per unit","amount":"$65.00"},{"label":"Condominium or multi-family, per unit","amount":"$50.00"},{"label":"1- to 4-family home or townhouse at a special time, per unit","amount":"$125.00"},{"label":"Condominium or multi-family at a special time, per unit","amount":"$100.00"},{"label":"Reprint of an issued certificate","amount":"$25.00"},{"label":"First reinspection for a failed or missed inspection, per unit","amount":"$35.00"},{"label":"Second reinspection for a failed or missed inspection (same as the first inspection fee)","amount":"$50.00 to $125.00 per unit"}]$j$::jsonb, $t$https://www.southplainfieldnj.com/spnj/Departments/Departments/Building%20Department/Forms/Permit%20Applications%20%26%20Forms/Certificate%20of%20Municipal%20Compliance%20%28Residential%20Resale%20or%20Tenant%29%2002-25-2025.pdf$t$, $t$https://www.southplainfieldnj.com/spnj/Departments/Departments/Building%20Department/$t$, $j$[{"url":"https://www.southplainfieldnj.com/spnj/Departments/Departments/Building%20Department/Forms/Permit%20Applications%20%26%20Forms/Certificate%20of%20Municipal%20Compliance%20%28Residential%20Resale%20or%20Tenant%29%2002-25-2025.pdf","label":"Official source (southplainfieldnj.com)"},{"url":"https://www.southplainfieldnj.com/spnj/Departments/Departments/Building%20Department/","label":"Official source (southplainfieldnj.com)"},{"url":"https://www.southplainfieldnj.com/spnj/Departments/Departments/Construction%20Officer/","label":"Official source (southplainfieldnj.com)"},{"url":"https://www.southplainfieldnj.com/spnj/Departments/Departments/Building%20Department/Forms/Smoke%20Detector%20Information.pdf","label":"Official source (southplainfieldnj.com)"}]$j$::jsonb, $t$CERTIFICATE OF MUNICIPAL COMPLIANCE For Smoke and Carbon Monoxide Detectors, Certificate of Occupancy$t$, $t$db82da0972704fa66833a563a7c6ffd011b47bbe051029a0a35a2d14218bb4b8$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1222.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1222.json$t$, true),
  ($t$1222$t$, $t$South Plainfield Borough$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of South Plainfield Building Department (issues the smoke/CO Certificate of Municipal Compliance) (town fire bureau)","Contact: Dominic Demico Jr, Construction Official · 908-226-7640 · schedulemyinspection@southplainfieldnj.com","Apply: Certificates are generated within 2 business days after the inspection","How to apply: Same packet and process as the town certificate: submit the Certificate of Municipal Compliance packet in person at the Building Department, 2480 Plainfield Avenue, with a check or money order.","Fire official in the NJ state directory, updated 1/20/2026: Michael Pellegrino · (908) 756-4761 · mpellegrino@southplainfieldnj.com","Smoke detectors on each habitable level and within 10 feet of the farthest bedroom door; 10-year sealed battery units unless the home has AC or interwired detectors (homes built after 1977 must keep that type); detectors expire after 10 years","CO detectors within 10 feet of the farthest bedroom door","Alarm system annunciators within 10 feet of bedrooms and on each level","The June 2023 form still requires a 2A-10B:C extinguisher (10 lb. or less, within 10 feet of the kitchen, mounted, top no higher than 5 feet); P.L.2025, c.19 removed the state extinguisher requirement, so confirm with the Building Department","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"1- to 4-family home or townhouse, per unit (same combined certificate as the town resale certificate; not charged twice)","amount":"$65.00"},{"label":"Condominium or multi-family, per unit (same combined certificate as the town resale certificate; not charged twice)","amount":"$50.00"},{"label":"1- to 4-family home or townhouse at a special time, per unit (same combined certificate as the town resale certificate; not charged twice)","amount":"$125.00"}]$j$::jsonb, $t$https://www.southplainfieldnj.com/spnj/Departments/Departments/Building%20Department/Forms/Permit%20Applications%20%26%20Forms/Certificate%20of%20Municipal%20Compliance%20%28Residential%20Resale%20or%20Tenant%29%2002-25-2025.pdf$t$, $t$https://www.southplainfieldnj.com/spnj/Departments/Departments/Building%20Department/$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.southplainfieldnj.com/spnj/Departments/Departments/Building%20Department/Forms/Permit%20Applications%20%26%20Forms/Certificate%20of%20Municipal%20Compliance%20%28Residential%20Resale%20or%20Tenant%29%2002-25-2025.pdf","label":"Official source (southplainfieldnj.com)"},{"url":"https://www.southplainfieldnj.com/spnj/Fire%20Marshal/","label":"Official source (southplainfieldnj.com)"}]$j$::jsonb, $t$F South Plainfield Borough$t$, $t$c4742b2fad46fa8e9e65d6b6853da6bd214a1dd3aa63600c5f0816a08fdfbe79$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1222.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1222.json$t$, true),
  ($t$1223$t$, $t$South River Borough$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale Certificate (Certificate of Continued Occupancy)$t$, $j$["Issued by: Code Enforcement / Property Maintenance, 48 Washington Street","Contact: Carolyn LaBella, Secretary, Zoning & Code Enforcement · 732-257-1999 ext. 503 · clabella@southrivernj.org","Apply: Close out open permits and get the County smoke/CO certificate first; the smoke certificate must be provided before or by the inspection date","How to apply: Complete the Borough's Application for Certificate of Continued Occupancy (check 'Resale', attach a property survey) and pay the non-refundable fee when you submit it, by check or money order payable to the Borough of South River (the older Residential Resale Certificate form also allows cash). Submit to Code Enforcement / Property Maintenance, 48 Washington Street, South River, NJ 08882.","Valid for: 60 days","Smoke/CO detector certificate from the fire prevention office provided before or by the inspection date","Electric, water and gas on; house numbers at least 4 inches with contrasting background","Metal dryer exhaust pipe with no screws; chimney certification for any fireplace or wood stove","Secure handrails and guards on stairs with 4 or more risers and landings over 30 inches; graspable handrail on one side","Steps, porches, sidewalks, curbs and aprons in safe condition; yard free of overgrowth","Interior clean (kitchen, cabinets, refrigerator, bath fixtures); stove anti-tip device; kitchen exhaust fan working","No plumbing leaks; sump pumps must not discharge into the sanitary sewer; water heater in good repair","Windows clean, uncracked, glazed, locking and operable with one hand, with screens; storm and screen doors with closers","Thumb-latch door locks only (no double-keyed deadbolts or hasps); privacy locks on bedrooms and bathrooms","No electrical hazards or extension cords as permanent wiring; covers on all switches and outlets; globes on light fixtures","Floor coverings secure and not worn; heating outlets and baseboard covers secured","Heating system safe and able to heat October 1 to May 1","Pools and pool barriers code compliant","Open Building/Construction permits inspected and closed; any work done without permits must be permitted and finaled before scheduling","Also: Open permits and unpermitted work: Outstanding Building/Construction permits must be inspected and closed, and any work done without permits must be permitted and finaled, before scheduling the Resale Certificate.","Also: Chimney certification: A chimney certification is required for any fireplace or wood burning stove.","Also: Property survey: Attach a copy of the property survey to a resale application."]$j$::jsonb, $j$[{"label":"Resale inspection, first inspection, per unit","amount":"$100.00"},{"label":"Resale inspection, second inspection, per unit","amount":"$100.00"},{"label":"Resale inspection, third inspection, per unit","amount":"$125.00"}]$j$::jsonb, $t$https://www.southrivernj.org/DocumentCenter/View/2296/Certificate-of-Continued-Occupancy-Application-PDF$t$, $t$https://www.southrivernj.org/211/Code-Enforcement$t$, $j$[{"url":"https://www.southrivernj.org/458/Building-Department-FAQs","label":"Official source (southrivernj.org)"},{"url":"https://www.southrivernj.org/DocumentCenter/View/2296/Certificate-of-Continued-Occupancy-Application-PDF","label":"Official source (southrivernj.org)"},{"url":"https://www.southrivernj.org/DocumentCenter/View/1960/Residential-Resale-Certificate-PDF","label":"Official source (southrivernj.org)"},{"url":"https://www.southrivernj.org/211/Code-Enforcement","label":"Official source (southrivernj.org)"}]$j$::jsonb, $t$The Township of South River does require a Certificate of Occupancy (CO) for the resale of a property.$t$, $t$5307282685dc3209297e759ffcef6631abceeab0b947f1fdadbf66e99882998f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":16,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1223.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1223.json$t$, true),
  ($t$1223$t$, $t$South River Borough$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Middlesex County Fire Marshal's Office","Contact: Michael Gallagher, Fire Official (Middlesex County Fire Marshal) · 732-316-7171 · mike.gallagher@co.middlesex.nj.us","Apply: Apply 10 or more business days before closing for the lowest fee","How to apply: Complete the Middlesex County Fire Marshal's Smoke & Carbon Monoxide Detector Application (posted on the Borough's Forms & Permits page) and send it to the County Fire Marshal, 1001 Fire Academy Drive, Sayreville (firemarshal@co.middlesex.nj.us, 732-316-7171). Make checks payable to the Office of the Fire Marshal. The certificate is issued right after a passed inspection.","Fire official in the NJ state directory (county fire marshal), updated 4/8/2020: Michael Gallagher · (732) 316-7171 · mike.gallagher@co.middlesex.nj.us","Smoke alarms on every level (basement, first floor, second floor; not crawl spaces or unfinished attics) and outside sleeping areas within 10 feet; basement alarm near the bottom of the stairs","Smoke alarms no older than 10 years (or the maker's expiration date); wall-mounted alarms 6 to 12 inches below the ceiling","CO alarm outside each separate sleeping area; the County sheet says CO alarms must not be older than 5 years or the maker's expiration date","Detector type by year built (County criteria sheet): before 1977 battery; 1977-1983 electric; 1984-1989 electric interconnected; 1990 and later electric with battery backup, all interconnected, including one in each bedroom","House numbers at least 4 inches high and visible from the street (2 inches on both sides of a curbside mailbox)","The County application and guideline sheet still list a fire extinguisher (2A:10B:C, 10 lb. or less, within 10 feet of the kitchen, top no more than 5 feet above the floor, tagged within 12 months or with a purchase receipt); P.L.2025, c.19 removed the state requirement, so confirm with the Fire Marshal","Certificate is issued right after the inspection and is valid for 6 months","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO inspection, 10 or more business days before closing","amount":"$50.00"},{"label":"Smoke/CO inspection, less than 10 business days before closing","amount":"$75.00"},{"label":"Smoke/CO inspection, less than 4 business days before closing","amount":"$125.00"},{"label":"Reinspection after a failed inspection","amount":"$20.00"},{"label":"Not present for a scheduled inspection without notice","amount":"$75.00"}]$j$::jsonb, $t$https://www.southrivernj.org/DocumentCenter/View/856/Smoke-Detector--Carbon-Monoxide-Detector-Inspection-PDF$t$, $t$https://www.southrivernj.org/310/Forms-Permits$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.southrivernj.org/310/Forms-Permits","label":"Official source (southrivernj.org)"},{"url":"https://www.southrivernj.org/DocumentCenter/View/856/Smoke-Detector--Carbon-Monoxide-Detector-Inspection-PDF","label":"Official source (southrivernj.org)"}]$j$::jsonb, $t$C South River Borough$t$, $t$77ebd718ed5ffe96a794f2345c64a48f3cc3d4d447d241d4a670b9d06ea12073$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":16,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1223.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1223.json$t$, true),
  ($t$1225$t$, $t$Woodbridge Township$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (Residential Sale & Refinance), 'Smoke Detector Inspection'$t$, $j$["Issued by: Bureau of Housing (Housing Department), Department of Planning and Development, One Main Street","Contact: Michael Logan, Head of Housing Department · 732-634-4500 ext. 6009","Apply: Apply more than 10 business days before the change of occupant for the lowest fee","How to apply: The form is not available online. Call the Bureau of Housing at 732-634-4500 ext. 6009 with the closing date, the buyer's name, current address, email and phone, the property address, and who will be at the inspection. You get an appointment date and an application number and are told how to pay; the 2021 sheet says exact cash or bank certified check only (no personal checks or money orders). The certificate is handed to the person who meets the inspector.","Valid for: 60 days from the date of inspection","Smoke detectors on every level, including at the foot of the basement stairs; UL listed; mounted with screws (no tape, Velcro, nails or picture hooks)","Battery smoke detectors must be the 10-year sealed-battery type (since 01/01/2019)","CO detectors within 10 feet of sleeping areas; UL listed; mounted with screws unless plug-in","Sanitary sewer discharge inspection: no floor drains (basement drains must be cemented over), sump pumps, or yard and driveway drains into the sanitary sewer; sewer trap caps not missing, loose or cracked","Fire extinguisher in or within 10 feet of the kitchen, mounted on the maker's bracket, 2 1/2 to 10 lb., rated 2A:10B:C or greater (as printed on the 2021 form)","All open building permits and violations closed before the inspector releases the certificate","Owner or a representative must be at the inspection; inspections are 9:00 am to 12:00 pm","Also: Sanitary sewer discharge inspection: Part of the Township Certificate of Compliance: floor drains must be cemented over, and sump pumps, yard or driveway drains may not discharge into the sanitary sewer; sewer trap caps must be intact.","Also: Open permits and violations: All open building permits and violations must be closed for the inspector to release the Certificate of Compliance.","Also: Refinance: The same Certificate of Compliance is also required for a refinance."]$j$::jsonb, $j$[{"label":"Certificate of Compliance (smoke/CO/extinguisher), requested more than 10 business days before change of occupant, per unit","amount":"$50.00"},{"label":"Certificate of Compliance, requested 4 to 10 business days before change of occupant, per unit","amount":"$70.00"},{"label":"Certificate of Compliance, requested fewer than 4 business days before change of occupant, per unit","amount":"$125.00"}]$j$::jsonb, null, $t$https://www.twp.woodbridge.nj.us/982/Housing-Forms$t$, $j$[{"url":"https://www.twp.woodbridge.nj.us/DocumentCenter/View/15589/Certificate-of-Compliance-2021","label":"Official source (twp.woodbridge.nj.us)"},{"url":"https://www.twp.woodbridge.nj.us/DocumentCenter/View/15497/Instructions-for-Residential-Resale-and-Rentals","label":"Official source (twp.woodbridge.nj.us)"},{"url":"https://www.twp.woodbridge.nj.us/982/Housing-Forms","label":"Official source (twp.woodbridge.nj.us)"},{"url":"https://www.twp.woodbridge.nj.us/m/directory/department?did=47","label":"Official source (twp.woodbridge.nj.us)"}]$j$::jsonb, $t$Residential properties being sold or refinanced must meet all the requirements of the Township Smoke Detector, Carbon Monoxide Detector, Sanitary Sewer Discharge and Fire Extinguisher Ordinances.$t$, $t$50cec1e5e3a693b1c1e99b14b27ea4fba972e2147733779dbafedc3134c27b75$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1225.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1225.json$t$, true),
  ($t$1225$t$, $t$Woodbridge Township$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Woodbridge Township Bureau of Housing (issues the smoke/CO Certificate of Compliance township-wide) (town fire bureau)","Contact: Michael Logan, Head of Housing Department · 732-634-4500 ext. 6009","Apply: Apply more than 10 business days before the change of occupant for the lowest fee","How to apply: Call the Bureau of Housing at 732-634-4500 ext. 6009 to schedule (the form is not online); pay by exact cash or bank certified check per the 2021 sheet.","Fire official in the NJ state directory (fire district), updated 2/23/2022: William R Schleck · (732) 388-6666 · fireprevention@coloniafd.org","Smoke detectors on every level, including at the foot of the basement stairs; UL listed; mounted with screws; battery units must be 10-year sealed","CO detectors within 10 feet of sleeping areas; UL listed; mounted with screws unless plug-in","The 2021 Township form still lists a fire extinguisher (2A:10B:C, 2 1/2 to 10 lb., in or within 10 feet of the kitchen, mounted); P.L.2025, c.19 removed the state requirement, so confirm with the Bureau of Housing","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Compliance (smoke/CO/extinguisher), requested more than 10 business days before change of occupant, per unit (same Certificate of Compliance as the town certificate; not charged twice)","amount":"$50.00"},{"label":"Certificate of Compliance, requested 4 to 10 business days before change of occupant, per unit (same Certificate of Compliance as the town certificate; not charged twice)","amount":"$70.00"},{"label":"Certificate of Compliance, requested fewer than 4 business days before change of occupant, per unit (same Certificate of Compliance as the town certificate; not charged twice)","amount":"$125.00"}]$j$::jsonb, null, $t$https://www.twp.woodbridge.nj.us/982/Housing-Forms$t$, $j$[{"url":"https://www.twp.woodbridge.nj.us/DocumentCenter/View/15589/Certificate-of-Compliance-2021","label":"Official source (twp.woodbridge.nj.us)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.avenelfire.org/index.php/2017-12-27-17-48-57/bureau-of-fire-prevention","label":"Official source (avenelfire.org)"}]$j$::jsonb, $t$FEES: The request fee for a certificate of smoke detector, carbon monoxide alarm and portable fire extinguisher compliance as required by N.J.A.C. 5:70-2.3, shall be based upon the amount of time remaining before the change of occupants is expected as follows:$t$, $t$2e6606db03d7ee992fffb3cc0e5ec6ee98bd4db89f3f62d06ade618c7a779e07$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1225.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1225.json$t$, true)
